// Human readable byte sizes: parsing and formatting.

const LN_KIB: f64 = 6.931_471_805_599_453;

fn unit_multiplier(unit: &str) -> Option<u64> {
    let u = unit.to_ascii_lowercase();
    let v: u64 = match u.as_str() {
        "b" => 1,
        "k" | "kb" => 1_000,
        "ki" | "kib" => 1 << 10,
        "m" | "mb" => 1_000_000,
        "mi" | "mib" => 1 << 20,
        "g" | "gb" => 1_000_000_000,
        "gi" | "gib" => 1 << 30,
        "t" | "tb" => 1_000_000_000_000,
        "ti" | "tib" => 1 << 40,
        "p" | "pb" => 1_000_000_000_000_000,
        "pi" | "pib" => 1 << 50,
        "e" | "eb" => 1_000_000_000_000_000_000,
        "ei" | "eib" => 1 << 60,
        _ => return None,
    };
    Some(v)
}

pub fn parse_bytesize(value: &str) -> Result<u64, String> {
    if let Ok(v) = value.parse::<u64>() {
        return Ok(v);
    }
    let number: String = value
        .chars()
        .take_while(|c| c.is_ascii_digit() || *c == '.')
        .collect();
    match number.parse::<f64>() {
        Ok(v) => {
            let suffix = value[number.len()..].trim_start_matches(char::is_whitespace);
            match unit_multiplier(suffix) {
                Some(u) => Ok((v * u as f64) as u64),
                None => Err(format!(
                    "couldn't parse {:?} into a known SI unit, Failed to parse unit \"{}\"",
                    suffix, suffix
                )),
            }
        }
        Err(e) => Err(format!("couldn't parse {:?} into a ByteSize, {}", value, e)),
    }
}

pub fn format_size(bytes: u64) -> String {
    if bytes < 1024 {
        return format!("{} B", bytes);
    }
    let size = bytes as f64;
    let mut exp = (size.ln() / LN_KIB) as usize;
    if exp == 0 {
        exp = 1;
    }
    if exp > 6 {
        exp = 6;
    }
    let prefix = b"KMGTPE"[exp - 1] as char;
    format!("{:.1} {}iB", size / (1024u64.pow(exp as u32) as f64), prefix)
}
EOF"}

