{"command":"cat > /workspace/src/main.rs <<'EOF'
mod caesium;
mod cli;
mod codecs;
mod size;

use cli::{MinSavings, Options, OutputFormat, Overwrite};
use std::fs;
use std::io::Read;
use std::path::{Component, Path, PathBuf};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Mutex;

#[derive(Clone, Copy, PartialEq, Eq)]
enum Status {
    Success,
    Skipped,
    Error,
}

struct FileResult {
    status: Status,
    input: String,
    output: String,
    original_size: u64,
    compressed_size: u64,
    message: String,
}

pub static PANIC_NOTE_SHOWN: Mutex<bool> = Mutex::new(false);

fn is_supported_image(path: &Path) -> bool {
    let mut f = match fs::File::open(path) {
        Ok(f) => f,
        Err(_) => return false,
    };
    let mut buf = [0u8; 16];
    if f.read_exact(&mut buf).is_err() {
        return false;
    }
    codecs::detect_format(&buf).is_some()
}

fn walk_dir(dir: &Path, recursive: bool, out: &mut Vec<PathBuf>) {
    let rd = match fs::read_dir(dir) {
        Ok(r) => r,
        Err(_) => return,
    };
    for entry in rd.flatten() {
        let path = entry.path();
        let ft = match entry.file_type() {
            Ok(t) => t,
            Err(_) => continue,
        };
        if ft.is_dir() {
            if recursive {
                walk_dir(&path, recursive, out);
            }
            continue;
        }
        if path.is_file() && is_supported_image(&path) {
            out.push(path);
        }
    }
}

fn collect_files(inputs: &[PathBuf], recursive: bool) -> Vec<PathBuf> {
    let mut files = Vec::new();
    for input in inputs {
        if input.is_dir() {
            walk_dir(input, recursive, &mut files);
        } else if input.is_file() && is_supported_image(input) {
            files.push(input.clone());
        }
    }
    files
}

fn common_prefix(a: &Path, b: &Path) -> PathBuf {
    let mut res = PathBuf::new();
    for (x, y) in a.components().zip(b.components()) {
        if x == y {
            res.push(x.as_os_str());
        } else {
            break;
        }
    }
    res
}

fn compute_base_path(files: &[PathBuf]) -> Option<PathBuf> {
    let mut base: Option<PathBuf> = None;
    for f in files {
        let abs = match std::path::absolute(f) {
            Ok(a) => a,
            Err(_) => continue,
        };
        let parent = match abs.parent() {
            Some(p) => p.to_path_buf(),
            None => continue,
        };
        base = Some(match base {
            None => parent,
            Some(b) => common_prefix(&b, &parent),
        });
    }
    base
}

fn output_extension(opts: &Options, input: &Path) -> String {
    match opts.format {
        OutputFormat::Original => input
            .extension()
            .map(|e| e.to_string_lossy().to_string())
            .unwrap_or_default(),
        OutputFormat::Jpeg => "jpg".to_string(),
        OutputFormat::Png => "png".to_string(),
        OutputFormat::Gif => "gif".to_string(),
        OutputFormat::Webp => "webp".to_string(),
        OutputFormat::Tiff => "tiff".to_string(),
    }
}

fn compute_output_path(input: &Path, opts: &Options, base: &Path) -> Option<PathBuf> {
    let stem = input.file_stem()?.to_string_lossy().to_string();
    let mut name = stem;
    if let Some(s) = &opts.suffix {
        name.push_str(s);
    }
    let ext = output_extension(opts, input);
    if !ext.is_empty() {
        name.push('.');
        name.push_str(&ext);
    }
    let dir: PathBuf = if opts.same_folder_as_input {
        let parent = input.parent()?;
        if opts.keep_structure {
            std::path::absolute(parent).ok()?
        } else {
            parent.to_path_buf()
        }
    } else {
        let out = opts.output.clone()?;
        if opts.keep_structure {
            let parent = input.parent()?;
            let abs = std::path::absolute(parent).ok()?;
            let rel = abs.strip_prefix(base).ok()?;
            out.join(rel)
        } else {
            out
        }
    };
    if !opts.dry_run && !dir.exists() {
        fs::create_dir_all(&dir).ok()?;
    }
    Some(dir.join(name))
}

fn savings_message(original: u64, compressed: u64, min: &MinSavings) -> Option<String> {
    let saved = original.saturating_sub(compressed);
    match min {
        MinSavings::Percent(p) => {
            let pct = if original > 0 {
                saved as f64 / original as f64 * 100.0
            } else {
                0.0
            };
            if pct <= *p {
                Some(format!(
                    "Insufficient savings: {:.2}% < {:.2}%, skipped",
                    pct, p
                ))
            } else {
                None
            }
        }
        MinSavings::Bytes(b) => {
            if saved <= *b {
                Some(format!(
                    "Insufficient savings: {} < {}, skipped",
                    size::format_size(saved),
                    size::format_size(*b)
                ))
            } else {
                None
            }
        }
    }
}

fn process_file(input: &Path, opts: &Options, base: &Path, single: bool) -> FileResult {
    let original_size = fs::metadata(input).map(|m| m.len()).unwrap_or(0);
    let mut res = FileResult {
        status: Status::Error,
        input: input.display().to_string(),
        output: String::new(),
        original_size,
        compressed_size: 0,
        message: String::new(),
    };
    let out_path = match compute_output_path(input, opts, base) {
        Some(p) => p,
        None => {
            res.message = "Error setting up output path".to_string();
            return res;
        }
    };
    res.output = out_path.display().to_string();
    let exists = out_path.exists();
    if exists && opts.overwrite == Overwrite::Never {
        res.status = Status::Skipped;
        res.compressed_size = original_size;
        res.message = "File already exists, skipped due overwrite policy".to_string();
        return res;
    }
    if opts.dry_run {
        res.status = Status::Success;
        res.compressed_size = original_size;
        return res;
    }
    let data = match fs::read(input) {
        Ok(d) => d,
        Err(_) => {
            res.message = "Error reading input file".to_string();
            return res;
        }
    };
    let input_meta = fs::metadata(input).ok();
    let compressed = match caesium::process(&data, opts, single) {
        Ok(c) => c,
        Err(e) => {
            res.message = format!("Error compressing file: {} [{}]", e.message, e.code);
            return res;
        }
    };
    let new_size = compressed.len() as u64;
    if let Some(ms) = &opts.min_savings {
        if let Some(msg) = savings_message(original_size, new_size, ms) {
            res.status = Status::Skipped;
            res.compressed_size = original_size;
            res.message = msg;
            return res;
        }
    }
    if exists && opts.overwrite == Overwrite::Bigger {
        let existing = fs::metadata(&out_path).map(|m| m.len()).unwrap_or(0);
        if existing <= new_size {
            res.status = Status::Skipped;
            res.compressed_size = original_size;
            res.message = "File already exists, skipped due overwrite policy".to_string();
            return res;
        }
    }
    let mut f = match fs::File::create(&out_path) {
        Ok(f) => f,
