// WebP support through the system libwebp shared library (loaded at runtime).
use super::Image;
use std::ffi::{c_void, CString};
use std::os::raw::{c_char, c_int};
use std::sync::OnceLock;

extern "C" {
    fn dlopen(filename: *const c_char, flag: c_int) -> *mut c_void;
    fn dlsym(handle: *mut c_void, symbol: *const c_char) -> *mut c_void;
}

type DecodeFn = unsafe extern "C" fn(*const u8, usize, *mut c_int, *mut c_int) -> *mut u8;
type EncodeFn = unsafe extern "C" fn(*const u8, c_int, c_int, c_int, f32, *mut *mut u8) -> usize;
type EncodeLLFn = unsafe extern "C" fn(*const u8, c_int, c_int, c_int, *mut *mut u8) -> usize;
type FreeFn = unsafe extern "C" fn(*mut c_void);
type FeaturesFn = unsafe extern "C" fn(*const u8, usize, *mut BitstreamFeatures, c_int) -> c_int;

#[repr(C)]
#[derive(Default)]
struct BitstreamFeatures {
    width: c_int,
    height: c_int,
    has_alpha: c_int,
    has_animation: c_int,
    format: c_int,
    pad: [u32; 5],
}

struct Lib {
    decode_rgb: DecodeFn,
    decode_rgba: DecodeFn,
    encode_rgb: EncodeFn,
    encode_rgba: EncodeFn,
    encode_ll_rgb: EncodeLLFn,
    encode_ll_rgba: EncodeLLFn,
    free: Option<FreeFn>,
    features: FeaturesFn,
}

unsafe impl Send for Lib {}
unsafe impl Sync for Lib {}

fn load() -> Option<Lib> {
    let names = [
        "libwebp.so.7",
        "libwebp.so",
        "/usr/lib/x86_64-linux-gnu/libwebp.so.7",
        "/usr/lib64/libwebp.so.7",
        "/usr/lib/libwebp.so.7",
        "/usr/lib/aarch64-linux-gnu/libwebp.so.7",
    ];
    unsafe {
        let mut h = std::ptr::null_mut();
        for n in names.iter() {
            let c = CString::new(*n).unwrap();
            h = dlopen(c.as_ptr(), 2);
            if !h.is_null() {
                break;
            }
        }
        if h.is_null() {
            return None;
        }
        let sym = |name: &str| -> Option<*mut c_void> {
            let c = CString::new(name).unwrap();
            let p = dlsym(h, c.as_ptr());
            if p.is_null() {
                None
            } else {
                Some(p)
            }
        };
        Some(Lib {
            decode_rgb: std::mem::transmute::<*mut c_void, DecodeFn>(sym("WebPDecodeRGB")?),
            decode_rgba: std::mem::transmute::<*mut c_void, DecodeFn>(sym("WebPDecodeRGBA")?),
            encode_rgb: std::mem::transmute::<*mut c_void, EncodeFn>(sym("WebPEncodeRGB")?),
            encode_rgba: std::mem::transmute::<*mut c_void, EncodeFn>(sym("WebPEncodeRGBA")?),
            encode_ll_rgb: std::mem::transmute::<*mut c_void, EncodeLLFn>(sym("WebPEncodeLosslessRGB")?),
            encode_ll_rgba: std::mem::transmute::<*mut c_void, EncodeLLFn>(sym("WebPEncodeLosslessRGBA")?),
            free: sym("WebPFree").map(|p| std::mem::transmute::<*mut c_void, FreeFn>(p)),
            features: std::mem::transmute::<*mut c_void, FeaturesFn>(sym("WebPGetFeaturesInternal")?),
        })
    }
}

fn lib() -> Option<&'static Lib> {
    static LIB: OnceLock<Option<Lib>> = OnceLock::new();
    LIB.get_or_init(load).as_ref()
}

pub fn available() -> bool {
    lib().is_some()
}

pub struct Features {
    pub width: u32,
    pub height: u32,
    pub has_alpha: bool,
    pub has_animation: bool,
}

pub fn features(data: &[u8]) -> Option<Features> {
    let l = lib()?;
    let mut f = BitstreamFeatures::default();
    let r = unsafe { (l.features)(data.as_ptr(), data.len(), &mut f, 0x0209) };
    if r != 0 {
        return None;
    }
    Some(Features {
        width: f.width as u32,
        height: f.height as u32,
        has_alpha: f.has_alpha != 0,
        has_animation: f.has_animation != 0,
    })
}

/// Decode a still WebP image. Returns RGB or RGBA depending on the alpha flag.
pub fn decode(data: &[u8]) -> Option<Image> {
    let l = lib()?;
    let f = features(data)?;
    if f.has_animation {
        return None;
    }
    let mut w: c_int = 0;
    let mut h: c_int = 0;
    let ch = if f.has_alpha { 4 } else { 3 };
    let p = unsafe {
        if f.has_alpha {
            (l.decode_rgba)(data.as_ptr(), data.len(), &mut w, &mut h)
        } else {
            (l.decode_rgb)(data.as_ptr(), data.len(), &mut w, &mut h)
        }
    };
    if p.is_null() {
        return None;
    }
    let n = (w as usize) * (h as usize) * ch;
    let v = unsafe { std::slice::from_raw_parts(p, n).to_vec() };
    free(p);
    Some(Image::new(w as u32, h as u32, ch as u8, v))
}

fn free(p: *mut u8) {
    if let Some(l) = lib() {
        unsafe {
            if let Some(f) = l.free {
                f(p as *mut c_void);
            }
        }
    }
}

/// Encode RGB/RGBA pixels. quality None => lossless.
pub fn encode(img: &Image, quality: Option<f32>) -> Option<Vec<u8>> {
    let l = lib()?;
    let img = match img.channels {
        3 | 4 => img.clone(),
        2 => img.to_rgba(),
        _ => img.to_rgb(),
    };
    let mut out: *mut u8 = std::ptr::null_mut();
    let w = img.width as c_int;
    let h = img.height as c_int;
    let stride = (img.width * img.channels as u32) as c_int;
    let size = unsafe {
        match (img.channels, quality) {
            (4, Some(q)) => (l.encode_rgba)(img.data.as_ptr(), w, h, stride, q, &mut out),
            (_, Some(q)) => (l.encode_rgb)(img.data.as_ptr(), w, h, stride, q, &mut out),
            (4, None) => (l.encode_ll_rgba)(img.data.as_ptr(), w, h, stride, &mut out),
            (_, None) => (l.encode_ll_rgb)(img.data.as_ptr(), w, h, stride, &mut out),
        }
    };
    if out.is_null() || size == 0 {
        return None;
    }
    let v = unsafe { std::slice::from_raw_parts(out, size).to_vec() };
    free(out);
    Some(v)
}
