// Image containers and format codecs.
pub mod deflate;
pub mod gif;
pub mod jpeg;
pub mod jpegenc;
pub mod png;
pub mod quant;
pub mod resize;
pub mod tiff;
pub mod webp;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Format {
    Jpeg,
    Png,
    Gif,
    Webp,
    Tiff,
}

pub fn detect_format(buf: &[u8]) -> Option<Format> {
    if buf.len() >= 3 && buf[0] == 0xFF && buf[1] == 0xD8 && buf[2] == 0xFF {
        return Some(Format::Jpeg);
    }
    if buf.len() >= 4 && buf[0] == 0x89 && buf[1] == b'P' && buf[2] == b'N' && buf[3] == b'G' {
        return Some(Format::Png);
    }
    if buf.len() >= 3 && &buf[0..3] == b"GIF" {
        return Some(Format::Gif);
    }
    if buf.len() >= 12 && &buf[8..12] == b"WEBP" {
        return Some(Format::Webp);
    }
    None
}

