#[derive(Clone)]
struct Huff {
    lookup: Vec<(u8, u8)>, // 9-bit fast lookup: (len, value)
    maxcode: [i32; 18],
    valoffset: [i32; 18],
    vals: Vec<u8>,
}

impl Huff {
    fn new(counts: &[u8; 16], vals: &[u8]) -> Huff {
        let mut huffsize = Vec::new();
        for (l, &c) in counts.iter().enumerate() {
            for _ in 0..c {
                huffsize.push((l + 1) as u8);
            }
        }
        let mut huffcode = Vec::new();
        let mut code: u32 = 0;
        let mut si = if huffsize.is_empty() { 0 } else { huffsize[0] };
        let mut k = 0;
        while k < huffsize.len() {
            while k < huffsize.len() && huffsize[k] == si {
                huffcode.push(code);
                code += 1;
                k += 1;
            }
            code <<= 1;
            si += 1;
        }
        let mut maxcode = [-1i32; 18];
        let mut valoffset = [0i32; 18];
        let mut p = 0usize;
        for l in 1..=16 {
            let c = counts[l - 1] as usize;
            if c > 0 {
                valoffset[l] = p as i32 - huffcode[p] as i32;
                p += c;
                maxcode[l] = huffcode[p - 1] as i32;
            } else {
                maxcode[l] = -1;
            }
        }
        maxcode[17] = 0x7fffffff;
        let mut lookup = vec![(0u8, 0u8); 512];
        for (i, (&s, &c)) in huffsize.iter().zip(huffcode.iter()).enumerate() {
            if s <= 9 {
                let shift = 9 - s;
                let base = (c << shift) as usize;
                for j in 0..(1usize << shift) {
                    lookup[base + j] = (s, vals[i]);
                }
            }
        }
        Huff { lookup, maxcode, valoffset, vals: vals.to_vec() }
    }
}

struct BitReader<'a> {
    data: &'a [u8],
    pos: usize,
    acc: u64,
    nbits: u32,
    hit_marker: bool,
    pub eof_warned: bool,
}

impl<'a> BitReader<'a> {
    fn new(data: &'a [u8], pos: usize) -> Self {
        BitReader { data, pos, acc: 0, nbits: 0, hit_marker: false, eof_warned: false }
    }
    fn fill(&mut self) {
        while self.nbits <= 56 {
            let mut byte = 0u8;
            if !self.hit_marker && self.pos < self.data.len() {
                let b = self.data[self.pos];
                if b == 0xFF {
                    // look at next
                    let mut q = self.pos + 1;
                    while q < self.data.len() && self.data[q] == 0xFF {
                        q += 1;
                    }
                    if q < self.data.len() && self.data[q] == 0x00 {
                        byte = 0xFF;
                        self.pos = q + 1;
                    } else {
                        self.hit_marker = true;
                        if q >= self.data.len() {
                            self.eof_warned = true;
                        }
                    }
                } else {
                    byte = b;
                    self.pos += 1;
                }
            } else if !self.hit_marker {
                self.eof_warned = true;
                self.hit_marker = true;
            }
            self.acc |= (byte as u64) << (56 - self.nbits);
            self.nbits += 8;
        }
    }
    #[inline]
    fn get_bits(&mut self, n: u32) -> u32 {
        if n == 0 {
            return 0;
        }
        if self.nbits < n {
            self.fill();
        }
        let v = (self.acc >> (64 - n)) as u32;
        self.acc <<= n;
        self.nbits -= n;
        v
    }
    #[inline]
    fn get_bit(&mut self) -> u32 {
        self.get_bits(1)
    }
    #[inline]
    fn peek9(&mut self) -> u32 {
        if self.nbits < 9 {
            self.fill();
        }
        (self.acc >> 55) as u32
    }
    fn decode(&mut self, h: &Huff) -> u8 {
        let p = self.peek9() as usize;
        let (len, val) = h.lookup[p];
        if len > 0 {
            self.acc <<= len;
            self.nbits -= len as u32;
            return val;
        }
        let mut code = self.get_bits(9) as i32;
        let mut l = 9usize;
        while l < 17 && code > h.maxcode[l] {
            code = (code << 1) | self.get_bit() as i32;
            l += 1;
        }
        if l > 16 {
            return 0; // corrupt data
        }
        let idx = (code + h.valoffset[l]) as usize;
        if idx < h.vals.len() {
            h.vals[idx]
        } else {
            0
        }
    }
    fn receive_extend(&mut self, s: u32) -> i32 {
        if s == 0 {
            return 0;
        }
        if s > 16 {
            return 0;
        }
        let v = self.get_bits(s) as i32;
        if v < (1 << (s - 1)) {
            v - (1 << s) + 1
        } else {
            v
        }
    }
    fn reset(&mut self) {
        self.acc = 0;
        self.nbits = 0;
    }
    /// Handle a restart marker: discard remaining bits and skip RSTn.
    fn restart(&mut self) {
        self.reset();
        if self.hit_marker {
            // marker located at self.pos (0xFF...)
            let mut q = self.pos;
            while q < self.data.len() && self.data[q] == 0xFF {
                q += 1;
            }
            if q < self.data.len() && (0xD0..=0xD7).contains(&self.data[q]) {
                self.pos = q + 1;
                self.hit_marker = false;
            }
        } else {
            // search for the marker
            let mut q = self.pos;
            while q + 1 < self.data.len() {
                if self.data[q] == 0xFF && (0xD0..=0xD7).contains(&self.data[q + 1]) {
                    self.pos = q + 2;
                    break;
                }
                if self.data[q] == 0xFF && self.data[q + 1] != 0 && self.data[q + 1] != 0xFF {
                    self.pos = q;
                    self.hit_marker = true;
                    break;
                }
                q += 1;
            }
        }
    }
    /// position of the next marker after the entropy data
    fn marker_pos(&self) -> usize {
        let mut q = self.pos;
        loop {
            if q + 1 >= self.data.len() {
                return self.data.len();
            }
            if self.data[q] == 0xFF && self.data[q + 1] != 0 && !(0xD0..=0xD7).contains(&self.data[q + 1]) && self.data[q + 1] != 0xFF {
                return q;
            }
            q += 1;
        }
    }
}

fn be16(d: &[u8], p: usize) -> usize {
    ((d[p] as usize) << 8) | d[p + 1] as usize
}

pub fn read_header_dims(data: &[u8]) -> Option<(usize, usize)> {
    let mut p = 2;
    while p + 4 <= data.len() {
        if data[p] != 0xFF {
            p += 1;
            continue;
        }
        let m = data[p + 1];
        if m == 0xFF {
            p += 1;
            continue;
        }
        if m == 0xD8 || (0xD0..=0xD7).contains(&m) || m == 0x01 {
            p += 2;
            continue;
        }
        let len = be16(data, p + 2);
        if matches!(m, 0xC0..=0xC3 | 0xC5..=0xC7 | 0xC9..=0xCB | 0xCD..=0xCF) {
            if p + 9 > data.len() {
                return None;
            }
            let h = be16(data, p + 5);
            let w = be16(data, p + 7);
            return Some((w, h));
        }
        p += 2 + len;
    }
    None
}

/// Decode JPEG into coefficients. Errors use libjpeg-like message codes.
pub fn decode_coefficients(data: &[u8]) -> Result<JpegData, JpegError> {
    let n = data.len();
    if n < 2 || data[0] != 0xFF || data[1] != 0xD8 {
        return Err(JpegError(55));
    }
    let mut p = 2usize;
    let mut qtables: [Option<[u16; 64]>; 4] = [None, None, None, None];
    let mut dc_tables: [Option<Huff>; 4] = [None, None, None, None];
    let mut ac_tables: [Option<Huff>; 4] = [None, None, None, None];
    let mut markers = Vec::new();
    let mut jfif = None;
    let mut adobe = None;
    let mut frame: Option<JpegData> = None;
    let mut restart_interval = 0usize;
    // progressive: track which coefficient bits have been seen
    loop {
        // find marker
        while p < n && data[p] != 0xFF {
            p += 1;
        }
        while p < n && data[p] == 0xFF {
            p += 1;
        }
        if p >= n {
            // premature end: act as EOI
            break;
        }
        let m = data[p];
        p += 1;
        if m == 0xD9 {
            break;
        }
        if (0xD0..=0xD7).contains(&m) || m == 0x01 {
            continue;
        }
        if p + 2 > n {
            break;
        }
        let len = be16(data, p);
        if len < 2 {
            return Err(JpegError(12));
        }
        if p + len > n {
            // truncated segment
            if m == 0xDA || (m >= 0xE0 && m <= 0xEF) || m == 0xFE {
                break;
            }
            break;
        }
        let seg = &data[p + 2..p + len];
        match m {
            0xE0..=0xEF | 0xFE => {
                if m == 0xE0 && seg.len() >= 14 && &seg[0..5] == b"JFIF\0" {
                    jfif = Some(JfifInfo {
                        major: seg[5],
                        minor: seg[6],
                        unit: seg[7],
                        xd: ((seg[8] as u16) << 8) | seg[9] as u16,
                        yd: ((seg[10] as u16) << 8) | seg[11] as u16,
                    });
                }
                if m == 0xEE && seg.len() >= 12 && &seg[0..5] == b"Adobe" {
                    adobe = Some(seg[11]);
                }
                markers.push((m, seg.to_vec()));
            }
            0xDB => {
                let mut q = 0;
                while q < seg.len() {
                    let pq = seg[q] >> 4;
                    let tq = (seg[q] & 15) as usize;
                    q += 1;
                    if tq > 3 {
                        return Err(JpegError(32));
                    }
                    let mut t = [0u16; 64];
                    for i in 0..64 {
                        let v = if pq != 0 {
                            if q + 1 >= seg.len() + 1 {
                                0
                            } else {
                                let v = ((seg[q] as u16) << 8) | *seg.get(q + 1).unwrap_or(&0) as u16;
                                q += 2;
                                v
                            }
                        } else {
                            let v = *seg.get(q).unwrap_or(&0) as u16;
                            q += 1;
                            v
                        };
                        t[ZIGZAG[i]] = v;
                    }
                    qtables[tq] = Some(t);
                }
            }
            0xC4 => {
                let mut q = 0;
                while q + 17 <= seg.len() {
                    let tc = seg[q] >> 4;
                    let th = (seg[q] & 15) as usize;
                    let mut counts = [0u8; 16];
                    counts.copy_from_slice(&seg[q + 1..q + 17]);
                    let total: usize = counts.iter().map(|&c| c as usize).sum();
                    q += 17;
                    if q + total > seg.len() || th > 3 || total > 256 {
                        return Err(JpegError(8));
                    }
                    let vals = &seg[q..q + total];
                    q += total;
                    let h = Huff::new(&counts, vals);
                    if tc == 0 {
                        dc_tables[th] = Some(h);
                    } else {
                        ac_tables[th] = Some(h);
                    }
                }
            }
            0xDD => {
                if seg.len() >= 2 {
                    restart_interval = be16(seg, 0);
                }
            }
            0xC0 | 0xC1 | 0xC2 => {
                if seg.len() < 6 {
                    return Err(JpegError(12));
                }
                let precision = seg[0];
                if precision != 8 {
                    return Err(JpegError(15));
                }
                let height = be16(seg, 1);
                let width = be16(seg, 3);
                let nc = seg[5] as usize;
                if height == 0 || width == 0 {
                    return Err(JpegError(32));
                }
                if nc == 0 || nc > 4 || seg.len() < 6 + 3 * nc {
                    return Err(JpegError(26));
                }
                let mut comps = Vec::new();
                for c in 0..nc {
                    let id = seg[6 + 3 * c];
                    let hv = seg[7 + 3 * c];
                    let h = (hv >> 4) as usize;
                    let v = (hv & 15) as usize;
                    if !(1..=4).contains(&h) || !(1..=4).contains(&v) {
                        return Err(JpegError(18));
                    }
                    comps.push(Component {
                        id,
                        h,
                        v,
                        tq: (seg[8 + 3 * c] & 3) as usize,
                        width_in_blocks: 0,
                        height_in_blocks: 0,
                        bw: 0,
                        bh: 0,
                        coefs: Vec::new(),
                        dc_tbl: 0,
                        ac_tbl: 0,
                    });
                }
                let max_h = comps.iter().map(|c| c.h).max().unwrap();
                let max_v = comps.iter().map(|c| c.v).max().unwrap();
                let mcux = (width + 8 * max_h - 1) / (8 * max_h);
                let mcuy = (height + 8 * max_v - 1) / (8 * max_v);
                for c in comps.iter_mut() {
                    c.width_in_blocks = (width * c.h + 8 * max_h - 1) / (8 * max_h);
                    c.height_in_blocks = (height * c.v + 8 * max_v - 1) / (8 * max_v);
                    c.bw = mcux * c.h;
                    c.bh = mcuy * c.v;
                    c.coefs = vec![[0i16; 64]; c.bw * c.bh];
                }
                frame = Some(JpegData {
                    width,
                    height,
                    progressive: m == 0xC2,
                    components: comps,
                    qtables: [None, None, None, None],
                    markers: Vec::new(),
                    jfif: None,
                    adobe_transform: None,
                    max_h,
                    max_v,
                });
            }
            0xC3 | 0xC5..=0xC7 | 0xC9..=0xCB | 0xCD..=0xCF => {
                return Err(JpegError(47));
            }
            0xDA => {
                let fr = match frame.as_mut() {
                    Some(f) => f,
                    None => return Err(JpegError(51)),
                };
                let ns = seg[0] as usize;
                if ns == 0 || ns > 4 || seg.len() < 1 + 2 * ns + 3 {
                    return Err(JpegError(12));
                }
                let mut scomp = Vec::new();
                for i in 0..ns {
                    let cid = seg[1 + 2 * i];
                    let t = seg[2 + 2 * i];
                    let ci = match fr.components.iter().position(|c| c.id == cid) {
                        Some(ci) => ci,
                        None => return Err(JpegError(5)),
                    };
                    fr.components[ci].dc_tbl = (t >> 4) as usize & 3;
                    fr.components[ci].ac_tbl = (t & 15) as usize & 3;
                    scomp.push(ci);
                }
                let ss = seg[1 + 2 * ns] as usize;
                let se = seg[2 + 2 * ns] as usize;
                let ah = (seg[3 + 2 * ns] >> 4) as u32;
                let al = (seg[3 + 2 * ns] & 15) as u32;
                let start = p + len;
                let mut br = BitReader::new(data, start);
                decode_scan(fr, &scomp, ss, se, ah, al, &dc_tables, &ac_tables, restart_interval, &mut br)?;
                p = br.marker_pos();
                continue;
            }
            _ => {}
        }
        p += len;
    }
    let mut fr = match frame {
        Some(f) => f,
        None => return Err(JpegError(51)),
    };
    for c in fr.components.iter() {
        if qtables[c.tq].is_none() {
            return Err(JpegError(52));
        }
    }
    fr.qtables = qtables;
    fr.markers = markers;
    fr.jfif = jfif;
    fr.adobe_transform = adobe;
    Ok(fr)
}

#[allow(clippy::too_many_arguments)]
fn decode_scan(
    fr: &mut JpegData,
    scomp: &[usize],
    ss: usize,
    se: usize,
    ah: u32,
    al: u32,
    dc_tables: &[Option<Huff>; 4],
    ac_tables: &[Option<Huff>; 4],
    restart_interval: usize,
    br: &mut BitReader,
) -> Result<(), JpegError> {
    let progressive = fr.progressive;
    if !progressive && (ss != 0 || se != 63) {
        // tolerate
    }
    let se = se.min(63);
    let is_dc = ss == 0;
    // check tables
    for &ci in scomp {
        let c = &fr.components[ci];
        if (!progressive || (is_dc && ah == 0)) && dc_tables[c.dc_tbl].is_none() {
            return Err(JpegError(50));
        }
        if (!progressive || !is_dc) && ac_tables[c.ac_tbl].is_none() {
            return Err(JpegError(50));
        }
    }
    let mut preds = [0i32; 4];
    let mut eobrun: u32 = 0;
    let single = scomp.len() == 1;
    let (mcus_x, mcus_y) = if single {
        let c = &fr.components[scomp[0]];
        (c.width_in_blocks, c.height_in_blocks)
    } else {
        (
            (fr.width + 8 * fr.max_h - 1) / (8 * fr.max_h),
            (fr.height + 8 * fr.max_v - 1) / (8 * fr.max_v),
        )
    };
    let total = mcus_x * mcus_y;
    let mut restarts_left = restart_interval;
    for mcu in 0..total {
        if restart_interval > 0 {
            if restarts_left == 0 {
                br.restart();
                preds = [0; 4];
                eobrun = 0;
                restarts_left = restart_interval;
            }
            restarts_left -= 1;
        }
        if br.hit_marker && br.nbits == 0 {
            // out of data: remaining coefficients left as is
        }
        let mx = mcu % mcus_x;
        let my = mcu / mcus_x;
        for (si, &ci) in scomp.iter().enumerate() {
            let (h, v) = if single { (1, 1) } else { (fr.components[ci].h, fr.components[ci].v) };
            for by in 0..v {
                for bx in 0..h {
                    let (bxx, byy) = if single { (mx, my) } else { (mx * h + bx, my * v + by) };
                    let comp = &mut fr.components[ci];
                    let bw = comp.bw;
                    let blk = &mut comp.coefs[byy * bw + bxx];
                    let dct = comp.dc_tbl;
                    let act = comp.ac_tbl;
                    if !progressive {
                        let dc = dc_tables[dct].as_ref().unwrap();
                        let ac = ac_tables[act].as_ref().unwrap();
                        let s = br.decode(dc) as u32;
                        let diff = br.receive_extend(s);
                        preds[si] += diff;
                        blk[0] = preds[si] as i16;
                        let mut k = 1;
                        while k < 64 {
                            let rs = br.decode(ac);
                            let r = (rs >> 4) as usize;
                            let s = (rs & 15) as u32;
                            if s == 0 {
                                if r == 15 {
                                    k += 16;
                                    continue;
                                }
                                break;
                            }
                            k += r;
                            if k > 63 {
                                break;
                            }
                            blk[ZIGZAG[k]] = br.receive_extend(s) as i16;
                            k += 1;
                        }
                    } else if is_dc {
                        if ah == 0 {
                            let dc = dc_tables[dct].as_ref().unwrap();
                            let s = br.decode(dc) as u32;
                            let diff = br.receive_extend(s);
                            preds[si] += diff;
                            blk[0] = (preds[si] << al) as i16;
                        } else if br.get_bit() != 0 {
                            blk[0] |= (1 << al) as i16;
                        }
                    } else if ah == 0 {
                        // AC first
                        if eobrun > 0 {
                            eobrun -= 1;
                            continue;
                        }
                        let ac = ac_tables[act].as_ref().unwrap();
                        let mut k = ss;
                        while k <= se {
                            let rs = br.decode(ac);
                            let r = (rs >> 4) as u32;
                            let s = (rs & 15) as u32;
                            if s == 0 {
                                if r < 15 {
                                    eobrun = (1 << r) - 1;
                                    if r > 0 {
                                        eobrun += br.get_bits(r);
                                    }
                                    break;
                                }
                                k += 16;
                                continue;
                            }
                            k += r as usize;
                            if k > 63 {
                                break;
                            }
                            blk[ZIGZAG[k]] = (br.receive_extend(s) * (1 << al)) as i16;
                            k += 1;
                        }
                    } else {
                        // AC refinement
                        let ac = ac_tables[act].as_ref().unwrap();
                        let p1 = 1i32 << al;
                        let m1 = -1i32 << al;
                        let mut k = ss;
                        if eobrun == 0 {
                            while k <= se {
                                let rs = br.decode(ac);
                                let mut r = (rs >> 4) as i32;
                                let s = (rs & 15) as u32;
                                let mut val = 0i32;
                                if s != 0 {
                                    val = if br.get_bit() != 0 { p1 } else { m1 };
                                } else if r != 15 {
                                    eobrun = 1 << r;
                                    if r > 0 {
                                        eobrun += br.get_bits(r as u32);
                                    }
                                    break;
                                }
                                while k <= se {
                                    let z = ZIGZAG[k];
                                    if blk[z] != 0 {
                                        if br.get_bit() != 0 && (blk[z] as i32 & p1) == 0 {
                                            if blk[z] >= 0 {
                                                blk[z] = (blk[z] as i32 + p1) as i16;
                                            } else {
                                                blk[z] = (blk[z] as i32 + m1) as i16;
                                            }
                                        }
                                    } else {
                                        if r == 0 {
                                            if val != 0 {
                                                blk[z] = val as i16;
                                            }
                                            k += 1;
                                            break;
                                        }
                                        r -= 1;
                                    }
                                    k += 1;
                                }
                            }
                        }
                        if eobrun > 0 {
                            while k <= se {
                                let z = ZIGZAG[k];
                                if blk[z] != 0 && br.get_bit() != 0 && (blk[z] as i32 & p1) == 0 {
                                    if blk[z] >= 0 {
                                        blk[z] = (blk[z] as i32 + p1) as i16;
                                    } else {
                                        blk[z] = (blk[z] as i32 + m1) as i16;
                                    }
                                }
                                k += 1;
                            }
                            eobrun -= 1;
                        }
                    }
                }
            }
        }
    }
    Ok(())
}

// ---------------------------------------------------------------------------
// Inverse DCT (integer, slow-but-accurate variant)

const CONST_BITS: i32 = 13;
const PASS1_BITS: i32 = 2;
const FIX_0_298631336: i64 = 2446;
const FIX_0_390180644: i64 = 3196;
const FIX_0_541196100: i64 = 4433;
const FIX_0_765366865: i64 = 6270;
const FIX_0_899976223: i64 = 7373;
const FIX_1_175875602: i64 = 9633;
const FIX_1_501321110: i64 = 12299;
const FIX_1_847759065: i64 = 15137;
const FIX_1_961570560: i64 = 16069;
const FIX_2_053119869: i64 = 16819;
const FIX_2_562915447: i64 = 20995;
const FIX_3_072711026: i64 = 25172;

#[inline]
fn descale(x: i64, n: i32) -> i64 {
    (x + (1i64 << (n - 1))) >> n
}

fn idct_range_limit(x: i64) -> u8 {
    let idx = (x as i32) & 1023;
    if idx < 128 {
        (idx + 128) as u8
    } else if idx < 512 {
        255
    } else if idx < 896 {
        0
    } else {
        (idx - 896) as u8
    }
}

pub fn idct_islow(coef: &[i16; 64], q: &[u16; 64], out: &mut [u8], stride: usize) {
    let mut ws = [0i64; 64];
    for col in 0..8 {
        let c = |r: usize| coef[r * 8 + col] as i64 * q[r * 8 + col] as i64;
        if (1..8).all(|r| coef[r * 8 + col] == 0) {
            let dc = c(0) << PASS1_BITS;
            for r in 0..8 {
                ws[r * 8 + col] = dc;
            }
            continue;
        }
        let z2 = c(2);
        let z3 = c(6);
        let z1 = (z2 + z3) * FIX_0_541196100;
        let tmp2 = z1 + z3 * (-FIX_1_847759065);
        let tmp3 = z1 + z2 * FIX_0_765366865;
        let z2 = c(0);
        let z3 = c(4);
        let tmp0 = (z2 + z3) << CONST_BITS;
        let tmp1 = (z2 - z3) << CONST_BITS;
        let tmp10 = tmp0 + tmp3;
        let tmp13 = tmp0 - tmp3;
        let tmp11 = tmp1 + tmp2;
        let tmp12 = tmp1 - tmp2;
        let mut t0 = c(7);
        let mut t1 = c(5);
        let mut t2 = c(3);
        let mut t3 = c(1);
        let z1 = t0 + t3;
        let z2 = t1 + t2;
        let z3 = t0 + t2;
        let z4 = t1 + t3;
        let z5 = (z3 + z4) * FIX_1_175875602;
        t0 *= FIX_0_298631336;
        t1 *= FIX_2_053119869;
        t2 *= FIX_3_072711026;
        t3 *= FIX_1_501321110;
        let z1 = z1 * (-FIX_0_899976223);
        let z2 = z2 * (-FIX_2_562915447);
        let z3 = z3 * (-FIX_1_961570560) + z5;
        let z4 = z4 * (-FIX_0_390180644) + z5;
        t0 += z1 + z3;
        t1 += z2 + z4;
        t2 += z2 + z3;
        t3 += z1 + z4;
        let n = CONST_BITS - PASS1_BITS;
        ws[col] = descale(tmp10 + t3, n);
        ws[56 + col] = descale(tmp10 - t3, n);
        ws[8 + col] = descale(tmp11 + t2, n);
        ws[48 + col] = descale(tmp11 - t2, n);
        ws[16 + col] = descale(tmp12 + t1, n);
        ws[40 + col] = descale(tmp12 - t1, n);
        ws[24 + col] = descale(tmp13 + t0, n);
        ws[32 + col] = descale(tmp13 - t0, n);
    }
    for row in 0..8 {
        let w = &ws[row * 8..row * 8 + 8];
        let o = &mut out[row * stride..row * stride + 8];
        if w[1..8].iter().all(|&v| v == 0) {
            let v = idct_range_limit(descale(w[0], PASS1_BITS + 3));
            for x in o.iter_mut() {
                *x = v;
            }
            continue;
        }
        let z2 = w[2];
        let z3 = w[6];
        let z1 = (z2 + z3) * FIX_0_541196100;
        let tmp2 = z1 + z3 * (-FIX_1_847759065);
        let tmp3 = z1 + z2 * FIX_0_765366865;
        let tmp0 = (w[0] + w[4]) << CONST_BITS;
        let tmp1 = (w[0] - w[4]) << CONST_BITS;
        let tmp10 = tmp0 + tmp3;
        let tmp13 = tmp0 - tmp3;
        let tmp11 = tmp1 + tmp2;
        let tmp12 = tmp1 - tmp2;
        let mut t0 = w[7];
        let mut t1 = w[5];
        let mut t2 = w[3];
        let mut t3 = w[1];
        let z1 = t0 + t3;
        let z2 = t1 + t2;
        let z3 = t0 + t2;
        let z4 = t1 + t3;
        let z5 = (z3 + z4) * FIX_1_175875602;
        t0 *= FIX_0_298631336;
        t1 *= FIX_2_053119869;
        t2 *= FIX_3_072711026;
        t3 *= FIX_1_501321110;
        let z1 = z1 * (-FIX_0_899976223);
        let z2 = z2 * (-FIX_2_562915447);
        let z3 = z3 * (-FIX_1_961570560) + z5;
        let z4 = z4 * (-FIX_0_390180644) + z5;
        t0 += z1 + z3;
        t1 += z2 + z4;
        t2 += z2 + z3;
        t3 += z1 + z4;
        let n = CONST_BITS + PASS1_BITS + 3;
        o[0] = idct_range_limit(descale(tmp10 + t3, n));
        o[7] = idct_range_limit(descale(tmp10 - t3, n));
        o[1] = idct_range_limit(descale(tmp11 + t2, n));
        o[6] = idct_range_limit(descale(tmp11 - t2, n));
        o[2] = idct_range_limit(descale(tmp12 + t1, n));
        o[5] = idct_range_limit(descale(tmp12 - t1, n));
        o[3] = idct_range_limit(descale(tmp13 + t0, n));
        o[4] = idct_range_limit(descale(tmp13 - t0, n));
    }
}

/// Per-component sample planes (downsampled resolution, padded to blocks).
pub struct Planes {
    pub planes: Vec<Vec<u8>>,
    pub strides: Vec<usize>,
    /// real downsampled dimensions
    pub dims: Vec<(usize, usize)>,
}

pub fn idct_planes(j: &JpegData) -> Planes {
    let mut planes = Vec::new();
    let mut strides = Vec::new();
    let mut dims = Vec::new();
    for c in &j.components {
        let q = j.qtables[c.tq].unwrap_or([1u16; 64]);
        let stride = c.bw * 8;
        let mut plane = vec![0u8; stride * c.bh * 8];
        for by in 0..c.bh {
            for bx in 0..c.bw {
                let off = by * 8 * stride + bx * 8;
                idct_islow(&c.coefs[by * c.bw + bx], &q, &mut plane[off..], stride);
            }
        }
        planes.push(plane);
        strides.push(stride);
        let dw = (j.width * c.h + j.max_h - 1) / j.max_h;
        let dh = (j.height * c.v + j.max_v - 1) / j.max_v;
        dims.push((dw, dh));
    }
    Planes { planes, strides, dims }
}

/// Upsample a component to full resolution (width x height).
fn upsample(
    plane: &[u8],
    stride: usize,
    dw: usize,
    dh: usize,
    hf: usize,
    vf: usize,
    width: usize,
    height: usize,
) -> Vec<u8> {
    let mut out = vec![0u8; width * height];
    let row = |y: isize| -> &[u8] {
        let yy = y.clamp(0, dh as isize - 1) as usize;
        &plane[yy * stride..yy * stride + dw]
    };
    if hf == 1 && vf == 1 {
        for y in 0..height {
            out[y * width..y * width + width].copy_from_slice(&row(y as isize)[..width]);
        }
        return out;
    }
    if hf == 2 && vf == 1 {
        let mut line = vec![0u8; dw * 2];
        for y in 0..height {
            let inp = row(y as isize);
            h2v1_fancy(inp, dw, &mut line);
            out[y * width..y * width + width].copy_from_slice(&line[..width]);
        }
        return out;
    }
    if hf == 2 && vf == 2 {
        let mut line = vec![0u8; dw * 2];
        for y in 0..height {
            let iy = (y / 2) as isize;
            let near = row(iy);
            let far = if y % 2 == 0 { row(iy - 1) } else { row(iy + 1) };
            if dw == 1 {
                let s = near[0] as i32 * 3 + far[0] as i32;
                line[0] = ((s * 4 + 8) >> 4) as u8;
                line[1] = ((s * 4 + 7) >> 4) as u8;
            } else {
                let mut this = near[0] as i32 * 3 + far[0] as i32;
                let mut next = near[1] as i32 * 3 + far[1] as i32;
                line[0] = ((this * 4 + 8) >> 4) as u8;
                line[1] = ((this * 3 + next + 7) >> 4) as u8;
                let mut last = this;
                this = next;
                let mut o = 2;
                for x in 2..dw {
                    next = near[x] as i32 * 3 + far[x] as i32;
                    line[o] = ((this * 3 + last + 8) >> 4) as u8;
                    line[o + 1] = ((this * 3 + next + 7) >> 4) as u8;
                    o += 2;
                    last = this;
                    this = next;
                }
                line[o] = ((this * 3 + last + 8) >> 4) as u8;
                line[o + 1] = ((this * 4 + 7) >> 4) as u8;
            }
            out[y * width..y * width + width].copy_from_slice(&line[..width]);
        }
        return out;
    }
    if hf == 1 && vf == 2 {
        for y in 0..height {
            let iy = (y / 2) as isize;
            let near = row(iy);
            let (far, bias) = if y % 2 == 0 { (row(iy - 1), 1) } else { (row(iy + 1), 2) };
            for x in 0..width {
                let s = near[x] as i32 * 3 + far[x] as i32;
                out[y * width + x] = ((s + bias) >> 2) as u8;
            }
        }
        return out;
    }
    // generic integral replication
    for y in 0..height {
        let inp = row((y / vf) as isize);
        for x in 0..width {
            out[y * width + x] = inp[(x / hf).min(dw - 1)];
        }
    }
    out
}

fn h2v1_fancy(inp: &[u8], dw: usize, out: &mut [u8]) {
    if dw == 1 {
        out[0] = inp[0];
        out[1] = inp[0];
        return;
    }
    let mut o = 0;
    let v = inp[0] as i32;
    out[o] = v as u8;
    out[o + 1] = ((v * 3 + inp[1] as i32 + 2) >> 2) as u8;
    o += 2;
    for x in 1..dw - 1 {
        let v = inp[x] as i32 * 3;
        out[o] = ((v + inp[x - 1] as i32 + 1) >> 2) as u8;
        out[o + 1] = ((v + inp[x + 1] as i32 + 2) >> 2) as u8;
        o += 2;
    }
    let v = inp[dw - 1] as i32;
    out[o] = ((v * 3 + inp[dw - 2] as i32 + 1) >> 2) as u8;
    out[o + 1] = v as u8;
}

/// Full resolution component planes (no color conversion).
pub fn full_planes(j: &JpegData) -> Vec<Vec<u8>> {
    let p = idct_planes(j);
    let mut res = Vec::new();
    for (ci, c) in j.components.iter().enumerate() {
        let hf = j.max_h / c.h;
        let vf = j.max_v / c.v;
        let (dw, dh) = p.dims[ci];
        res.push(upsample(&p.planes[ci], p.strides[ci], dw, dh, hf.max(1), vf.max(1), j.width, j.height));
    }
    res
}

fn ycc_tables() -> ([i32; 256], [i32; 256], [i32; 256], [i32; 256]) {
    let mut cr_r = [0i32; 256];
    let mut cb_b = [0i32; 256];
    let mut cr_g = [0i32; 256];
    let mut cb_g = [0i32; 256];
    const SCALEBITS: i32 = 16;
    let one_half: i64 = 1 << (SCALEBITS - 1);
    let fix = |x: f64| -> i64 { (x * 65536.0 + 0.5) as i64 };
    for i in 0..256 {
        let x = i as i64 - 128;
        cr_r[i] = ((fix(1.40200) * x + one_half) >> SCALEBITS) as i32;
        cb_b[i] = ((fix(1.77200) * x + one_half) >> SCALEBITS) as i32;
        cr_g[i] = (-fix(0.71414) * x) as i32;
        cb_g[i] = (-fix(0.34414) * x + one_half) as i32;
    }
    (cr_r, cb_b, cr_g, cb_g)
}

/// Decoded pixels: gray (1), RGB (3) or CMYK (4).
pub fn to_pixels(j: &JpegData) -> (usize, Vec<u8>) {
    let planes = full_planes(j);
    let n = j.width * j.height;
    let nc = j.components.len();
    if nc == 1 {
        return (1, planes.into_iter().next().unwrap());
    }
    let clamp = |v: i32| -> u8 { v.clamp(0, 255) as u8 };
    let (cr_r, cb_b, cr_g, cb_g) = ycc_tables();
    if nc == 3 {
        // RGB if Adobe transform 0 and component ids R,G,B
        let ids: Vec<u8> = j.components.iter().map(|c| c.id).collect();
        let is_rgb = (j.jfif.is_none() && j.adobe_transform == Some(0))
            || (j.jfif.is_none() && j.adobe_transform.is_none() && ids == [b'R', b'G', b'B']);
        let mut out = vec![0u8; n * 3];
        for i in 0..n {
            if is_rgb {
                out[3 * i] = planes[0][i];
                out[3 * i + 1] = planes[1][i];
                out[3 * i + 2] = planes[2][i];
            } else {
                let y = planes[0][i] as i32;
                let cb = planes[1][i] as usize;
                let cr = planes[2][i] as usize;
                out[3 * i] = clamp(y + cr_r[cr]);
                out[3 * i + 1] = clamp(y + ((cb_g[cb] + cr_g[cr]) >> 16));
                out[3 * i + 2] = clamp(y + cb_b[cb]);
            }
        }
        return (3, out);
    }
    // 4 components: CMYK or YCCK -> CMYK
    let mut out = vec![0u8; n * 4];
    let ycck = j.adobe_transform == Some(2);
    for i in 0..n {
        if ycck {
            let y = planes[0][i] as i32;
            let cb = planes[1][i] as usize;
            let cr = planes[2][i] as usize;
            out[4 * i] = 255 - clamp(y + cr_r[cr]);
            out[4 * i + 1] = 255 - clamp(y + ((cb_g[cb] + cr_g[cr]) >> 16));
            out[4 * i + 2] = 255 - clamp(y + cb_b[cb]);
        } else {
            out[4 * i] = planes[0][i];
            out[4 * i + 1] = planes[1][i];
            out[4 * i + 2] = planes[2][i];
        }
        out[4 * i + 3] = planes[3][i];
    }
    (4, out)
}

/// Decode to an RGB / gray image (CMYK converted to RGB naively).
pub fn decode_image(data: &[u8]) -> Result<super::Image, JpegError> {
    let j = decode_coefficients(data)?;
    let (ch, px) = to_pixels(&j);
    let img = match ch {
        1 => super::Image::new(j.width as u32, j.height as u32, 1, px),
        3 => super::Image::new(j.width as u32, j.height as u32, 3, px),
        _ => {
            let n = j.width * j.height;
            let mut out = vec![0u8; n * 3];
            let inverted = j.adobe_transform.is_some();
            for i in 0..n {
                let (mut c, mut m, mut y, mut k) = (
                    px[4 * i] as u32,
                    px[4 * i + 1] as u32,
                    px[4 * i + 2] as u32,
                    px[4 * i + 3] as u32,
                );
                if inverted {
                    c = 255 - c;
                    m = 255 - m;
                    y = 255 - y;
                    k = 255 - k;
                }
                out[3 * i] = (255 - (c + k).min(255)) as u8;
                out[3 * i + 1] = (255 - (m + k).min(255)) as u8;
                out[3 * i + 2] = (255 - (y + k).min(255)) as u8;
            }
            super::Image::new(j.width as u32, j.height as u32, 3, out)
        }
    };
    Ok(img)
}

/// EXIF orientation value (1..8) if present.
pub fn exif_orientation(data: &[u8]) -> Option<u16> {
    let mut p = 2;
    while p + 4 <= data.len() {
        if data[p] != 0xFF {
            return None;
        }
        let m = data[p + 1];
        if m == 0xDA || m == 0xD9 {
            return None;
        }
        let len = be16(data, p + 2);
        if m == 0xE1 && p + 2 + len <= data.len() {
            let seg = &data[p + 4..p + 2 + len];
            if seg.len() > 14 && &seg[0..6] == b"Exif\0\0" {
                return super::tiff::orientation_from_tiff(&seg[6..]);
            }
        }
        p += 2 + len;
    }
    None
}
