// Baseline / progressive JPEG decoder producing DCT coefficients and pixels.
// Pixel reconstruction follows the classic integer ("islow") IDCT and the
// triangle ("fancy") chroma upsampling used by the common C libraries.

pub const ZIGZAG: [usize; 64] = [
    0, 1, 8, 16, 9, 2, 3, 10, 17, 24, 32, 25, 18, 11, 4, 5, 12, 19, 26, 33, 40, 48, 41, 34, 27,
