// Inverse DCT (integer, slow-but-accurate variant)

const CONST_BITS: i32 = 13;
const PASS1_BITS: i32 = 2;
const FIX_0_298631336: i64 = 2446;
const FIX_0_390180644: i64 = 3196;
const FIX_0_541196100: i64 = 4433;
const FIX_0_765366865: i64 = 6270;
const FIX_0_899976223: i64 = 7373;
const FIX_1_175875602: i64 = 9633;
const FIX_1_501321110: i64 = 12299;
const FIX_1_847759065: i64 = 15137;
const FIX_1_961570560: i64 = 16069;
const FIX_2_053119869: i64 = 16819;
const FIX_2_562915447: i64 = 20995;
const FIX_3_072711026: i64 = 25172;

#[inline]
fn descale(x: i64, n: i32) -> i64 {
    (x + (1i64 << (n - 1))) >> n
}

fn idct_range_limit(x: i64) -> u8 {
    let idx = (x as i32) & 1023;
    if idx < 128 {
        (idx + 128) as u8
    } else if idx < 512 {
        255
    } else if idx < 896 {
        0
    } else {
        (idx - 896) as u8
    }
}

pub fn idct_islow(coef: &[i16; 64], q: &[u16; 64], out: &mut [u8], stride: usize) {
    let mut ws = [0i64; 64];
    for col in 0..8 {
        let c = |r: usize| coef[r * 8 + col] as i64 * q[r * 8 + col] as i64;
        if (1..8).all(|r| coef[r * 8 + col] == 0) {
            let dc = c(0) << PASS1_BITS;
            for r in 0..8 {
                ws[r * 8 + col] = dc;
            }
            continue;
        }
        let z2 = c(2);
        let z3 = c(6);
        let z1 = (z2 + z3) * FIX_0_541196100;
        let tmp2 = z1 + z3 * (-FIX_1_847759065);
        let tmp3 = z1 + z2 * FIX_0_765366865;
        let z2 = c(0);
        let z3 = c(4);
        let tmp0 = (z2 + z3) << CONST_BITS;
        let tmp1 = (z2 - z3) << CONST_BITS;
        let tmp10 = tmp0 + tmp3;
        let tmp13 = tmp0 - tmp3;
        let tmp11 = tmp1 + tmp2;
        let tmp12 = tmp1 - tmp2;
        let mut t0 = c(7);
        let mut t1 = c(5);
        let mut t2 = c(3);
        let mut t3 = c(1);
        let z1 = t0 + t3;
        let z2 = t1 + t2;
        let z3 = t0 + t2;
        let z4 = t1 + t3;
        let z5 = (z3 + z4) * FIX_1_175875602;
        t0 *= FIX_0_298631336;
        t1 *= FIX_2_053119869;
        t2 *= FIX_3_072711026;
        t3 *= FIX_1_501321110;
        let z1 = z1 * (-FIX_0_899976223);
        let z2 = z2 * (-FIX_2_562915447);
        let z3 = z3 * (-FIX_1_961570560) + z5;
        let z4 = z4 * (-FIX_0_390180644) + z5;
        t0 += z1 + z3;
        t1 += z2 + z4;
        t2 += z2 + z3;
        t3 += z1 + z4;
        let n = CONST_BITS - PASS1_BITS;
        ws[col] = descale(tmp10 + t3, n);
        ws[56 + col] = descale(tmp10 - t3, n);
        ws[8 + col] = descale(tmp11 + t2, n);
        ws[48 + col] = descale(tmp11 - t2, n);
        ws[16 + col] = descale(tmp12 + t1, n);
        ws[40 + col] = descale(tmp12 - t1, n);
        ws[24 + col] = descale(tmp13 + t0, n);
        ws[32 + col] = descale(tmp13 - t0, n);
    }
    for row in 0..8 {
        let w = &ws[row * 8..row * 8 + 8];
        let o = &mut out[row * stride..row * stride + 8];
        if w[1..8].iter().all(|&v| v == 0) {
            let v = idct_range_limit(descale(w[0], PASS1_BITS + 3));
            for x in o.iter_mut() {
                *x = v;
            }
            continue;
        }
        let z2 = w[2];
        let z3 = w[6];
        let z1 = (z2 + z3) * FIX_0_541196100;
        let tmp2 = z1 + z3 * (-FIX_1_847759065);
        let tmp3 = z1 + z2 * FIX_0_765366865;
        let tmp0 = (w[0] + w[4]) << CONST_BITS;
        let tmp1 = (w[0] - w[4]) << CONST_BITS;
        let tmp10 = tmp0 + tmp3;
        let tmp13 = tmp0 - tmp3;
        let tmp11 = tmp1 + tmp2;
        let tmp12 = tmp1 - tmp2;
        let mut t0 = w[7];
        let mut t1 = w[5];
        let mut t2 = w[3];
        let mut t3 = w[1];
        let z1 = t0 + t3;
        let z2 = t1 + t2;
        let z3 = t0 + t2;
        let z4 = t1 + t3;
        let z5 = (z3 + z4) * FIX_1_175875602;
        t0 *= FIX_0_298631336;
        t1 *= FIX_2_053119869;
        t2 *= FIX_3_072711026;
        t3 *= FIX_1_501321110;
        let z1 = z1 * (-FIX_0_899976223);
        let z2 = z2 * (-FIX_2_562915447);
        let z3 = z3 * (-FIX_1_961570560) + z5;
        let z4 = z4 * (-FIX_0_390180644) + z5;
        t0 += z1 + z3;
        t1 += z2 + z4;
        t2 += z2 + z3;
        t3 += z1 + z4;
        let n = CONST_BITS + PASS1_BITS + 3;
        o[0] = idct_range_limit(descale(tmp10 + t3, n));
        o[7] = idct_range_limit(descale(tmp10 - t3, n));
        o[1] = idct_range_limit(descale(tmp11 + t2, n));
        o[6] = idct_range_limit(descale(tmp11 - t2, n));
        o[2] = idct_range_limit(descale(tmp12 + t1, n));
        o[5] = idct_range_limit(descale(tmp12 - t1, n));
        o[3] = idct_range_limit(descale(tmp13 + t0, n));
        o[4] = idct_range_limit(descale(tmp13 - t0, n));
    }
}

/// Per-component sample planes (downsampled resolution, padded to blocks).
pub struct Planes {
    pub planes: Vec<Vec<u8>>,
    pub strides: Vec<usize>,
    /// real downsampled dimensions
    pub dims: Vec<(usize, usize)>,
}

pub fn idct_planes(j: &JpegData) -> Planes {
    let mut planes = Vec::new();
    let mut strides = Vec::new();
    let mut dims = Vec::new();
    for c in &j.components {
        let q = j.qtables[c.tq].unwrap_or([1u16; 64]);
        let stride = c.bw * 8;
        let mut plane = vec![0u8; stride * c.bh * 8];
        for by in 0..c.bh {
            for bx in 0..c.bw {
                let off = by * 8 * stride + bx * 8;
                idct_islow(&c.coefs[by * c.bw + bx], &q, &mut plane[off..], stride);
            }
        }
        planes.push(plane);
        strides.push(stride);
        let dw = (j.width * c.h + j.max_h - 1) / j.max_h;
        let dh = (j.height * c.v + j.max_v - 1) / j.max_v;
        dims.push((dw, dh));
    }
    Planes { planes, strides, dims }
}

/// Upsample a component to full resolution (width x height).
fn upsample(
    plane: &[u8],
    stride: usize,
    dw: usize,
    dh: usize,
    hf: usize,
    vf: usize,
    width: usize,
    height: usize,
) -> Vec<u8> {
    let mut out = vec![0u8; width * height];
    let row = |y: isize| -> &[u8] {
        let yy = y.clamp(0, dh as isize - 1) as usize;
        &plane[yy * stride..yy * stride + dw]
    };
    if hf == 1 && vf == 1 {
        for y in 0..height {
            out[y * width..y * width + width].copy_from_slice(&row(y as isize)[..width]);
        }
        return out;
    }
    if hf == 2 && vf == 1 {
        let mut line = vec![0u8; dw * 2];
        for y in 0..height {
            let inp = row(y as isize);
            h2v1_fancy(inp, dw, &mut line);
            out[y * width..y * width + width].copy_from_slice(&line[..width]);
        }
        return out;
    }
    if hf == 2 && vf == 2 {
        let mut line = vec![0u8; dw * 2];
        for y in 0..height {
            let iy = (y / 2) as isize;
            let near = row(iy);
            let far = if y % 2 == 0 { row(iy - 1) } else { row(iy + 1) };
            if dw == 1 {
                let s = near[0] as i32 * 3 + far[0] as i32;
                line[0] = ((s * 4 + 8) >> 4) as u8;
                line[1] = ((s * 4 + 7) >> 4) as u8;
            } else {
                let mut this = near[0] as i32 * 3 + far[0] as i32;
                let mut next = near[1] as i32 * 3 + far[1] as i32;
                line[0] = ((this * 4 + 8) >> 4) as u8;
                line[1] = ((this * 3 + next + 7) >> 4) as u8;
                let mut last = this;
                this = next;
                let mut o = 2;
                for x in 2..dw {
                    next = near[x] as i32 * 3 + far[x] as i32;
                    line[o] = ((this * 3 + last + 8) >> 4) as u8;
                    line[o + 1] = ((this * 3 + next + 7) >> 4) as u8;
                    o += 2;
                    last = this;
                    this = next;
                }
                line[o] = ((this * 3 + last + 8) >> 4) as u8;
                line[o + 1] = ((this * 4 + 7) >> 4) as u8;
            }
            out[y * width..y * width + width].copy_from_slice(&line[..width]);
        }
        return out;
    }
    if hf == 1 && vf == 2 {
        for y in 0..height {
            let iy = (y / 2) as isize;
            let near = row(iy);
            let (far, bias) = if y % 2 == 0 { (row(iy - 1), 1) } else { (row(iy + 1), 2) };
            for x in 0..width {
                let s = near[x] as i32 * 3 + far[x] as i32;
                out[y * width + x] = ((s + bias) >> 2) as u8;
            }
        }
        return out;
    }
    // generic integral replication
    for y in 0..height {
        let inp = row((y / vf) as isize);
        for x in 0..width {
            out[y * width + x] = inp[(x / hf).min(dw - 1)];
        }
    }
    out
}

fn h2v1_fancy(inp: &[u8], dw: usize, out: &mut [u8]) {
    if dw == 1 {
        out[0] = inp[0];
        out[1] = inp[0];
        return;
    }
    let mut o = 0;
    let v = inp[0] as i32;
    out[o] = v as u8;
    out[o + 1] = ((v * 3 + inp[1] as i32 + 2) >> 2) as u8;
    o += 2;
    for x in 1..dw - 1 {
        let v = inp[x] as i32 * 3;
        out[o] = ((v + inp[x - 1] as i32 + 1) >> 2) as u8;
        out[o + 1] = ((v + inp[x + 1] as i32 + 2) >> 2) as u8;
        o += 2;
    }
    let v = inp[dw - 1] as i32;
    out[o] = ((v * 3 + inp[dw - 2] as i32 + 1) >> 2) as u8;
    out[o + 1] = v as u8;
}

/// Full resolution component planes (no color conversion).
pub fn full_planes(j: &JpegData) -> Vec<Vec<u8>> {
    let p = idct_planes(j);
    let mut res = Vec::new();
    for (ci, c) in j.components.iter().enumerate() {
        let hf = j.max_h / c.h;
        let vf = j.max_v / c.v;
        let (dw, dh) = p.dims[ci];
        res.push(upsample(&p.planes[ci], p.strides[ci], dw, dh, hf.max(1), vf.max(1), j.width, j.height));
    }
    res
}

fn ycc_tables() -> ([i32; 256], [i32; 256], [i32; 256], [i32; 256]) {
    let mut cr_r = [0i32; 256];
    let mut cb_b = [0i32; 256];
    let mut cr_g = [0i32; 256];
    let mut cb_g = [0i32; 256];
    const SCALEBITS: i32 = 16;
    let one_half: i64 = 1 << (SCALEBITS - 1);
    let fix = |x: f64| -> i64 { (x * 65536.0 + 0.5) as i64 };
    for i in 0..256 {
        let x = i as i64 - 128;
        cr_r[i] = ((fix(1.40200) * x + one_half) >> SCALEBITS) as i32;
        cb_b[i] = ((fix(1.77200) * x + one_half) >> SCALEBITS) as i32;
        cr_g[i] = (-fix(0.71414) * x) as i32;
        cb_g[i] = (-fix(0.34414) * x + one_half) as i32;
    }
    (cr_r, cb_b, cr_g, cb_g)
}

/// Decoded pixels: gray (1), RGB (3) or CMYK (4).
pub fn to_pixels(j: &JpegData) -> (usize, Vec<u8>) {
    let planes = full_planes(j);
    let n = j.width * j.height;
    let nc = j.components.len();
    if nc == 1 {
        return (1, planes.into_iter().next().unwrap());
    }
    let clamp = |v: i32| -> u8 { v.clamp(0, 255) as u8 };
    let (cr_r, cb_b, cr_g, cb_g) = ycc_tables();
    if nc == 3 {
        // RGB if Adobe transform 0 and component ids R,G,B
        let ids: Vec<u8> = j.components.iter().map(|c| c.id).collect();
        let is_rgb = (j.jfif.is_none() && j.adobe_transform == Some(0))
            || (j.jfif.is_none() && j.adobe_transform.is_none() && ids == [b'R', b'G', b'B']);
        let mut out = vec![0u8; n * 3];
        for i in 0..n {
            if is_rgb {
                out[3 * i] = planes[0][i];
                out[3 * i + 1] = planes[1][i];
                out[3 * i + 2] = planes[2][i];
            } else {
                let y = planes[0][i] as i32;
                let cb = planes[1][i] as usize;
                let cr = planes[2][i] as usize;
                out[3 * i] = clamp(y + cr_r[cr]);
                out[3 * i + 1] = clamp(y + ((cb_g[cb] + cr_g[cr]) >> 16));
                out[3 * i + 2] = clamp(y + cb_b[cb]);
            }
        }
        return (3, out);
    }
    // 4 components: CMYK or YCCK -> CMYK
    let mut out = vec![0u8; n * 4];
    let ycck = j.adobe_transform == Some(2);
    for i in 0..n {
        if ycck {
            let y = planes[0][i] as i32;
            let cb = planes[1][i] as usize;
            let cr = planes[2][i] as usize;
            out[4 * i] = 255 - clamp(y + cr_r[cr]);
            out[4 * i + 1] = 255 - clamp(y + ((cb_g[cb] + cr_g[cr]) >> 16));
            out[4 * i + 2] = 255 - clamp(y + cb_b[cb]);
        } else {
            out[4 * i] = planes[0][i];
            out[4 * i + 1] = planes[1][i];
            out[4 * i + 2] = planes[2][i];
        }
        out[4 * i + 3] = planes[3][i];
    }
    (4, out)
}

/// Decode to an RGB / gray image (CMYK converted to RGB naively).
pub fn decode_image(data: &[u8]) -> Result<super::Image, JpegError> {
    let j = decode_coefficients(data)?;
    let (ch, px) = to_pixels(&j);
    let img = match ch {
        1 => super::Image::new(j.width as u32, j.height as u32, 1, px),
        3 => super::Image::new(j.width as u32, j.height as u32, 3, px),
        _ => {
            let n = j.width * j.height;
            let mut out = vec![0u8; n * 3];
            let inverted = j.adobe_transform.is_some();
            for i in 0..n {
                let (mut c, mut m, mut y, mut k) = (
                    px[4 * i] as u32,
                    px[4 * i + 1] as u32,
                    px[4 * i + 2] as u32,
                    px[4 * i + 3] as u32,
                );
                if inverted {
                    c = 255 - c;
                    m = 255 - m;
                    y = 255 - y;
                    k = 255 - k;
                }
                out[3 * i] = (255 - (c + k).min(255)) as u8;
                out[3 * i + 1] = (255 - (m + k).min(255)) as u8;
                out[3 * i + 2] = (255 - (y + k).min(255)) as u8;
            }
            super::Image::new(j.width as u32, j.height as u32, 3, out)
        }
    };
    Ok(img)
}

/// EXIF orientation value (1..8) if present.
pub fn exif_orientation(data: &[u8]) -> Option<u16> {
    let mut p = 2;
    while p + 4 <= data.len() {
        if data[p] != 0xFF {
            return None;
        }
        let m = data[p + 1];
        if m == 0xDA || m == 0xD9 {
            return None;
        }
        let len = be16(data, p + 2);
        if m == 0xE1 && p + 2 + len <= data.len() {
            let seg = &data[p + 4..p + 2 + len];
            if seg.len() > 14 && &seg[0..6] == b"Exif\0\0" {
                return super::tiff::orientation_from_tiff(&seg[6..]);
            }
        }
        p += 2 + len;
    }
    None
}
