pub fn quality_scaling(q: i32) -> i32 {
    let q = q.clamp(1, 100);
    if q < 50 {
        5000 / q
    } else {
        200 - q * 2
    }
}

pub fn scaled_table(scale: i32) -> [u16; 64] {
    let mut t = [0u16; 64];
    for i in 0..64 {
        let mut v = (STD_TABLE[i] as i64 * scale as i64 + 50) / 100;
        if v <= 0 {
            v = 1;
        }
        if v > 32767 {
            v = 32767;
        }
        t[i] = v as u16;
    }
    t
}

// ---------------------------------------------------------------------------
// Color conversion

pub fn rgb_to_ycc(rgb: &[u8], n: usize) -> [Vec<u8>; 3] {
    const SCALEBITS: i64 = 16;
    let fix = |x: f64| -> i64 { (x * 65536.0 + 0.5) as i64 };
    let one_half = 1i64 << (SCALEBITS - 1);
    let cbcr_offset = 128i64 << SCALEBITS;
    let mut tab = vec![0i64; 8 * 256];
    for i in 0..256i64 {
        let u = i as usize;
        tab[u] = fix(0.29900) * i;
        tab[u + 256] = fix(0.58700) * i;
        tab[u + 512] = fix(0.11400) * i + one_half;
        tab[u + 768] = -fix(0.16874) * i;
        tab[u + 1024] = -fix(0.33126) * i;
        tab[u + 1280] = fix(0.50000) * i + cbcr_offset + one_half - 1;
        tab[u + 1536] = -fix(0.41869) * i;
        tab[u + 1792] = -fix(0.08131) * i;
    }
    let mut y = vec![0u8; n];
    let mut cb = vec![0u8; n];
    let mut cr = vec![0u8; n];
    for i in 0..n {
        let r = rgb[3 * i] as usize;
        let g = rgb[3 * i + 1] as usize;
        let b = rgb[3 * i + 2] as usize;
        y[i] = ((tab[r] + tab[g + 256] + tab[b + 512]) >> SCALEBITS) as u8;
        cb[i] = ((tab[r + 768] + tab[g + 1024] + tab[b + 1280]) >> SCALEBITS) as u8;
        cr[i] = ((tab[r + 1280] + tab[g + 1536] + tab[b + 1792]) >> SCALEBITS) as u8;
    }
    [y, cb, cr]
}

