// Component geometry and downsampling

#[derive(Clone, Debug)]
pub struct CompInfo {
    pub id: u8,
    pub h: usize,
    pub v: usize,
    pub tq: usize,
    pub width_in_blocks: usize,
    pub height_in_blocks: usize,
    /// padded block dimensions (whole MCUs)
    pub bw: usize,
    pub bh: usize,
}

pub fn comp_geometry(width: usize, height: usize, samp: &[(usize, usize)], ids: &[u8], tqs: &[usize]) -> Vec<CompInfo> {
    let max_h = samp.iter().map(|s| s.0).max().unwrap();
    let max_v = samp.iter().map(|s| s.1).max().unwrap();
    let mcux = (width + 8 * max_h - 1) / (8 * max_h);
    let mcuy = (height + 8 * max_v - 1) / (8 * max_v);
    samp.iter()
        .enumerate()
        .map(|(i, &(h, v))| CompInfo {
            id: ids[i],
            h,
            v,
            tq: tqs[i],
            width_in_blocks: (width * h + 8 * max_h - 1) / (8 * max_h),
            height_in_blocks: (height * v + 8 * max_v - 1) / (8 * max_v),
            bw: mcux * h,
            bh: mcuy * v,
        })
        .collect()
}

/// Downsample a full-resolution plane into a padded component plane of
/// (width_in_blocks*8) x (iMCU rows * v * 8) samples.
pub fn downsample(
    plane: &[u8],
    width: usize,
    height: usize,
    max_h: usize,
    max_v: usize,
    c: &CompInfo,
) -> (Vec<u8>, usize, usize) {
    let h_expand = max_h / c.h;
    let v_expand = max_v / c.v;
    let out_cols = c.width_in_blocks * 8;
    let imcu_rows = (height + 8 * max_v - 1) / (8 * max_v);
    let out_rows = imcu_rows * c.v * 8;
    // input rows padded to a multiple of max_v by replicating the last row,
    // columns expanded to out_cols * h_expand by replicating the last column
    let in_cols = out_cols * h_expand;
    let in_rows_padded = (height + max_v - 1) / max_v * max_v;
    let get_row = |y: usize| -> Vec<u8> {
        let yy = y.min(height - 1);
        let mut r = Vec::with_capacity(in_cols);
        r.extend_from_slice(&plane[yy * width..yy * width + width]);
        let last = plane[yy * width + width - 1];
        while r.len() < in_cols {
            r.push(last);
        }
        r.truncate(in_cols);
        r
    };
    let real_out_rows = in_rows_padded / v_expand;
    let mut out = vec![0u8; out_cols * out_rows];
    for oy in 0..real_out_rows {
        let rows: Vec<Vec<u8>> = (0..v_expand).map(|k| get_row(oy * v_expand + k)).collect();
        let o = &mut out[oy * out_cols..(oy + 1) * out_cols];
        if h_expand == 1 && v_expand == 1 {
            o.copy_from_slice(&rows[0][..out_cols]);
        } else if h_expand == 2 && v_expand == 1 {
            let mut bias = 0u32;
            for x in 0..out_cols {
                o[x] = ((rows[0][2 * x] as u32 + rows[0][2 * x + 1] as u32 + bias) >> 1) as u8;
                bias ^= 1;
            }
        } else if h_expand == 2 && v_expand == 2 {
            let mut bias = 1u32;
            for x in 0..out_cols {
                o[x] = ((rows[0][2 * x] as u32
                    + rows[0][2 * x + 1] as u32
                    + rows[1][2 * x] as u32
                    + rows[1][2 * x + 1] as u32
                    + bias)
                    >> 2) as u8;
                bias ^= 3;
            }
        } else {
            let numpix = (h_expand * v_expand) as u32;
            let numpix2 = numpix / 2;
            for x in 0..out_cols {
                let mut s = 0u32;
                for r in rows.iter() {
                    for k in 0..h_expand {
                        s += r[x * h_expand + k] as u32;
                    }
                }
                o[x] = ((s + numpix2) / numpix) as u8;
            }
        }
    }
    // pad bottom by replicating last real downsampled row
    if real_out_rows > 0 {
        for oy in real_out_rows..out_rows {
            let (a, b) = out.split_at_mut(oy * out_cols);
            b[..out_cols].copy_from_slice(&a[(real_out_rows - 1) * out_cols..real_out_rows * out_cols]);
        }
    }
    (out, out_cols, out_rows)
}

