const FIX_2_562915447: i64 = 20995;
const FIX_3_072711026: i64 = 25172;

#[inline]
fn descale(x: i64, n: i32) -> i64 {
    (x + (1i64 << (n - 1))) >> n
}

pub fn fdct_islow(data: &mut [i32; 64]) {
    for r in 0..8 {
        let d = &mut data[r * 8..r * 8 + 8];
        let tmp0 = (d[0] + d[7]) as i64;
        let tmp7 = (d[0] - d[7]) as i64;
