        d[4] = ((tmp10 - tmp11) << PASS1_BITS) as i32;
        let z1 = (tmp12 + tmp13) * FIX_0_541196100;
        d[2] = descale(z1 + tmp13 * FIX_0_765366865, CONST_BITS - PASS1_BITS) as i32;
        d[6] = descale(z1 + tmp12 * (-FIX_1_847759065), CONST_BITS - PASS1_BITS) as i32;
        let z1 = tmp4 + tmp7;
        let z2 = tmp5 + tmp6;
        let z3 = tmp4 + tmp6;
        let z4 = tmp5 + tmp7;
        let z5 = (z3 + z4) * FIX_1_175875602;
        let t4 = tmp4 * FIX_0_298631336;
        let t5 = tmp5 * FIX_2_053119869;
        let t6 = tmp6 * FIX_3_072711026;
        let t7 = tmp7 * FIX_1_501321110;
        let z1 = z1 * (-FIX_0_899976223);
        let z2 = z2 * (-FIX_2_562915447);
        let z3 = z3 * (-FIX_1_961570560) + z5;
        let z4 = z4 * (-FIX_0_390180644) + z5;
        d[7] = descale(t4 + z1 + z3, CONST_BITS - PASS1_BITS) as i32;
        d[5] = descale(t5 + z2 + z4, CONST_BITS - PASS1_BITS) as i32;
        d[3] = descale(t6 + z2 + z3, CONST_BITS - PASS1_BITS) as i32;
        d[1] = descale(t7 + z1 + z4, CONST_BITS - PASS1_BITS) as i32;
    }
    for c in 0..8 {
        let g = |r: usize| data[r * 8 + c] as i64;
        let tmp0 = g(0) + g(7);
        let tmp7 = g(0) - g(7);
        let tmp1 = g(1) + g(6);
        let tmp6 = g(1) - g(6);
        let tmp2 = g(2) + g(5);
        let tmp5 = g(2) - g(5);
        let tmp3 = g(3) + g(4);
        let tmp4 = g(3) - g(4);
        let tmp10 = tmp0 + tmp3;
        let tmp13 = tmp0 - tmp3;
        let tmp11 = tmp1 + tmp2;
        let tmp12 = tmp1 - tmp2;
        let mut o = [0i64; 8];
        o[0] = descale(tmp10 + tmp11, PASS1_BITS);
        o[4] = descale(tmp10 - tmp11, PASS1_BITS);
        let z1 = (tmp12 + tmp13) * FIX_0_541196100;
        o[2] = descale(z1 + tmp13 * FIX_0_765366865, CONST_BITS + PASS1_BITS);
        o[6] = descale(z1 + tmp12 * (-FIX_1_847759065), CONST_BITS + PASS1_BITS);
        let z1 = tmp4 + tmp7;
        let z2 = tmp5 + tmp6;
        let z3 = tmp4 + tmp6;
        let z4 = tmp5 + tmp7;
        let z5 = (z3 + z4) * FIX_1_175875602;
        let t4 = tmp4 * FIX_0_298631336;
        let t5 = tmp5 * FIX_2_053119869;
        let t6 = tmp6 * FIX_3_072711026;
        let t7 = tmp7 * FIX_1_501321110;
        let z1 = z1 * (-FIX_0_899976223);
        let z2 = z2 * (-FIX_2_562915447);
        let z3 = z3 * (-FIX_1_961570560) + z5;
        let z4 = z4 * (-FIX_0_390180644) + z5;
        o[7] = descale(t4 + z1 + z3, CONST_BITS + PASS1_BITS);
        o[5] = descale(t5 + z2 + z4, CONST_BITS + PASS1_BITS);
        o[3] = descale(t6 + z2 + z3, CONST_BITS + PASS1_BITS);
        o[1] = descale(t7 + z1 + z4, CONST_BITS + PASS1_BITS);
        for r in 0..8 {
            data[r * 8 + c] = o[r] as i32;
        }
    }
}

pub fn quantize_plain(raw: &[i32; 64], q: &[u16; 64]) -> [i16; 64] {
    let mut out = [0i16; 64];
    for i in 0..64 {
        let qv = (q[i] as i32) << 3;
        let t = raw[i];
        let v = if t < 0 { -((-t + (qv >> 1)) / qv) } else { (t + (qv >> 1)) / qv };
        out[i] = v as i16;
    }
    out
}

