    Some(if le { u16::from_le_bytes([b[0], b[1]]) } else { u16::from_be_bytes([b[0], b[1]]) })
}

fn rd32(d: &[u8], p: usize, le: bool) -> Option<u32> {
    let b = d.get(p..p + 4)?;
    Some(if le {
        u32::from_le_bytes([b[0], b[1], b[2], b[3]])
    } else {
        u32::from_be_bytes([b[0], b[1], b[2], b[3]])
    })
}

/// Parse the orientation tag (0x0112) of IFD0 in a TIFF structure.
pub fn orientation_from_tiff(d: &[u8]) -> Option<u16> {
    if d.len() < 8 {
        return None;
    }
    let le = match &d[0..2] {
        b"II" => true,
        b"MM" => false,
        _ => return None,
    };
    let ifd = rd32(d, 4, le)? as usize;
    let n = rd16(d, ifd, le)? as usize;
