        let (_, px) = jpeg::to_pixels(&j);
        let p = je::rgb_to_ycc(&px, w * h);
        p.to_vec()
    } else {
        jpeg::full_planes(&j)
    };
    let table = je::scaled_table(je::quality_scaling(q));
    let samp: Vec<(usize, usize)> = r.components.iter().map(|c| (c.h, c.v)).collect();
    let ids: Vec<u8> = r.components.iter().map(|c| c.id).collect();
    let geo = je::comp_geometry(w, h, &samp, &ids, &[0, 1, 1]);
    let max_h = samp.iter().map(|s| s.0).max().unwrap();
    let max_v = samp.iter().map(|s| s.1).max().unwrap();
    for (ci, c) in geo.iter().enumerate() {
        let (ds, cols, _rows) = je::downsample(&planes[ci], w, h, max_h, max_v, c);
        let rc = &r.components[ci];
        let (mut eq, mut tot, mut zero_in_ref, mut absdiff1, mut other) = (0u64, 0u64, 0u64, 0u64, 0u64);
        let mut dc_eq = 0u64;
        for by in 0..c.height_in_blocks {
            for bx in 0..c.width_in_blocks {
                let mut blk = [0i32; 64];
                for y in 0..8 {
                    for x in 0..8 {
                        blk[y * 8 + x] = ds[(by * 8 + y) * cols + bx * 8 + x] as i32 - 128;
                    }
                }
                je::fdct_islow(&mut blk);
                let qb = je::quantize_plain(&blk, &table);
                let rb = &rc.coefs[by * rc.bw + bx];
                for k in 0..64 {
                    tot += 1;
                    if qb[k] == rb[k] { eq += 1; if k == 0 { dc_eq += 1; } }
                    else if rb[k] == 0 { zero_in_ref += 1; }
                    else if (qb[k] - rb[k]).abs() == 1 { absdiff1 += 1; }
                    else { other += 1; }
                }
            }
        }
        let nb = (c.height_in_blocks * c.width_in_blocks) as u64;
        println!("comp {} eq {:.4} zero_in_ref {:.4} diff1 {:.4} other {:.4} dc_eq {:.4}", ci, eq as f64 / tot as f64, zero_in_ref as f64 / tot as f64, absdiff1 as f64 / tot as f64, other as f64/tot as f64, dc_eq as f64 / nb as f64);
    }
}
