#[derive(Clone, Debug)]
pub struct HuffTable {
    pub bits: [u8; 17], // bits[1..=16]
    pub vals: Vec<u8>,
    pub ehufco: [u32; 256],
    pub ehufsi: [u8; 256],
}

impl HuffTable {
    pub fn from_spec(bits16: &[u8; 16], vals: &[u8]) -> HuffTable {
        let mut bits = [0u8; 17];
        bits[1..].copy_from_slice(bits16);
        Self::build(bits, vals.to_vec())
    }

    pub fn build(bits: [u8; 17], vals: Vec<u8>) -> HuffTable {
        let mut huffsize = Vec::new();
        for l in 1..=16 {
            for _ in 0..bits[l] {
                huffsize.push(l as u8);
            }
        }
        let mut huffcode = Vec::with_capacity(huffsize.len());
        let mut code = 0u32;
        let mut si = huffsize.first().copied().unwrap_or(0);
        let mut p = 0;
        while p < huffsize.len() {
            while p < huffsize.len() && huffsize[p] == si {
                huffcode.push(code);
                code += 1;
                p += 1;
            }
            code <<= 1;
            si += 1;
        }
        let mut ehufco = [0u32; 256];
        let mut ehufsi = [0u8; 256];
        for (i, &v) in vals.iter().enumerate() {
            ehufco[v as usize] = huffcode[i];
            ehufsi[v as usize] = huffsize[i];
        }
        HuffTable { bits, vals, ehufco, ehufsi }
    }

    pub fn optimal(freq_in: &[u32; 257]) -> HuffTable {
        let mut freq = [0i64; 257];
        for i in 0..257 {
            freq[i] = freq_in[i] as i64;
        }
        freq[256] = 1;
        let mut bits = [0u32; 33];
        let mut codesize = [0i32; 257];
        let mut others = [-1i32; 257];
        loop {
            let mut c1: i32 = -1;
            let mut v: i64 = 1_000_000_000;
            for i in 0..257 {
                if freq[i] != 0 && freq[i] <= v {
                    v = freq[i];
                    c1 = i as i32;
                }
            }
            let mut c2: i32 = -1;
            v = 1_000_000_000;
            for i in 0..257 {
                if freq[i] != 0 && freq[i] <= v && i as i32 != c1 {
                    v = freq[i];
                    c2 = i as i32;
                }
            }
            if c2 < 0 {
                break;
            }
            let (mut a, mut b) = (c1 as usize, c2 as usize);
            freq[a] += freq[b];
            freq[b] = 0;
            codesize[a] += 1;
            while others[a] >= 0 {
                a = others[a] as usize;
                codesize[a] += 1;
            }
            others[a] = b as i32;
            codesize[b] += 1;
            while others[b] >= 0 {
                b = others[b] as usize;
                codesize[b] += 1;
            }
        }
        for i in 0..257 {
            if codesize[i] != 0 {
                let cs = (codesize[i] as usize).min(32);
                bits[cs] += 1;
            }
        }
        let mut i = 32;
        while i > 16 {
            while bits[i] > 0 {
                let mut j = i - 2;
                while bits[j] == 0 {
                    j -= 1;
                }
                bits[i] -= 2;
                bits[i - 1] += 1;
                bits[j + 1] += 2;
                bits[j] -= 1;
            }
            i -= 1;
        }
        while bits[i] == 0 {
            i -= 1;
        }
        bits[i] -= 1;
        let mut out_bits = [0u8; 17];
        for l in 1..=16 {
            out_bits[l] = bits[l] as u8;
        }
        let mut vals = Vec::new();
        for l in 1..=32 {
            for j in 0..256 {
                if codesize[j] == l {
                    vals.push(j as u8);
                }
            }
        }
        HuffTable::build(out_bits, vals)
    }
}

// ---------------------------------------------------------------------------
// Bit writer with JPEG byte stuffing

pub struct BitWriter {
    pub out: Vec<u8>,
    acc: u64,
    nbits: u32,
}

impl BitWriter {
    pub fn new() -> Self {
        BitWriter { out: Vec::new(), acc: 0, nbits: 0 }
    }
    #[inline]
    pub fn put(&mut self, code: u32, size: u32) {
        if size == 0 {
            return;
        }
        let code = (code as u64) & ((1u64 << size) - 1);
        self.acc = (self.acc << size) | code;
        self.nbits += size;
        while self.nbits >= 8 {
            let c = ((self.acc >> (self.nbits - 8)) & 0xFF) as u8;
            self.out.push(c);
            if c == 0xFF {
                self.out.push(0);
            }
            self.nbits -= 8;
        }
        self.acc &= (1u64 << self.nbits) - 1;
    }
    pub fn flush(&mut self) {
        self.put(0x7F, 7);
        self.acc = 0;
        self.nbits = 0;
    }
}

/// Symbol sink: either gathers statistics or emits codes.
pub struct Coder<'a> {
    pub gather: bool,
    pub counts: [[u32; 257]; 4],
    pub tables: [Option<&'a HuffTable>; 4],
    pub w: BitWriter,
}

impl<'a> Coder<'a> {
    pub fn gatherer() -> Self {
        Coder { gather: true, counts: [[0; 257]; 4], tables: [None; 4], w: BitWriter::new() }
    }
    pub fn emitter(tables: [Option<&'a HuffTable>; 4]) -> Self {
        Coder { gather: false, counts: [[0; 257]; 4], tables, w: BitWriter::new() }
    }
    #[inline]
    fn sym(&mut self, tbl: usize, s: usize) {
        if self.gather {
            self.counts[tbl][s] += 1;
        } else {
            let t = self.tables[tbl].unwrap();
            self.w.put(t.ehufco[s], t.ehufsi[s] as u32);
        }
    }
    #[inline]
    fn bits(&mut self, v: u32, n: u32) {
        if !self.gather {
            self.w.put(v, n);
        }
    }
}

#[inline]
fn nbits_of(mut v: u32) -> u32 {
    let mut n = 0;
    while v != 0 {
        n += 1;
        v >>= 1;
    }
    n
}

/// Coefficient storage for one component (padded to whole MCUs).
#[derive(Clone)]
pub struct CompCoefs {
    pub info: CompInfo,
    pub blocks: Vec<[i16; 64]>, // natural order
}

impl CompCoefs {
    #[inline]
    pub fn blk(&self, bx: usize, by: usize) -> &[i16; 64] {
        &self.blocks[by * self.info.bw + bx]
    }
}

/// Fill the MCU padding blocks: AC zero, DC copied from the neighbour.
pub fn fill_dummy_blocks(c: &mut CompCoefs) {
    let info = c.info.clone();
    let wb = info.width_in_blocks;
    let hb = info.height_in_blocks;
    for by in 0..hb {
        for bx in wb..info.bw {
            let dc = c.blocks[by * info.bw + bx - 1][0];
            let mut b = [0i16; 64];
            b[0] = dc;
            c.blocks[by * info.bw + bx] = b;
        }
    }
    for by in hb..info.bh {
        let mcus = info.bw / info.h;
        for m in 0..mcus {
            let dc = c.blocks[(by - 1) * info.bw + m * info.h + info.h - 1][0];
            for k in 0..info.h {
                let mut b = [0i16; 64];
                b[0] = dc;
                c.blocks[by * info.bw + m * info.h + k] = b;
            }
        }
    }
}

#[derive(Clone, Copy, Debug)]
pub struct Scan {
    pub comps: [usize; 4],
    pub ncomps: usize,
    pub ss: usize,
    pub se: usize,
    pub ah: u32,
    pub al: u32,
}

impl Scan {
    pub fn new(comps: &[usize], ss: usize, se: usize, ah: u32, al: u32) -> Scan {
        let mut c = [0usize; 4];
        c[..comps.len()].copy_from_slice(comps);
        Scan { comps: c, ncomps: comps.len(), ss, se, ah, al }
    }
}

/// Iterate over blocks of a scan in coding order calling f(component index, block).
fn for_each_block<F: FnMut(usize, &[i16; 64])>(comps: &[CompCoefs], scan: &Scan, width: usize, height: usize, mut f: F) {
    if scan.ncomps == 1 {
        let c = &comps[scan.comps[0]];
        for by in 0..c.info.height_in_blocks {
            for bx in 0..c.info.width_in_blocks {
                f(0, c.blk(bx, by));
            }
        }
    } else {
        let max_h = comps.iter().map(|c| c.info.h).max().unwrap();
        let max_v = comps.iter().map(|c| c.info.v).max().unwrap();
        let mcux = (width + 8 * max_h - 1) / (8 * max_h);
        let mcuy = (height + 8 * max_v - 1) / (8 * max_v);
        for my in 0..mcuy {
            for mx in 0..mcux {
                for si in 0..scan.ncomps {
                    let c = &comps[scan.comps[si]];
                    for y in 0..c.info.v {
                        for x in 0..c.info.h {
                            f(si, c.blk(mx * c.info.h + x, my * c.info.v + y));
                        }
                    }
                }
            }
        }
    }
}

/// Encode (or gather) a sequential scan with DC+AC for all components.
pub fn code_sequential(comps: &[CompCoefs], scan: &Scan, width: usize, height: usize, dc_tbl: &[usize], ac_tbl: &[usize], coder: &mut Coder) {
    let mut last_dc = [0i32; 4];
    let dc_off = 0usize;
    for_each_block(comps, scan, width, height, |si, b| {
        let dct = dc_tbl[si];
        let act = ac_tbl[si] + 2;
        let _ = dc_off;
        let mut temp = b[0] as i32 - last_dc[si];
        last_dc[si] = b[0] as i32;
        let mut temp2 = temp;
        if temp < 0 {
            temp = -temp;
            temp2 -= 1;
        }
        let nb = nbits_of(temp as u32);
        coder.sym(dct, nb as usize);
        coder.bits(temp2 as u32, nb);
        let mut r = 0usize;
        for k in 1..64 {
            let mut t = b[ZIGZAG[k]] as i32;
            if t == 0 {
                r += 1;
                continue;
            }
            while r > 15 {
                coder.sym(act, 0xF0);
                r -= 16;
            }
            let mut t2 = t;
            if t < 0 {
                t = -t;
                t2 -= 1;
            }
            let nb = nbits_of(t as u32);
            coder.sym(act, (r << 4) + nb as usize);
            coder.bits(t2 as u32, nb);
            r = 0;
        }
        if r > 0 {
            coder.sym(act, 0);
        }
    });
}

struct PhuffState {
    eobrun: u32,
    be: Vec<u8>,
}

fn emit_eobrun(coder: &mut Coder, st: &mut PhuffState, tbl: usize) {
    if st.eobrun > 0 {
        let mut temp = st.eobrun;
        let mut nb = 0;
        loop {
            temp >>= 1;
            if temp == 0 {
                break;
            }
            nb += 1;
        }
        coder.sym(tbl, (nb << 4) as usize);
        if nb > 0 {
            coder.bits(st.eobrun, nb);
        }
        st.eobrun = 0;
        if !coder.gather {
            for &bit in st.be.iter() {
                coder.w.put(bit as u32, 1);
            }
        }
        st.be.clear();
    }
}

/// Encode (or gather) a progressive scan. Table indices: DC 0..1, AC 2..3.
pub fn code_progressive(comps: &[CompCoefs], scan: &Scan, width: usize, height: usize, coder: &mut Coder) {
    let al = scan.al;
    let tbl_of = |ci: usize, ac: bool| -> usize {
        let t = if ci == 0 { 0 } else { 1 };
        if ac {
            t + 2
        } else {
            t
        }
    };
    if scan.ss == 0 {
        let mut last_dc = [0i32; 4];
        let ah = scan.ah;
        for_each_block(comps, scan, width, height, |si, b| {
            let ci = scan.comps[si];
            if ah == 0 {
                let t2 = (b[0] as i32) >> al;
                let mut temp = t2 - last_dc[si];
                last_dc[si] = t2;
                let mut temp2 = temp;
                if temp < 0 {
                    temp = -temp;
                    temp2 -= 1;
                }
                let nb = nbits_of(temp as u32);
                coder.sym(tbl_of(ci, false), nb as usize);
                coder.bits(temp2 as u32, nb);
            } else {
                coder.bits(((b[0] as i32) >> al) as u32 & 1, 1);
            }
        });
        if !coder.gather {
            coder.w.flush();
        }
        return;
    }
    let ci = scan.comps[0];
    let tbl = tbl_of(ci, true);
    let mut st = PhuffState { eobrun: 0, be: Vec::new() };
    let ss = scan.ss;
    let se = scan.se;
    if scan.ah == 0 {
        for_each_block(comps, scan, width, height, |_, b| {
            let mut r = 0usize;
            for k in ss..=se {
                let mut temp = b[ZIGZAG[k]] as i32;
                if temp == 0 {
                    r += 1;
                    continue;
                }
                let temp2;
                if temp < 0 {
                    temp = -temp;
                    temp >>= al;
                    temp2 = !temp;
                } else {
                    temp >>= al;
                    temp2 = temp;
                }
                if temp == 0 {
                    r += 1;
                    continue;
                }
                if st.eobrun > 0 {
                    emit_eobrun(coder, &mut st, tbl);
                }
                while r > 15 {
                    coder.sym(tbl, 0xF0);
                    r -= 16;
                }
                let nb = nbits_of(temp as u32);
                coder.sym(tbl, (r << 4) + nb as usize);
                coder.bits(temp2 as u32, nb);
                r = 0;
            }
            if r > 0 {
                st.eobrun += 1;
                if st.eobrun == 0x7FFF {
                    emit_eobrun(coder, &mut st, tbl);
                }
            }
        });
    } else {
        let mut absvalues = [0i32; 64];
        for_each_block(comps, scan, width, height, |_, b| {
            let mut eob = 0usize;
            for k in ss..=se {
                let mut t = b[ZIGZAG[k]] as i32;
                if t < 0 {
                    t = -t;
                }
                t >>= al;
                absvalues[k] = t;
                if t == 1 {
                    eob = k;
                }
            }
            let mut r = 0usize;
            let mut br: Vec<u8> = Vec::new();
            for k in ss..=se {
                let temp = absvalues[k];
                if temp == 0 {
                    r += 1;
                    continue;
                }
                while r > 15 && k <= eob {
                    emit_eobrun(coder, &mut st, tbl);
                    coder.sym(tbl, 0xF0);
                    r -= 16;
                    if !coder.gather {
                        for &bit in br.iter() {
                            coder.w.put(bit as u32, 1);
                        }
                    }
                    br.clear();
                }
                if temp > 1 {
                    br.push((temp & 1) as u8);
                    continue;
                }
                emit_eobrun(coder, &mut st, tbl);
                coder.sym(tbl, (r << 4) + 1);
                let bit = if b[ZIGZAG[k]] < 0 { 0 } else { 1 };
                coder.bits(bit, 1);
                if !coder.gather {
                    for &bit in br.iter() {
                        coder.w.put(bit as u32, 1);
                    }
                }
                br.clear();
                r = 0;
            }
            if r > 0 || !br.is_empty() {
                st.eobrun += 1;
                st.be.extend_from_slice(&br);
                if st.eobrun == 0x7FFF || st.be.len() > (1000 - 64 + 1) {
                    emit_eobrun(coder, &mut st, tbl);
                }
            }
        });
    }
    emit_eobrun(coder, &mut st, tbl);
    if !coder.gather {
        coder.w.flush();
    }
}
