// ---------------------------------------------------------------------------
// Overshoot deringing for blocks touching the maximum sample value

fn catmull_rom(v1: i32, v2: i32, v3: i32, v4: i32, t: f32, size: i32) -> f32 {
    let tan1 = (v3 - v1) * size;
    let tan2 = (v4 - v2) * size;
    let t2 = t * t;
    let t3 = t2 * t;
    let f1 = 2.0f32 * t3 - 3.0f32 * t2 + 1.0f32;
    let f2 = -2.0f32 * t3 + 3.0f32 * t2;
    let f3 = t3 - 2.0f32 * t2 + t;
    let f4 = t3 - t2;
    v2 as f32 * f1 + tan1 as f32 * f3 + v3 as f32 * f2 + tan2 as f32 * f4
}

pub fn preprocess_deringing(data: &mut [i32; 64], q0: u16) {
    let maxsample: i32 = 255 - 128;
    let size: i32 = 64;
    let mut sum = 0i32;
    let mut maxcount = 0i32;
    for i in 0..64 {
        sum += data[i];
        if data[i] >= maxsample {
            maxcount += 1;
        }
    }
    if maxcount == 0 || maxcount == size {
        return;
    }
    let maxovershoot = maxsample + 31.min(2 * q0 as i32).min((maxsample * size - sum) / maxcount);
    let nat = &ZIGZAG;
    let mut n = 0usize;
    loop {
        if data[nat[n]] < maxsample {
            n += 1;
            if n >= 64 {
                break;
            }
            continue;
        }
        let start = n;
        loop {
            n += 1;
            if !(n < 64 && data[nat[n]] >= maxsample) {
                break;
            }
        }
        let end = n;
        let f1 = data[nat[if start >= 1 { start - 1 } else { 0 }]];
        let f2 = data[nat[if start >= 2 { start - 2 } else { 0 }]];
        let l1 = data[nat[if end < 63 { end } else { 63 }]];
        let l2 = data[nat[if end < 62 { end + 1 } else { 63 }]];
        let mut fslope = (f1 - f2).max(maxsample - f1);
        let mut lslope = (l1 - l2).max(maxsample - l1);
        if start == 0 {
            fslope = lslope;
        }
        if end == 64 {
            lslope = fslope;
        }
        let length = (end - start) as i32;
        let step = 1.0f32 / (length + 1) as f32;
        let mut position = step;
        for i in start..end {
            let tmp = catmull_rom(maxsample - fslope, maxsample, maxsample, maxsample - lslope, position, length).ceil() as i32;
            data[nat[i]] = tmp.min(maxovershoot);
            position += step;
        }
        n += 1;
        if n >= 64 {
            break;
        }
    }
}

// ---------------------------------------------------------------------------
// Trellis quantization

pub struct TrellisCfg {
    pub lambda_log_scale1: f64,
    pub lambda_log_scale2: f64,
    pub dc: bool,
}

fn dc_candidates(q0: u16) -> usize {
    // number of DC candidates examined around the rounded value
    let n = ((q0 as usize) + 7) >> 3;
    n.clamp(1, 9)
}

/// Rate/distortion quantization of a row of blocks.
#[allow(clippy::too_many_arguments)]
pub fn quantize_trellis(
    cfg: &TrellisCfg,
    dctbl: &HuffTable,
    actbl: &HuffTable,
    out: &mut [[i16; 64]],
    src: &[[i32; 64]],
    qt: &[u16; 64],
    last_dc: &mut i32,
) {
    let nblocks = src.len();
    let ss = 1usize;
    let se = 63usize;
    let mut lambda_table = [0f32; 64];
    for i in 0..64 {
        lambda_table[i] = 1.0f32 / ((qt[i] as f32) * (qt[i] as f32));
    }
    let lambda_base = 1.0f32;
    let ncand = if cfg.dc { dc_candidates(qt[0]) } else { 1 };
    let mut acc_dc_cost: Vec<Vec<f32>> = vec![vec![0f32; nblocks]; ncand];
    let mut dc_backtrack: Vec<Vec<i32>> = vec![vec![0i32; nblocks]; ncand];
    let mut dc_cand: Vec<Vec<i32>> = vec![vec![0i32; nblocks]; ncand];
    let mut acc_zero_dist = [0f32; 64];
    let mut acc_cost = [0f32; 64];
    let mut run_start = [0usize; 64];
    for bi in 0..nblocks {
        let s = &src[bi];
        let mut norm = 0f32;
        for i in 1..64 {
            norm += (s[i] * s[i]) as f32;
        }
        norm /= 63.0;
        let lambda: f32 = if cfg.lambda_log_scale2 > 0.0 {
            (2f64.powf(cfg.lambda_log_scale1) * lambda_base as f64 / (2f64.powf(cfg.lambda_log_scale2) + norm as f64)) as f32
        } else {
            (2f64.powf(cfg.lambda_log_scale1 - 12.0) * lambda_base as f64) as f32
        };
        let lambda_dc = lambda * lambda_table[0];
        acc_zero_dist[ss - 1] = 0.0;
        acc_cost[ss - 1] = 0.0;
        if cfg.dc {
            let sign = s[0] >> 31;
            let x = s[0].abs();
            let q = 8 * qt[0] as i32;
            let qval = (x + q / 2) / q;
            for k in 0..ncand {
                let mut c = qval - (ncand as i32) / 2 + k as i32;
                if c >= (1 << 10) {
                    c = (1 << 10) - 1;
                }
                let delta = c * q - x;
                let dist = (delta * delta) as f32 * lambda_dc;
                c *= 1 + 2 * sign;
                dc_cand[k][bi] = c;
                if bi == 0 {
                    let d = (c - *last_dc).unsigned_abs();
                    let bits = nbits_of(d);
                    let cost = bits as f32 + dctbl.ehufsi[bits as usize] as f32 + dist;
                    acc_dc_cost[k][0] = cost;
                    dc_backtrack[k][0] = -1;
                } else {
                    for l in 0..ncand {
                        let d = (c - dc_cand[l][bi - 1]).unsigned_abs();
                        let bits = nbits_of(d);
                        let cost = bits as f32 + dctbl.ehufsi[bits as usize] as f32 + dist + acc_dc_cost[l][bi - 1];
                        if l == 0 || cost < acc_dc_cost[k][bi] {
                            acc_dc_cost[k][bi] = cost;
                            dc_backtrack[k][bi] = l as i32;
                        }
                    }
                }
            }
        }
        let blk = &mut out[bi];
        for i in ss..=se {
            let z = ZIGZAG[i];
            let sign = s[z] >> 31;
            let x = s[z].abs();
            let q = 8 * qt[z] as i32;
            acc_zero_dist[i] = (x * x) as f32 * lambda * lambda_table[z] + acc_zero_dist[i - 1];
            let mut qval = (x + q / 2) / q;
            if qval == 0 {
                blk[z] = 0;
                acc_cost[i] = 1e38;
                continue;
            }
            if qval >= (1 << 10) {
                qval = (1 << 10) - 1;
            }
            let ncand_ac = nbits_of(qval as u32) as usize;
            let mut cand = [0i32; 16];
            let mut cand_bits = [0usize; 16];
            let mut cand_dist = [0f32; 16];
            for k in 0..ncand_ac {
                cand[k] = if k < ncand_ac - 1 { (2 << k) - 1 } else { qval };
                let delta = cand[k] * q - x;
                cand_bits[k] = k + 1;
                cand_dist[k] = (delta * delta) as f32 * lambda * lambda_table[z];
            }
            acc_cost[i] = 1e38;
            for j in (ss - 1)..i {
                let zz = ZIGZAG[j];
                if j != ss - 1 && blk[zz] == 0 {
                    continue;
                }
                let mut zero_run = i - 1 - j;
                if (zero_run >> 4) != 0 && actbl.ehufsi[0xf0] == 0 {
                    continue;
                }
                let run_bits = (zero_run >> 4) as i32 * actbl.ehufsi[0xf0] as i32;
                zero_run &= 15;
                for k in 0..ncand_ac {
                    let coef_bits = actbl.ehufsi[16 * zero_run + cand_bits[k]] as i32;
                    if coef_bits == 0 {
                        continue;
                    }
                    let rate = coef_bits + cand_bits[k] as i32 + run_bits;
                    let mut cost = rate as f32 + cand_dist[k];
                    cost += acc_zero_dist[i - 1] - acc_zero_dist[j] + acc_cost[j];
                    if cost < acc_cost[i] {
                        blk[z] = ((cand[k] ^ sign) - sign) as i16;
                        acc_cost[i] = cost;
                        run_start[i] = j;
                    }
                }
            }
        }
        let mut last_coeff_idx = ss - 1;
        let mut best_cost = acc_zero_dist[se] + actbl.ehufsi[0] as f32;
        for i in ss..=se {
            let z = ZIGZAG[i];
            if blk[z] != 0 {
                let mut cost = acc_cost[i] + acc_zero_dist[se] - acc_zero_dist[i];
                if i < se {
                    cost += actbl.ehufsi[0] as f32;
                }
                if cost < best_cost {
                    best_cost = cost;
                    last_coeff_idx = i;
                }
            }
        }
        // zero out coefficients that are part of runs
        let mut i = se as isize;
        while i >= ss as isize {
            while i > last_coeff_idx as isize {
                blk[ZIGZAG[i as usize]] = 0;
                i -= 1;
            }
            if i < ss as isize {
                break;
            }
            last_coeff_idx = run_start[i as usize];
            i -= 1;
        }
    }
    if cfg.dc && nblocks > 0 {
        let mut j = 0usize;
        for i in 1..ncand {
            if acc_dc_cost[i][nblocks - 1] < acc_dc_cost[j][nblocks - 1] {
                j = i;
            }
        }
        let mut jj = j as i32;
        for bi in (0..nblocks).rev() {
            out[bi][0] = dc_cand[jj as usize][bi] as i16;
            jj = dc_backtrack[jj as usize][bi];
        }
        *last_dc = out[nblocks - 1][0] as i32;
    } else if nblocks > 0 {
        *last_dc = out[nblocks - 1][0] as i32;
    }
}
