// ---------------------------------------------------------------------------
// Coefficient computation for lossy encoding

#[derive(Clone)]
pub struct LossyOptions {
    pub quality: i32,
    pub progressive: bool,
    /// sampling factors per component
    pub samp: Vec<(usize, usize)>,
    pub trellis: bool,
    pub deringing: bool,
    pub reset_dc_per_imcu: bool,
}

pub fn std_dc_table(chroma: bool) -> HuffTable {
    if chroma {
        HuffTable::from_spec(&DC_CHROMA_BITS, &DC_VALS)
    } else {
        HuffTable::from_spec(&DC_LUMA_BITS, &DC_VALS)
    }
}

/// planes: full resolution component samples (width*height each)
pub fn compute_coefficients(
    planes: &[Vec<u8>],
    width: usize,
    height: usize,
    ids: &[u8],
    opts: &LossyOptions,
) -> (Vec<CompCoefs>, Vec<[u16; 64]>) {
    let nc = planes.len();
    let table = scaled_table(quality_scaling(opts.quality));
    let qtables = if nc == 1 { vec![table] } else { vec![table, table] };
    let tqs: Vec<usize> = (0..nc).map(|c| if c == 0 { 0 } else { 1 }).collect();
    let geo = comp_geometry(width, height, &opts.samp, ids, &tqs);
    let max_h = opts.samp.iter().map(|s| s.0).max().unwrap();
    let max_v = opts.samp.iter().map(|s| s.1).max().unwrap();
    let mut comps = Vec::new();
    let mut raws: Vec<Vec<[i32; 64]>> = Vec::new();
    for (ci, info) in geo.iter().enumerate() {
        let (ds, cols, _rows) = downsample(&planes[ci], width, height, max_h, max_v, info);
        let q = &qtables[info.tq];
        let mut blocks = vec![[0i16; 64]; info.bw * info.bh];
        let mut raw = vec![[0i32; 64]; info.width_in_blocks * info.height_in_blocks];
        for by in 0..info.height_in_blocks {
            for bx in 0..info.width_in_blocks {
                let mut blk = [0i32; 64];
                for y in 0..8 {
                    let row = &ds[(by * 8 + y) * cols + bx * 8..(by * 8 + y) * cols + bx * 8 + 8];
                    for x in 0..8 {
                        blk[y * 8 + x] = row[x] as i32 - 128;
                    }
                }
                if opts.deringing {
                    preprocess_deringing(&mut blk, q[0]);
                }
                fdct_islow(&mut blk);
                blocks[by * info.bw + bx] = quantize_plain(&blk, q);
                raw[by * info.width_in_blocks + bx] = blk;
            }
        }
        comps.push(CompCoefs { info: info.clone(), blocks });
        raws.push(raw);
    }
    if opts.trellis {
        let cfg = TrellisCfg { lambda_log_scale1: 14.75, lambda_log_scale2: 16.5, dc: true };
        for ci in 0..nc {
            let scan = Scan::new(&[ci], 1, 63, 0, 0);
            let (dctbl, actbl) = if opts.progressive {
                let mut g = Coder::gatherer();
                code_progressive(&comps, &scan, width, height, &mut g);
                let t = if ci == 0 { 2 } else { 3 };
                (std_dc_table(ci != 0), HuffTable::optimal(&g.counts[t]))
            } else {
                let mut g = Coder::gatherer();
                let tb = if ci == 0 { 0 } else { 1 };
                code_sequential(&comps, &Scan::new(&[ci], 0, 63, 0, 0), width, height, &[tb], &[tb], &mut g);
                (HuffTable::optimal(&g.counts[tb]), HuffTable::optimal(&g.counts[tb + 2]))
            };
            let info = comps[ci].info.clone();
            let q = qtables[info.tq];
            let mut last_dc = 0i32;
            for by in 0..info.height_in_blocks {
                if opts.reset_dc_per_imcu && by % info.v == 0 {
                    last_dc = 0;
                }
                let wb = info.width_in_blocks;
                let mut row: Vec<[i16; 64]> = comps[ci].blocks[by * info.bw..by * info.bw + wb].to_vec();
                quantize_trellis(&cfg, &dctbl, &actbl, &mut row, &raws[ci][by * wb..(by + 1) * wb], &q, &mut last_dc);
                comps[ci].blocks[by * info.bw..by * info.bw + wb].copy_from_slice(&row);
            }
        }
    }
    for c in comps.iter_mut() {
        fill_dummy_blocks(c);
    }
    (comps, qtables)
}
