// ---------------------------------------------------------------------------
// Scan encoding and file assembly

fn put16(v: &mut Vec<u8>, x: usize) {
    v.push((x >> 8) as u8);
    v.push(x as u8);
}

fn dht_segment(tables: &[(u8, &HuffTable)]) -> Vec<u8> {
    let mut body = Vec::new();
    for (cls_idx, t) in tables {
        body.push(*cls_idx);
        body.extend_from_slice(&t.bits[1..17]);
        body.extend_from_slice(&t.vals);
    }
    let mut v = vec![0xFF, 0xC4];
    put16(&mut v, body.len() + 2);
    v.extend_from_slice(&body);
    v
}

fn sos_segment(comps: &[CompCoefs], scan: &Scan, progressive: bool, dc_sel: &[u8], ac_sel: &[u8]) -> Vec<u8> {
    let mut v = vec![0xFF, 0xDA];
    put16(&mut v, 6 + 2 * scan.ncomps);
    v.push(scan.ncomps as u8);
    for si in 0..scan.ncomps {
        let ci = scan.comps[si];
        let mut td = dc_sel[ci];
        let mut ta = ac_sel[ci];
        if progressive {
            if scan.ss == 0 {
                ta = 0;
                if scan.ah != 0 {
                    td = 0;
                }
            } else {
                td = 0;
            }
        }
        v.push(comps[ci].info.id);
        v.push((td << 4) | ta);
    }
    v.push(scan.ss as u8);
    v.push(scan.se as u8);
    v.push(((scan.ah << 4) | scan.al) as u8);
    v
}

/// Encode one progressive scan with its own optimal tables: DHT + SOS + data.
fn encode_progressive_scan(comps: &[CompCoefs], scan: &Scan, width: usize, height: usize) -> Vec<u8> {
    let mut g = Coder::gatherer();
    code_progressive(comps, scan, width, height, &mut g);
    let mut tables: [Option<HuffTable>; 4] = [None, None, None, None];
    let mut order: Vec<usize> = Vec::new();
    for si in 0..scan.ncomps {
        let ci = scan.comps[si];
        let t = if ci == 0 { 0 } else { 1 };
        let idx = if scan.ss == 0 {
            if scan.ah != 0 {
                continue;
            }
            t
        } else {
            t + 2
        };
        if tables[idx].is_none() {
            tables[idx] = Some(HuffTable::optimal(&g.counts[idx]));
            order.push(idx);
        }
    }
    let mut out = Vec::new();
    if !order.is_empty() {
        let list: Vec<(u8, &HuffTable)> = order
            .iter()
            .map(|&i| {
                let cls_idx = if i >= 2 { 0x10 | (i as u8 - 2) } else { i as u8 };
                (cls_idx, tables[i].as_ref().unwrap())
            })
            .collect();
        out.extend_from_slice(&dht_segment(&list));
    }
    let sel: Vec<u8> = (0..comps.len()).map(|c| if c == 0 { 0 } else { 1 }).collect();
    out.extend_from_slice(&sos_segment(comps, scan, true, &sel, &sel));
    let refs: [Option<&HuffTable>; 4] = [tables[0].as_ref(), tables[1].as_ref(), tables[2].as_ref(), tables[3].as_ref()];
    let mut e = Coder::emitter(refs);
    code_progressive(comps, scan, width, height, &mut e);
    out.extend_from_slice(&e.w.out);
    out
}

/// Candidate scan list used by the progressive search (YCbCr or gray).
fn search_scans(nc: usize) -> Vec<Scan> {
    let mut s = Vec::new();
    let all: Vec<usize> = (0..nc).collect();
    s.push(Scan::new(&all, 0, 0, 0, 0));
    s.push(Scan::new(&[0], 1, 8, 0, 0));
    s.push(Scan::new(&[0], 9, 63, 0, 0));
    for al in 0..3u32 {
        s.push(Scan::new(&[0], 1, 63, al + 1, al));
        s.push(Scan::new(&[0], 1, 8, 0, al + 1));
        s.push(Scan::new(&[0], 9, 63, 0, al + 1));
    }
    s.push(Scan::new(&[0], 1, 63, 0, 0));
    let splits = [2usize, 8, 5, 12, 18];
    for &f in splits.iter() {
        s.push(Scan::new(&[0], 1, f, 0, 0));
        s.push(Scan::new(&[0], f + 1, 63, 0, 0));
    }
    if nc == 3 {
        s.push(Scan::new(&[1, 2], 0, 0, 0, 0));
        s.push(Scan::new(&[1], 0, 0, 0, 0));
        s.push(Scan::new(&[2], 0, 0, 0, 0));
        s.push(Scan::new(&[1], 1, 8, 0, 0));
        s.push(Scan::new(&[1], 9, 63, 0, 0));
        s.push(Scan::new(&[2], 1, 8, 0, 0));
        s.push(Scan::new(&[2], 9, 63, 0, 0));
        for al in 0..2u32 {
            s.push(Scan::new(&[1], 1, 63, al + 1, al));
            s.push(Scan::new(&[2], 1, 63, al + 1, al));
            s.push(Scan::new(&[1], 1, 8, 0, al + 1));
            s.push(Scan::new(&[1], 9, 63, 0, al + 1));
            s.push(Scan::new(&[2], 1, 8, 0, al + 1));
            s.push(Scan::new(&[2], 9, 63, 0, al + 1));
        }
        s.push(Scan::new(&[1], 1, 63, 0, 0));
        s.push(Scan::new(&[2], 1, 63, 0, 0));
        for &f in splits.iter() {
            s.push(Scan::new(&[1], 1, f, 0, 0));
            s.push(Scan::new(&[1], f + 1, 63, 0, 0));
            s.push(Scan::new(&[2], 1, f, 0, 0));
            s.push(Scan::new(&[2], f + 1, 63, 0, 0));
        }
    }
    s
}

/// Progressive encoding with a search over successive approximation and
/// spectral split points. Returns the concatenated scan segments.
fn progressive_search(comps: &[CompCoefs], width: usize, height: usize) -> Vec<u8> {
    let nc = comps.len();
    let mut scans = search_scans(nc);
    let num_scans = scans.len();
    let al_max_luma = 3usize;
    let num_freq_splits = 5usize;
    let luma_dc = 1usize;
    let num_scans_luma = luma_dc + (3 * al_max_luma + 2) + (2 * num_freq_splits + 1);
    let luma_split_start = luma_dc + 3 * al_max_luma + 2;
    let (al_max_chroma, chroma_dc) = if nc == 3 { (2usize, 3usize) } else { (0, 0) };
    let chroma_split_start = num_scans_luma + chroma_dc + (6 * al_max_chroma + 4);
    let mut buffers: Vec<Option<Vec<u8>>> = vec![None; num_scans];
    let mut best_al_luma = 0usize;
    let mut best_al_chroma = 0usize;
    let mut best_split_luma = 0usize;
    let mut best_split_chroma = 0usize;
    let mut best_cost: usize = 0;
    let mut sn = 0usize;
    while sn < num_scans {
        // Al of frequency split scans follows the selected successive approximation
        if sn >= luma_split_start && sn < num_scans_luma {
            scans[sn].al = best_al_luma as u32;
        }
        if nc == 3 && sn >= chroma_split_start {
            scans[sn].al = best_al_chroma as u32;
        }
        let buf = encode_progressive_scan(comps, &scans[sn], width, height);
        buffers[sn] = Some(buf);
        let size = |i: usize, b: &Vec<Option<Vec<u8>>>| -> usize { b[i].as_ref().map(|v| v.len()).unwrap_or(0) };
        let next = sn + 1;
        let mut jump: Option<usize> = None;
        if next > 1 && next <= luma_split_start {
            if (next - 1) % 3 == 2 {
                let al = (next - 1) / 3;
                let mut cost = size(next - 2, &buffers) + size(next - 1, &buffers);
                for i in 0..al {
                    cost += size(3 + 3 * i, &buffers);
                }
                if al == 0 || cost < best_cost {
                    best_cost = cost;
                    best_al_luma = al;
                } else {
                    jump = Some(luma_split_start);
                }
            }
        } else if next > luma_split_start && next <= num_scans_luma {
            if next == luma_split_start + 1 {
                best_split_luma = 0;
                best_cost = size(next - 1, &buffers);
            } else if (next - luma_split_start) % 2 == 1 {
                let idx = (next - luma_split_start) >> 1;
                let cost = size(next - 2, &buffers) + size(next - 1, &buffers);
                if cost < best_cost {
                    best_cost = cost;
                    best_split_luma = idx;
                }
                if (idx == 2 && best_split_luma == 0) || (idx == 3 && best_split_luma != 2) || (idx == 4 && best_split_luma != 4) {
                    jump = Some(num_scans_luma);
                }
            }
        } else if nc > 1 {
            let base = num_scans_luma + chroma_dc;
            if next == base {
                // chroma DC interleaving decision (not used with combined DC scan)
            } else if next > base && next <= chroma_split_start {
                if (next - base) % 6 == 4 {
                    let al = (next - base) / 6;
                    let mut cost = size(next - 4, &buffers) + size(next - 3, &buffers) + size(next - 2, &buffers) + size(next - 1, &buffers);
                    for i in 0..al {
                        cost += size(base + 4 + 6 * i, &buffers);
                        cost += size(base + 5 + 6 * i, &buffers);
                    }
                    if al == 0 || cost < best_cost {
                        best_cost = cost;
                        best_al_chroma = al;
                    } else {
                        jump = Some(chroma_split_start);
                    }
                }
            } else if next > chroma_split_start && next <= num_scans {
                if next == chroma_split_start + 2 {
                    best_split_chroma = 0;
                    best_cost = size(next - 2, &buffers) + size(next - 1, &buffers);
                } else if (next - chroma_split_start) % 4 == 2 {
                    let idx = (next - chroma_split_start) >> 2;
                    let cost = size(next - 4, &buffers) + size(next - 3, &buffers) + size(next - 2, &buffers) + size(next - 1, &buffers);
                    if cost < best_cost {
                        best_cost = cost;
                        best_split_chroma = idx;
                    }
                    if (idx == 2 && best_split_chroma == 0) || (idx == 3 && best_split_chroma != 2) || (idx == 4 && best_split_chroma != 4) {
                        jump = Some(num_scans);
                    }
                }
            }
        }
        sn = jump.unwrap_or(next);
        // skip chroma DC candidates (not needed for the combined DC scan)
        if nc == 3 && sn >= num_scans_luma && sn < num_scans_luma + chroma_dc {
            sn = num_scans_luma + chroma_dc;
        }
    }
    // assemble
    let mut out = Vec::new();
    let mut copy = |i: usize, out: &mut Vec<u8>| {
        if let Some(b) = &buffers[i] {
            out.extend_from_slice(b);
        }
    };
    copy(0, &mut out);
    let min_al = if nc == 3 { best_al_luma.min(best_al_chroma) } else { best_al_luma };
    if best_split_luma == 0 {
        copy(luma_split_start, &mut out);
    } else {
        copy(luma_split_start + 2 * (best_split_luma - 1) + 1, &mut out);
        copy(luma_split_start + 2 * (best_split_luma - 1) + 2, &mut out);
    }
    let mut al = best_al_luma as isize - 1;
    while al >= min_al as isize {
        copy(3 + 3 * al as usize, &mut out);
        al -= 1;
    }
    let base = num_scans_luma + chroma_dc;
    if nc == 3 {
        if best_split_chroma == 0 {
            copy(chroma_split_start, &mut out);
            copy(chroma_split_start + 1, &mut out);
        } else {
            let b = chroma_split_start + 4 * (best_split_chroma - 1);
            copy(b + 2, &mut out);
            copy(b + 3, &mut out);
            copy(b + 4, &mut out);
            copy(b + 5, &mut out);
        }
        let mut al = best_al_chroma as isize - 1;
        while al >= min_al as isize {
            copy(base + 6 * al as usize + 4, &mut out);
            copy(base + 6 * al as usize + 5, &mut out);
            al -= 1;
        }
    }
    let mut al = min_al as isize - 1;
    while al >= 0 {
        copy(3 + 3 * al as usize, &mut out);
        if nc == 3 {
            copy(base + 6 * al as usize + 4, &mut out);
            copy(base + 6 * al as usize + 5, &mut out);
        }
        al -= 1;
    }
    out
}

/// Simple progressive script for component counts other than 1 or 3.
fn progressive_simple(comps: &[CompCoefs], width: usize, height: usize) -> Vec<u8> {
    let nc = comps.len();
    let all: Vec<usize> = (0..nc).collect();
    let mut out = Vec::new();
    out.extend_from_slice(&encode_progressive_scan(comps, &Scan::new(&all, 0, 0, 0, 1), width, height));
    for c in 0..nc {
        out.extend_from_slice(&encode_progressive_scan(comps, &Scan::new(&[c], 1, 5, 0, 2), width, height));
    }
    for c in 0..nc {
        out.extend_from_slice(&encode_progressive_scan(comps, &Scan::new(&[c], 6, 63, 0, 2), width, height));
    }
    for c in 0..nc {
        out.extend_from_slice(&encode_progressive_scan(comps, &Scan::new(&[c], 1, 63, 2, 1), width, height));
    }
    out.extend_from_slice(&encode_progressive_scan(comps, &Scan::new(&all, 0, 0, 1, 0), width, height));
    for c in 0..nc {
        out.extend_from_slice(&encode_progressive_scan(comps, &Scan::new(&[c], 1, 63, 1, 0), width, height));
    }
    out
}

fn sequential_scan(comps: &[CompCoefs], width: usize, height: usize) -> Vec<u8> {
    let nc = comps.len();
    let all: Vec<usize> = (0..nc).collect();
    let scan = Scan::new(&all, 0, 63, 0, 0);
    let sel: Vec<usize> = (0..nc).map(|c| if c == 0 { 0 } else { 1 }).collect();
    let mut g = Coder::gatherer();
    code_sequential(comps, &scan, width, height, &sel, &sel, &mut g);
    let mut tables: [Option<HuffTable>; 4] = [None, None, None, None];
    let mut order = Vec::new();
    for ci in 0..nc {
        let t = sel[ci];
        if tables[t].is_none() {
            tables[t] = Some(HuffTable::optimal(&g.counts[t]));
            order.push(t);
        }
        if tables[t + 2].is_none() {
            tables[t + 2] = Some(HuffTable::optimal(&g.counts[t + 2]));
            order.push(t + 2);
        }
    }
    let list: Vec<(u8, &HuffTable)> = order
        .iter()
        .map(|&i| {
            let cls_idx = if i >= 2 { 0x10 | (i as u8 - 2) } else { i as u8 };
            (cls_idx, tables[i].as_ref().unwrap())
        })
        .collect();
    let mut out = dht_segment(&list);
    let sel8: Vec<u8> = sel.iter().map(|&s| s as u8).collect();
    out.extend_from_slice(&sos_segment(comps, &scan, false, &sel8, &sel8));
    let refs: [Option<&HuffTable>; 4] = [tables[0].as_ref(), tables[1].as_ref(), tables[2].as_ref(), tables[3].as_ref()];
    let mut e = Coder::emitter(refs);
    code_sequential(comps, &scan, width, height, &sel, &sel, &mut e);
    e.w.flush();
    out.extend_from_slice(&e.w.out);
    out
}

pub struct WriteOptions<'a> {
    pub progressive: bool,
    pub jfif: Option<super::jpeg::JfifInfo>,
    pub adobe: Option<u8>,
    /// markers written after the JFIF header (APPn / COM): (marker, payload)
    pub markers: &'a [(u8, Vec<u8>)],
}

/// Write a complete JPEG file from coefficients.
pub fn write_jpeg(comps: &[CompCoefs], qtables: &[[u16; 64]], width: usize, height: usize, wo: &WriteOptions) -> Vec<u8> {
    let mut out = vec![0xFF, 0xD8];
    if let Some(j) = wo.jfif {
        out.extend_from_slice(&[0xFF, 0xE0, 0, 16, b'J', b'F', b'I', b'F', 0, j.major, j.minor, j.unit]);
        put16(&mut out, j.xd as usize);
        put16(&mut out, j.yd as usize);
        out.push(0);
        out.push(0);
    }
    if let Some(t) = wo.adobe {
        out.extend_from_slice(&[0xFF, 0xEE, 0, 14, b'A', b'd', b'o', b'b', b'e', 0, 100, 0, 0, 0, 0, t]);
    }
    for (m, payload) in wo.markers {
        let mut p = payload.as_slice();
        if p.len() > 65533 {
            p = &p[..65533];
        }
        out.push(0xFF);
        out.push(*m);
        put16(&mut out, p.len() + 2);
        out.extend_from_slice(p);
    }
    // quantization tables used by components, in component order
    let mut used: Vec<usize> = Vec::new();
    for c in comps {
        if !used.contains(&c.info.tq) {
            used.push(c.info.tq);
        }
    }
    let mut prec_any = false;
    let mut body = Vec::new();
    for &t in used.iter() {
        let q = &qtables[t];
        let prec = q.iter().any(|&v| v > 255);
        prec_any |= prec;
        body.push(((prec as u8) << 4) | t as u8);
        for k in 0..64 {
            let v = q[ZIGZAG[k]];
            if prec {
                body.push((v >> 8) as u8);
            }
            body.push(v as u8);
        }
    }
    out.extend_from_slice(&[0xFF, 0xDB]);
    put16(&mut out, body.len() + 2);
    out.extend_from_slice(&body);
    // frame header
    let sof = if wo.progressive {
        0xC2
    } else if prec_any {
        0xC1
    } else {
        0xC0
    };
    out.extend_from_slice(&[0xFF, sof]);
    put16(&mut out, 8 + 3 * comps.len());
    out.push(8);
    put16(&mut out, height);
    put16(&mut out, width);
    out.push(comps.len() as u8);
    for c in comps {
        out.push(c.info.id);
        out.push(((c.info.h << 4) | c.info.v) as u8);
        out.push(c.info.tq as u8);
    }
    let data = if !wo.progressive {
        sequential_scan(comps, width, height)
    } else if comps.len() == 1 || comps.len() == 3 {
        progressive_search(comps, width, height)
    } else {
        progressive_simple(comps, width, height)
    };
    out.extend_from_slice(&data);
    out.extend_from_slice(&[0xFF, 0xD9]);
    out
}
