// Compression pipeline: format dispatch, quality search, conversion and resizing.
use crate::cli::{Chroma, Options, OutputFormat};
use crate::codecs::{self, Format, Image};

#[derive(Debug)]
pub struct CsError {
    pub message: String,
    pub code: u32,
}

impl CsError {
    pub fn new(message: &str, code: u32) -> CsError {
        CsError { message: message.to_string(), code }
    }
}

#[derive(Clone, Debug)]
pub struct Params {
    pub quality: u32,
    pub lossless: bool,
    pub chroma: Chroma,
    pub progressive: bool,
    pub png_level: u8,
    pub zopfli: bool,
    pub keep_metadata: bool,
    pub strip_icc: bool,
    pub width: u32,
    pub height: u32,
    pub single: bool,
}

static PANIC_NOTE: std::sync::Once = std::sync::Once::new();

fn gettid() -> i64 {
    extern "C" {
        fn syscall(num: i64, ...) -> i64;
    }
    unsafe { syscall(186) }
}

/// Mimic the diagnostic printed by the original when the JPEG library aborts.
fn report_jpeg_abort(code: u32, single: bool) {
    let name = if single { "main".to_string() } else { "<unnamed>".to_string() };
    let mut msg = format!(
        "\nthread '{}' ({}) panicked at /usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/libcaesium-0.20.0/src/jpeg.rs:315:5:\nInternal JPEG error: {}\n",
        name,
        gettid(),
        code
    );
    PANIC_NOTE.call_once(|| {
        msg.push_str("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n");
    });
    eprint!("{}", msg);
}

fn jpeg_err(code: u32, p: &Params) -> CsError {
    report_jpeg_abort(code, p.single);
    CsError { message: format!("Internal JPEG error: {}", code), code: 20104 }
}

fn chroma_samp(ch: Chroma) -> Option<(usize, usize)> {
    match ch {
        Chroma::S444 => Some((1, 1)),
        Chroma::S422 => Some((2, 1)),
        Chroma::S420 => Some((2, 2)),
        Chroma::S411 => Some((4, 1)),
        Chroma::Auto => None,
    }
}

/// ICC profile reassembled from APP2 chunks.
fn read_icc(markers: &[(u8, Vec<u8>)]) -> Option<Vec<u8>> {
    let mut chunks: Vec<(u8, u8, &[u8])> = Vec::new();
    for (m, d) in markers {
        if *m == 0xE2 && d.len() >= 14 && &d[0..12] == b"ICC_PROFILE\0" {
            chunks.push((d[12], d[13], &d[14..]));
        }
    }
    if chunks.is_empty() {
        return None;
    }
    let total = chunks[0].1;
    if total == 0 || chunks.iter().any(|c| c.1 != total) {
        return None;
    }
    let mut out = Vec::new();
    for seq in 1..=total {
        let c: Vec<_> = chunks.iter().filter(|c| c.0 == seq).collect();
        if c.len() != 1 {
            return None;
        }
        out.extend_from_slice(c[0].2);
    }
    Some(out)
}

fn icc_markers(icc: &[u8]) -> Vec<(u8, Vec<u8>)> {
    const MAX: usize = 65533 - 14;
    let n = (icc.len() + MAX - 1) / MAX;
    let mut v = Vec::new();
    for i in 0..n {
        let part = &icc[i * MAX..((i + 1) * MAX).min(icc.len())];
        let mut d = b"ICC_PROFILE\0".to_vec();
        d.push((i + 1) as u8);
        d.push(n as u8);
        d.extend_from_slice(part);
        v.push((0xE2u8, d));
    }
    v
}

fn output_markers(src_markers: &[(u8, Vec<u8>)], p: &Params) -> Vec<(u8, Vec<u8>)> {
    if p.keep_metadata {
        return src_markers.to_vec();
    }
    if !p.strip_icc {
        if let Some(icc) = read_icc(src_markers) {
            return icc_markers(&icc);
        }
    }
    Vec::new()
}

fn default_jfif() -> codecs::jpeg::JfifInfo {
    codecs::jpeg::JfifInfo { major: 1, minor: 1, unit: 0, xd: 1, yd: 1 }
}

fn jpeg_lossy(data: &[u8], p: &Params) -> Result<Vec<u8>, CsError> {
    use codecs::jpeg::ColorSpace;
    use codecs::jpegenc as je;
    let j = codecs::jpeg::decode_coefficients(data).map_err(|e| jpeg_err(e.0, p))?;
    let cs = j.color_space();
    let mut planes = codecs::jpeg::full_planes(&j);
    let (ids, mut samp, tqs, hts, jfif, adobe): (Vec<u8>, Vec<(usize, usize)>, Vec<usize>, Vec<usize>, bool, Option<u8>) = match cs {
        ColorSpace::Gray => (vec![1], vec![(1, 1)], vec![0], vec![0], true, None),
        ColorSpace::Cmyk => (vec![67, 77, 89, 75], vec![(1, 1); 4], vec![0; 4], vec![0; 4], false, Some(0)),
        ColorSpace::Ycck => (vec![1, 2, 3, 4], vec![(2, 2), (1, 1), (1, 1), (2, 2)], vec![0, 1, 1, 0], vec![0, 1, 1, 0], false, Some(2)),
        ColorSpace::Rgb => {
            // converted to YCbCr by the encoder
            let n = j.width * j.height;
            let mut rgb = vec![0u8; n * 3];
            for i in 0..n {
                rgb[3 * i] = planes[0][i];
                rgb[3 * i + 1] = planes[1][i];
                rgb[3 * i + 2] = planes[2][i];
            }
            planes = je::rgb_to_ycc(&rgb, n).to_vec();
            (vec![1, 2, 3], vec![(2, 2), (1, 1), (1, 1)], vec![0, 1, 1], vec![0, 1, 1], true, None)
        }
        _ => (vec![1, 2, 3], vec![(2, 2), (1, 1), (1, 1)], vec![0, 1, 1], vec![0, 1, 1], true, None),
    };
    if let Some(s) = chroma_samp(p.chroma) {
        samp[0] = s;
    }
    let opts = je::LossyOptions {
        quality: p.quality as i32,
        progressive: p.progressive,
        samp,
        tqs,
        hts,
        trellis: true,
        deringing: true,
    };
    let (comps, qt) = je::compute_coefficients(&planes, j.width, j.height, &ids, &opts);
    let markers = output_markers(&j.markers, p);
    let wo = je::WriteOptions {
        progressive: p.progressive,
        jfif: if jfif { Some(default_jfif()) } else { None },
        adobe,
        markers: &markers,
    };
    Ok(je::write_jpeg(&comps, &qt, j.width, j.height, &wo))
}

fn jpeg_lossless(data: &[u8], p: &Params) -> Result<Vec<u8>, CsError> {
    use codecs::jpeg::ColorSpace;
    use codecs::jpegenc as je;
    let j = codecs::jpeg::decode_coefficients(data).map_err(|e| jpeg_err(e.0, p))?;
    let cs = j.color_space();
    let mut comps = Vec::new();
    for c in &j.components {
        let info = je::CompInfo {
            id: c.id,
            h: c.h,
            v: c.v,
            tq: c.tq,
            ht: match cs {
                ColorSpace::YCbCr | ColorSpace::Rgb => {
                    if comps.is_empty() {
                        0
                    } else {
                        1
                    }
                }
                ColorSpace::Ycck => {
                    if comps.is_empty() || comps.len() == 3 {
                        0
                    } else {
                        1
                    }
                }
                _ => 0,
            },
            width_in_blocks: c.width_in_blocks,
            height_in_blocks: c.height_in_blocks,
            bw: c.bw,
            bh: c.bh,
        };
        let mut cc = je::CompCoefs { info, blocks: c.coefs.clone() };
        je::fill_dummy_blocks(&mut cc);
        comps.push(cc);
    }
    let mut qt: Vec<[u16; 64]> = Vec::new();
    for i in 0..4 {
        qt.push(j.qtables[i].unwrap_or([1u16; 64]));
    }
    let jfif = match cs {
        ColorSpace::Gray | ColorSpace::YCbCr => {
            let mut f = default_jfif();
            if let Some(s) = j.jfif {
                if s.major == 1 || s.major == 2 {
                    f.major = s.major;
                    f.minor = s.minor;
                }
                f.unit = s.unit;
                f.xd = s.xd;
                f.yd = s.yd;
            }
            Some(f)
        }
        _ => None,
    };
    let adobe = match cs {
        ColorSpace::Rgb | ColorSpace::Cmyk => Some(0),
        ColorSpace::Ycck => Some(2),
        _ => None,
    };
    let markers = output_markers(&j.markers, p);
    let wo = je::WriteOptions { progressive: p.progressive, jfif, adobe, markers: &markers };
    Ok(je::write_jpeg(&comps, &qt, j.width, j.height, &wo))
}

fn compress_jpeg(data: &[u8], p: &Params) -> Result<Vec<u8>, CsError> {
    if p.width > 0 || p.height > 0 {
        let resized = resize_to_jpeg(data, p)?;
        return if p.lossless { jpeg_lossless(&resized, p) } else { jpeg_lossy(&resized, p) };
    }
    if p.lossless {
        jpeg_lossless(data, p)
    } else {
        jpeg_lossy(data, p)
    }
}

/// Resize through an intermediate baseline JPEG (as the reference pipeline does).
fn resize_to_jpeg(data: &[u8], p: &Params) -> Result<Vec<u8>, CsError> {
    let j = codecs::jpeg::decode_coefficients(data).map_err(|e| jpeg_err(e.0, p))?;
    let img = codecs::jpeg::decode_image(data).map_err(|e| jpeg_err(e.0, p))?;
    let (w, h) = codecs::resize::compute_dimensions(img.width, img.height, p.width, p.height);
    let resized = codecs::resize::resize(&img, w, h);
    let mut markers = Vec::new();
    for (m, d) in &j.markers {
        if *m == 0xE1 || *m == 0xE2 {
            markers.push((*m, d.clone()));
        }
    }
    Ok(codecs::jpegenc::encode_simple(&resized, 75, &markers))
}

pub fn decode_any(data: &[u8]) -> Result<Image, CsError> {
    match codecs::detect_any(data) {
        Some(Format::Jpeg) => codecs::jpeg::decode_image(data).map_err(|_| CsError::new("Failed to decode JPEG", 10302)),
        Some(Format::Png) => codecs::png::decode(data).map_err(|e| CsError::new(&e, 10302)),
        Some(Format::Gif) => codecs::gif::decode_first(data).map_err(|e| CsError::new(&e, 10302)),
        Some(Format::Webp) => codecs::webp::decode(data).ok_or_else(|| CsError::new("null_decoder", 10302)),
        Some(Format::Tiff) => Err(CsError::new("Format not supported", 10302)),
        None => Err(CsError::new("Format not supported", 10300)),
    }
}

fn compress_webp(data: &[u8], p: &Params) -> Result<Vec<u8>, CsError> {
    let mut img = codecs::webp::decode(data).ok_or_else(|| CsError::new("null_decoder", 20304))?;
    if p.width > 0 || p.height > 0 {
        let (w, h) = codecs::resize::compute_dimensions(img.width, img.height, p.width, p.height);
        img = codecs::resize::resize(&img, w, h);
    }
    let q = if p.lossless { None } else { Some(p.quality as f32) };
    codecs::webp::encode(&img, q).ok_or_else(|| CsError::new("Unimplemented", 20305))
}

fn compress_png(data: &[u8], p: &Params) -> Result<Vec<u8>, CsError> {
    codecs::png::compress(data, p)
}

fn compress_gif(data: &[u8], p: &Params) -> Result<Vec<u8>, CsError> {
    codecs::gif::compress(data, p)
}

pub fn compress(data: &[u8], p: &Params) -> Result<Vec<u8>, CsError> {
    match codecs::detect_any(data) {
        Some(Format::Jpeg) => compress_jpeg(data, p),
        Some(Format::Png) => compress_png(data, p),
        Some(Format::Gif) => compress_gif(data, p),
        Some(Format::Webp) => compress_webp(data, p),
        Some(Format::Tiff) => codecs::tiff::compress(data, p),
        None => Err(CsError::new("Format not supported", 10300)),
    }
}

/// Binary search on quality until the output fits in max_size.
pub fn compress_to_size(data: &[u8], p: &Params, max_size: u64) -> Result<Vec<u8>, CsError> {
    let in_size = data.len() as u64;
    if in_size <= max_size {
        return Ok(data.to_vec());
    }
    let mut params = p.clone();
    params.lossless = false;
    let tolerance = max_size / 50;
    let mut quality: i64 = 80;
    let mut last_less: i64 = 0;
    let mut last_high: i64 = 101;
    let max_tries = 10;
    let mut tries = 0;
    let mut out: Vec<u8>;
    loop {
        params.quality = quality as u32;
        out = compress(data, &params)?;
        let size = out.len() as u64;
        if size <= max_size && max_size - size < tolerance {
            break;
        }
        if size <= max_size {
            last_less = quality;
        } else {
            last_high = quality;
        }
        let last_quality = quality;
        quality = ((last_high + last_less) / 2).clamp(1, 100);
        if last_quality == quality {
            if quality == 1 && last_high == 1 {
                break;
            }
            break;
        }
        tries += 1;
        if tries >= max_tries {
            break;
        }
    }
    Ok(out)
}

pub fn convert(data: &[u8], p: &Params, fmt: OutputFormat) -> Result<Vec<u8>, CsError> {
    let src = codecs::detect_any(data);
    let target = match fmt {
        OutputFormat::Jpeg => Format::Jpeg,
        OutputFormat::Png => Format::Png,
        OutputFormat::Gif => Format::Gif,
        OutputFormat::Webp => Format::Webp,
        OutputFormat::Tiff => Format::Tiff,
        OutputFormat::Original => return compress(data, p),
    };
    if src == Some(target) {
        return Err(CsError::new("Cannot convert to the same format", 10407));
    }
    let img = decode_any(data)?;
    let intermediate = match target {
        Format::Jpeg => codecs::jpegenc::encode_simple(&img.to_rgb(), 75, &[]),
        Format::Png => codecs::png::encode_simple(&img),
        Format::Gif => codecs::gif::encode_simple(&img),
        Format::Webp => codecs::webp::encode(&img, None).ok_or_else(|| CsError::new("Unimplemented", 10405))?,
        Format::Tiff => codecs::tiff::encode(&img),
    };
    compress(&intermediate, p)
}

fn compute_resize(data: &[u8], opts: &Options) -> (u32, u32) {
    let mut w = opts.width.unwrap_or(0);
    let mut h = opts.height.unwrap_or(0);
    let dims = codecs::image_dimensions(data);
    if opts.long_edge.is_some() || opts.short_edge.is_some() {
        if let Some((iw, ih)) = dims {
            if let Some(le) = opts.long_edge {
                if iw >= ih {
                    w = le;
                    h = 0;
                } else {
                    w = 0;
                    h = le;
                }
            } else if let Some(se) = opts.short_edge {
                if iw <= ih {
                    w = se;
                    h = 0;
                } else {
                    w = 0;
                    h = se;
                }
            }
        }
    }
    if opts.no_upscale {
        if let Some((iw, ih)) = dims {
            if (w > 0 && w > iw) || (h > 0 && h > ih) {
                return (0, 0);
            }
        }
    }
    (w, h)
}

pub fn process(data: &[u8], opts: &Options, single: bool) -> Result<Vec<u8>, CsError> {
    let (width, height) = compute_resize(data, opts);
    let p = Params {
        quality: opts.quality.unwrap_or(80),
        lossless: opts.lossless,
        chroma: opts.chroma,
        progressive: !opts.jpeg_baseline,
        png_level: opts.png_opt_level,
        zopfli: opts.zopfli,
        keep_metadata: opts.exif,
        strip_icc: opts.strip_icc,
        width,
        height,
        single,
    };
    if opts.format != OutputFormat::Original {
        let converted = convert(data, &p, opts.format)?;
        return Ok(converted);
    }
    if let Some(max) = opts.max_size {
        return compress_to_size(data, &p, max);
    }
    compress(data, &p)
}
