// zlib / deflate helpers built on miniz_oxide.
use miniz_oxide::deflate::core::{compress, create_comp_flags_from_zip_params, CompressorOxide, TDEFLFlush, TDEFLStatus};

pub fn inflate_zlib(data: &[u8]) -> Result<Vec<u8>, ()> {
    miniz_oxide::inflate::decompress_to_vec_zlib(data).map_err(|_| ())
}

/// Inflate as much as possible; returns (data, ok).
pub fn inflate_zlib_partial(data: &[u8]) -> (Vec<u8>, bool) {
    match miniz_oxide::inflate::decompress_to_vec_zlib(data) {
        Ok(v) => (v, true),
        Err(e) => (e.output, false),
    }
}

/// zlib compress with a given level (0-10) and strategy (0 default, 1 filtered, 2 huffman only, 3 rle).
pub fn zlib(data: &[u8], level: u8, strategy: i32) -> Vec<u8> {
    let flags = create_comp_flags_from_zip_params(level as i32, 15, strategy);
    let mut c = CompressorOxide::new(flags);
    let mut out = Vec::with_capacity(data.len() / 2 + 64);
    let mut buf = vec![0u8; 1 << 16];
    let mut input = data;
    loop {
        let (status, used_in, used_out) = compress(&mut c, input, &mut buf, TDEFLFlush::Finish);
        out.extend_from_slice(&buf[..used_out]);
        input = &input[used_in..];
        match status {
            TDEFLStatus::Done => break,
            TDEFLStatus::Okay => continue,
            _ => break,
        }
    }
    out
}

pub fn zlib_best(data: &[u8]) -> Vec<u8> {
    let a = zlib(data, 10, 0);
    let b = zlib(data, 9, 1);
    if b.len() < a.len() {
        b
    } else {
        a
    }
}
