// PNG decoding, lossless re-optimisation and palette-based lossy compression.
use super::deflate;
use super::Image;
use crate::caesium::{CsError, Params};

#[derive(Clone, Debug)]
pub struct Png {
    pub width: u32,
    pub height: u32,
    pub bit_depth: u8,
    pub color_type: u8,
    pub palette: Vec<[u8; 3]>,
    pub trns: Option<Vec<u8>>,
    /// unfiltered, non interlaced packed scanlines
    pub data: Vec<u8>,
    /// ancillary chunks located before PLTE
    pub aux_pre: Vec<([u8; 4], Vec<u8>)>,
    /// ancillary chunks between PLTE and IDAT (or before IDAT when no PLTE)
    pub aux_mid: Vec<([u8; 4], Vec<u8>)>,
    /// ancillary chunks after IDAT
    pub aux_post: Vec<([u8; 4], Vec<u8>)>,
}

fn crc32(data: &[u8]) -> u32 {
    static TABLE: std::sync::OnceLock<[u32; 256]> = std::sync::OnceLock::new();
    let t = TABLE.get_or_init(|| {
        let mut t = [0u32; 256];
        for n in 0..256u32 {
            let mut c = n;
            for _ in 0..8 {
                c = if c & 1 != 0 { 0xEDB88320 ^ (c >> 1) } else { c >> 1 };
            }
            t[n as usize] = c;
        }
        t
    });
    let mut c = 0xFFFFFFFFu32;
    for &b in data {
        c = t[((c ^ b as u32) & 0xFF) as usize] ^ (c >> 8);
    }
    c ^ 0xFFFFFFFF
}

pub fn crc_of(typ: &[u8], data: &[u8]) -> u32 {
    let mut v = Vec::with_capacity(4 + data.len());
    v.extend_from_slice(typ);
    v.extend_from_slice(data);
    crc32(&v)
}

fn channels(ct: u8) -> Option<usize> {
    match ct {
        0 => Some(1),
        2 => Some(3),
        3 => Some(1),
        4 => Some(2),
        6 => Some(4),
        _ => None,
    }
}

fn valid_depth(ct: u8, bd: u8) -> bool {
    match ct {
        0 => matches!(bd, 1 | 2 | 4 | 8 | 16),
        3 => matches!(bd, 1 | 2 | 4 | 8),
        2 | 4 | 6 => matches!(bd, 8 | 16),
        _ => false,
    }
}

pub fn bits_per_pixel(ct: u8, bd: u8) -> usize {
    channels(ct).unwrap_or(1) * bd as usize
}

pub fn row_bytes(w: u32, ct: u8, bd: u8) -> usize {
    (w as usize * bits_per_pixel(ct, bd) + 7) / 8
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum ErrStyle {
    Lodepng,
    Oxipng,
}

fn err(style: ErrStyle, lode: &str, oxi: &str) -> String {
    match style {
        ErrStyle::Lodepng => lode.to_string(),
        ErrStyle::Oxipng => oxi.to_string(),
    }
}

fn be32(d: &[u8], p: usize) -> u32 {
    u32::from_be_bytes([d[p], d[p + 1], d[p + 2], d[p + 3]])
}

pub fn parse(data: &[u8], style: ErrStyle) -> Result<Png, String> {
    if data.len() < 8 || data[0..8] != [0x89, b'P', b'N', b'G', 0x0D, 0x0A, 0x1A, 0x0A] {
        return Err(err(style, "incorrect PNG signature, it's no PNG or corrupted", "Invalid header detected; Not a PNG file"));
    }
    let mut p = 8;
    let mut header: Option<(u32, u32, u8, u8, u8)> = None;
    let mut palette = Vec::new();
    let mut trns = None;
    let mut idat = Vec::new();
    let mut aux_pre = Vec::new();
    let mut aux_mid = Vec::new();
    let mut aux_post = Vec::new();
    let mut seen_plte = false;
    let mut seen_idat = false;
    let mut seen_iend = false;
    let mut truncated = false;
    while p < data.len() {
        if p + 12 > data.len() {
            truncated = true;
            break;
        }
        let len = be32(data, p) as usize;
        let mut typ = [0u8; 4];
        typ.copy_from_slice(&data[p + 4..p + 8]);
        if p + 12 + len > data.len() {
            truncated = true;
            if &typ == b"IDAT" && style == ErrStyle::Lodepng {
                idat.extend_from_slice(&data[p + 8..data.len().min(p + 8 + len)]);
            }
            break;
        }
        let body = &data[p + 8..p + 8 + len];
        let crc = be32(data, p + 8 + len);
        let crc_ok = crc_of(&typ, body) == crc;
        if header.is_none() && &typ != b"IHDR" {
            return Err(err(style, "first chunk is not the header chunk", "Invalid data found; unable to read PNG file"));
        }
        if !crc_ok && (style == ErrStyle::Oxipng || &typ == b"IHDR") {
            return Err(err(
                style,
                "invalid CRC encountered (checking CRC can be disabled)",
                &format!("CRC Mismatch in {} chunk; May be recoverable by using --fix", String::from_utf8_lossy(&typ)),
            ));
        }
        match &typ {
            b"IHDR" => {
                if len != 13 {
                    return Err(err(style, "header chunk must have a size of 13 bytes", "Invalid data found; unable to read PNG file"));
                }
                let w = be32(body, 0);
                let h = be32(body, 4);
                let bd = body[8];
                let ct = body[9];
                let il = body[12];
                if channels(ct).is_none() {
                    return Err(err(style, "illegal PNG color type or bpp", "Unexpected color type in header"));
                }
                if !valid_depth(ct, bd) {
                    return Err(err(style, "illegal PNG color type or bpp", "Unexpected bit depth in header"));
                }
                if w == 0 || h == 0 {
                    return Err(err(style, "zero width or height is invalid", "Invalid data found; unable to read PNG file"));
                }
                if body[10] != 0 {
                    return Err(err(style, "illegal PNG compression method", "Invalid data found; unable to read PNG file"));
                }
                if body[11] != 0 {
                    return Err(err(style, "illegal PNG filter method", "Invalid data found; unable to read PNG file"));
                }
                if il > 1 {
                    return Err(err(style, "illegal PNG interlace method", "Invalid data found; unable to read PNG file"));
                }
                header = Some((w, h, bd, ct, il));
            }
            b"PLTE" => {
                if len % 3 != 0 || len / 3 > 256 || len == 0 {
                    return Err(err(style, "the palette is too small or too big", "Invalid data found; unable to read PNG file"));
                }
                palette = body.chunks_exact(3).map(|c| [c[0], c[1], c[2]]).collect();
                seen_plte = true;
            }
            b"tRNS" => {
                trns = Some(body.to_vec());
            }
            b"IDAT" => {
                idat.extend_from_slice(body);
                seen_idat = true;
            }
            b"IEND" => {
                seen_iend = true;
                break;
            }
            _ => {
                if typ[0] & 0x20 == 0 && style == ErrStyle::Lodepng {
                    return Err("unknown chunk type with 'critical' flag encountered by the decoder".to_string());
                }
                if typ[0] & 0x20 != 0 || style == ErrStyle::Oxipng {
                    if seen_idat {
                        aux_post.push((typ, body.to_vec()));
                    } else if seen_plte {
                        aux_mid.push((typ, body.to_vec()));
                    } else {
                        aux_pre.push((typ, body.to_vec()));
                    }
                }
            }
        }
        p += 12 + len;
    }
    let (w, h, bd, ct, il) = match header {
        Some(hh) => hh,
        None => return Err(err(style, "PNG file is smaller than a PNG header", "Invalid header detected; Not a PNG file")),
    };
    if style == ErrStyle::Oxipng && (truncated || !seen_iend) {
        return Err("Missing data in the file; the file is truncated".to_string());
    }
    if style == ErrStyle::Lodepng && truncated {
        return Err("the length of the END symbol 256 in the Huffman tree is 0".to_string());
    }
    if style == ErrStyle::Lodepng && !seen_iend {
        return Err("jumped past memory while inflating".to_string());
    }
    if ct == 3 && palette.is_empty() {
        return Err(err(style, "the palette is too small or too big", "Invalid data found; unable to read PNG file"));
    }
    let (raw, ok) = deflate::inflate_zlib_partial(&idat);
    if !ok {
        return Err(err(style, "end of in buffer memory reached while inflating", "Invalid data found; unable to read PNG file"));
    }
    let data = unfilter_image(&raw, w, h, ct, bd, il == 1).map_err(|lode| {
        if lode {
            err(style, "invalid decompressed idat size", "Missing data in the file; the file is truncated")
        } else {
            err(style, "illegal PNG filter type encountered", "Invalid data found; unable to read PNG file")
        }
    })?;
    Ok(Png { width: w, height: h, bit_depth: bd, color_type: ct, palette, trns, data, aux_pre, aux_mid, aux_post })
}

fn paeth(a: u8, b: u8, c: u8) -> u8 {
    let p = a as i16 + b as i16 - c as i16;
    let pa = (p - a as i16).abs();
    let pb = (p - b as i16).abs();
    let pc = (p - c as i16).abs();
    if pa <= pb && pa <= pc {
        a
    } else if pb <= pc {
        b
    } else {
        c
    }
}

fn unfilter_rows(raw: &[u8], pos: &mut usize, rb: usize, rows: usize, bpp: usize, out: &mut Vec<u8>) -> Result<(), bool> {
    let mut prev = vec![0u8; rb];
    for _ in 0..rows {
        if *pos + 1 + rb > raw.len() {
            return Err(true);
        }
        let f = raw[*pos];
        let mut line = raw[*pos + 1..*pos + 1 + rb].to_vec();
        *pos += 1 + rb;
        match f {
            0 => {}
            1 => {
                for i in bpp..rb {
                    line[i] = line[i].wrapping_add(line[i - bpp]);
                }
            }
            2 => {
                for i in 0..rb {
                    line[i] = line[i].wrapping_add(prev[i]);
                }
            }
            3 => {
                for i in 0..rb {
                    let a = if i >= bpp { line[i - bpp] as u16 } else { 0 };
                    line[i] = line[i].wrapping_add(((a + prev[i] as u16) >> 1) as u8);
                }
            }
            4 => {
                for i in 0..rb {
                    let a = if i >= bpp { line[i - bpp] } else { 0 };
                    let c = if i >= bpp { prev[i - bpp] } else { 0 };
                    line[i] = line[i].wrapping_add(paeth(a, prev[i], c));
                }
            }
            _ => return Err(false),
        }
        out.extend_from_slice(&line);
        prev = line;
    }
    Ok(())
}

const ADAM7: [(usize, usize, usize, usize); 7] = [(0, 0, 8, 8), (4, 0, 8, 8), (0, 4, 4, 8), (2, 0, 4, 4), (0, 2, 2, 4), (1, 0, 2, 2), (0, 1, 1, 2)];

fn get_bits(row: &[u8], x: usize, bpp_bits: usize) -> u32 {
    if bpp_bits >= 8 {
        let n = bpp_bits / 8;
        let mut v = 0u32;
        for k in 0..n.min(4) {
            v = (v << 8) | row[x * n + k] as u32;
        }
        v
    } else {
        let bit = x * bpp_bits;
        let byte = row[bit / 8];
        let shift = 8 - bpp_bits - (bit % 8);
        ((byte >> shift) as u32) & ((1 << bpp_bits) - 1)
    }
}

fn unfilter_image(raw: &[u8], w: u32, h: u32, ct: u8, bd: u8, interlaced: bool) -> Result<Vec<u8>, bool> {
    let bpp_bits = bits_per_pixel(ct, bd);
    let bpp = ((bpp_bits + 7) / 8).max(1);
    let rb = row_bytes(w, ct, bd);
    let mut pos = 0;
    if !interlaced {
        let mut out = Vec::with_capacity(rb * h as usize);
        unfilter_rows(raw, &mut pos, rb, h as usize, bpp, &mut out)?;
        return Ok(out);
    }
    let mut out = vec![0u8; rb * h as usize];
    for &(x0, y0, dx, dy) in ADAM7.iter() {
        let pw = (w as usize + dx - 1 - x0) / dx;
        let ph = (h as usize + dy - 1 - y0) / dy;
        if pw == 0 || ph == 0 || (w as usize) <= x0 || (h as usize) <= y0 {
            continue;
        }
        let prb = (pw * bpp_bits + 7) / 8;
        let mut pass = Vec::new();
        unfilter_rows(raw, &mut pos, prb, ph, bpp, &mut pass)?;
        for py in 0..ph {
            let row = &pass[py * prb..(py + 1) * prb];
            let y = y0 + py * dy;
            for px in 0..pw {
                let x = x0 + px * dx;
                if bpp_bits >= 8 {
                    let n = bpp_bits / 8;
                    out[y * rb + x * n..y * rb + x * n + n].copy_from_slice(&row[px * n..px * n + n]);
                } else {
                    let v = get_bits(row, px, bpp_bits) as u8;
                    let bit = x * bpp_bits;
                    let shift = 8 - bpp_bits - (bit % 8);
                    out[y * rb + bit / 8] |= v << shift;
                }
            }
        }
    }
    Ok(out)
}

/// Convert to 8-bit RGBA.
pub fn to_rgba(png: &Png) -> Image {
    let w = png.width as usize;
    let h = png.height as usize;
    let rb = row_bytes(png.width, png.color_type, png.bit_depth);
    let bpp_bits = bits_per_pixel(png.color_type, png.bit_depth);
    let bd = png.bit_depth;
    let mut out = Vec::with_capacity(w * h * 4);
    let scale = |v: u32| -> u8 {
        match bd {
            1 => (v * 255) as u8,
            2 => (v * 85) as u8,
            4 => (v * 17) as u8,
            8 => v as u8,
            _ => (v >> 8) as u8,
        }
    };
    let trns = png.trns.as_deref();
    for y in 0..h {
        let row = &png.data[y * rb..(y + 1) * rb];
        for x in 0..w {
            match png.color_type {
                0 => {
                    let raw = get_bits(row, x, bpp_bits);
                    let g = scale(raw);
                    let a = match trns {
                        Some(t) if t.len() >= 2 && ((t[0] as u32) << 8 | t[1] as u32) == raw => 0,
                        _ => 255,
                    };
                    out.extend_from_slice(&[g, g, g, a]);
                }
                2 => {
                    let (r, g, b, a);
                    if bd == 8 {
                        r = row[x * 3];
                        g = row[x * 3 + 1];
                        b = row[x * 3 + 2];
                        a = match trns {
                            Some(t) if t.len() >= 6 && t[1] == r && t[3] == g && t[5] == b && t[0] == 0 && t[2] == 0 && t[4] == 0 => 0,
                            _ => 255,
                        };
                    } else {
                        r = row[x * 6];
                        g = row[x * 6 + 2];
                        b = row[x * 6 + 4];
                        a = match trns {
                            Some(t) if t.len() >= 6 && t[..] == row[x * 6..x * 6 + 6] => 0,
                            _ => 255,
                        };
                    }
                    out.extend_from_slice(&[r, g, b, a]);
                }
                3 => {
                    let i = get_bits(row, x, bpp_bits) as usize;
                    let c = png.palette.get(i).copied().unwrap_or([0, 0, 0]);
                    let a = trns.and_then(|t| t.get(i).copied()).unwrap_or(255);
                    out.extend_from_slice(&[c[0], c[1], c[2], a]);
                }
                4 => {
                    if bd == 8 {
                        let g = row[x * 2];
                        out.extend_from_slice(&[g, g, g, row[x * 2 + 1]]);
                    } else {
                        let g = row[x * 4];
                        out.extend_from_slice(&[g, g, g, row[x * 4 + 2]]);
                    }
                }
                _ => {
                    if bd == 8 {
                        out.extend_from_slice(&row[x * 4..x * 4 + 4]);
                    } else {
                        out.extend_from_slice(&[row[x * 8], row[x * 8 + 2], row[x * 8 + 4], row[x * 8 + 6]]);
                    }
                }
            }
        }
    }
    Image::new(png.width, png.height, 4, out)
}

pub fn decode(data: &[u8]) -> Result<Image, String> {
    let p = parse(data, ErrStyle::Lodepng)?;
    let img = to_rgba(&p);
    Ok(simplify(img))
}

/// Drop redundant alpha / color channels.
pub fn simplify(img: Image) -> Image {
    let opaque = img.is_opaque();
    let gray = img.is_gray();
    match (opaque, gray) {
        (true, true) => img.to_luma(),
        (true, false) => img.to_rgb(),
        (false, true) => {
            let n = (img.width * img.height) as usize;
            let rgba = img.to_rgba();
            let mut out = Vec::with_capacity(n * 2);
            for i in 0..n {
                out.push(rgba.data[4 * i]);
                out.push(rgba.data[4 * i + 3]);
            }
            Image::new(img.width, img.height, 2, out)
        }
        _ => img.to_rgba(),
    }
}

// ---------------------------------------------------------------------------
// Encoding

fn filter_row(f: u8, line: &[u8], prev: &[u8], bpp: usize, out: &mut Vec<u8>) {
    out.push(f);
    let n = line.len();
    match f {
        0 => out.extend_from_slice(line),
        1 => {
            for i in 0..n {
                let a = if i >= bpp { line[i - bpp] } else { 0 };
                out.push(line[i].wrapping_sub(a));
            }
        }
        2 => {
            for i in 0..n {
                out.push(line[i].wrapping_sub(prev[i]));
            }
        }
        3 => {
            for i in 0..n {
                let a = if i >= bpp { line[i - bpp] as u16 } else { 0 };
                out.push(line[i].wrapping_sub(((a + prev[i] as u16) >> 1) as u8));
            }
        }
        _ => {
            for i in 0..n {
                let a = if i >= bpp { line[i - bpp] } else { 0 };
                let c = if i >= bpp { prev[i - bpp] } else { 0 };
                out.push(line[i].wrapping_sub(paeth(a, prev[i], c)));
            }
        }
    }
}

/// strategy: 0..=4 fixed filter, 5 = minimum sum of absolute values, 6 = entropy
fn filter_image(data: &[u8], h: usize, rb: usize, bpp: usize, strategy: u8) -> Vec<u8> {
    let mut out = Vec::with_capacity((rb + 1) * h);
    let zero = vec![0u8; rb];
    let mut tmp = Vec::with_capacity(rb + 1);
    for y in 0..h {
        let line = &data[y * rb..(y + 1) * rb];
        let prev = if y > 0 { &data[(y - 1) * rb..y * rb] } else { &zero[..] };
        if strategy <= 4 {
            filter_row(strategy, line, prev, bpp, &mut out);
            continue;
        }
        let mut best: Option<(u64, Vec<u8>)> = None;
        for f in 0..5u8 {
            tmp.clear();
            filter_row(f, line, prev, bpp, &mut tmp);
            let score: u64 = if strategy == 5 {
                tmp[1..].iter().map(|&b| (b as i8).unsigned_abs() as u64).sum()
            } else {
                let mut hist = [0u32; 256];
                for &b in &tmp[1..] {
                    hist[b as usize] += 1;
                }
                let n = tmp.len() as f64 - 1.0;
                let mut e = 0.0;
                for &c in hist.iter() {
                    if c > 0 {
                        let p = c as f64 / n;
                        e -= p * p.log2();
                    }
                }
                (e * 1_000_000.0) as u64
            };
            if best.as_ref().map(|b| score < b.0).unwrap_or(true) {
                best = Some((score, tmp.clone()));
            }
        }
        out.extend_from_slice(&best.unwrap().1);
    }
    out
}

fn write_chunk(out: &mut Vec<u8>, typ: &[u8], body: &[u8]) {
    out.extend_from_slice(&(body.len() as u32).to_be_bytes());
    out.extend_from_slice(typ);
    out.extend_from_slice(body);
    out.extend_from_slice(&crc_of(typ, body).to_be_bytes());
}

pub fn assemble(p: &Png, idat: &[u8]) -> Vec<u8> {
    let mut out = vec![0x89, b'P', b'N', b'G', 0x0D, 0x0A, 0x1A, 0x0A];
    let mut ihdr = Vec::new();
    ihdr.extend_from_slice(&p.width.to_be_bytes());
    ihdr.extend_from_slice(&p.height.to_be_bytes());
    ihdr.extend_from_slice(&[p.bit_depth, p.color_type, 0, 0, 0]);
    write_chunk(&mut out, b"IHDR", &ihdr);
    for (t, b) in &p.aux_pre {
        write_chunk(&mut out, t, b);
    }
    if p.color_type == 3 {
        let mut pl = Vec::new();
        for c in &p.palette {
            pl.extend_from_slice(c);
        }
        write_chunk(&mut out, b"PLTE", &pl);
    }
    if let Some(t) = &p.trns {
        write_chunk(&mut out, b"tRNS", t);
    }
    for (t, b) in &p.aux_mid {
        write_chunk(&mut out, t, b);
    }
    write_chunk(&mut out, b"IDAT", idat);
    for (t, b) in &p.aux_post {
        write_chunk(&mut out, t, b);
    }
    write_chunk(&mut out, b"IEND", &[]);
    out
}

// ---------------------------------------------------------------------------
// Lossless reductions

fn pack_samples(vals: &[u8], w: usize, h: usize, bd: u8) -> Vec<u8> {
    if bd == 8 {
        return vals.to_vec();
    }
    let rb = (w * bd as usize + 7) / 8;
    let mut out = vec![0u8; rb * h];
    for y in 0..h {
        for x in 0..w {
            let v = vals[y * w + x];
            let bit = x * bd as usize;
            let shift = 8 - bd as usize - (bit % 8);
            out[y * rb + bit / 8] |= v << shift;
        }
    }
    out
}

/// Build the smallest lossless representation candidates of the image.
fn reduce(p: &Png) -> Png {
    let w = p.width as usize;
    let h = p.height as usize;
    let n = w * h;
    // 16-bit images that cannot be reduced stay as they are
    if p.bit_depth == 16 {
        let reducible = p.data.chunks_exact(2).all(|c| c[0] == c[1]);
        let trns_ok = p.trns.as_ref().map(|t| t.chunks_exact(2).all(|c| c[0] == c[1])).unwrap_or(true);
        if !(reducible && trns_ok) {
            return p.clone();
        }
    }
    let rgba = to_rgba(p);
    let px = &rgba.data;
    let opaque = rgba.is_opaque();
    let gray = rgba.is_gray();
    let mut base = p.clone();
    base.trns = None;
    // collect unique colors
    let mut colors: Vec<u32> = Vec::new();
    let mut map = std::collections::HashMap::new();
    let mut too_many = false;
    for i in 0..n {
        let c = u32::from_be_bytes([px[4 * i], px[4 * i + 1], px[4 * i + 2], px[4 * i + 3]]);
        if !map.contains_key(&c) {
            if colors.len() >= 256 {
                too_many = true;
                break;
            }
            map.insert(c, colors.len());
            colors.push(c);
        }
    }
    // grayscale candidate
    if gray {
        let g: Vec<u8> = (0..n).map(|i| px[4 * i]).collect();
        // transparent key for gray
        let mut alpha_needed = !opaque;
        let mut key: Option<u8> = None;
        if !opaque {
            // single fully transparent gray value not used opaquely -> tRNS
            let mut tval: Option<u8> = None;
            let mut ok = true;
            for i in 0..n {
                let a = px[4 * i + 3];
                if a == 0 {
                    match tval {
                        None => tval = Some(g[i]),
                        Some(t) if t != g[i] => ok = false,
                        _ => {}
                    }
                } else if a != 255 {
                    ok = false;
                }
            }
            if ok {
                if let Some(t) = tval {
                    if (0..n).all(|i| px[4 * i + 3] == 0 || g[i] != t) {
                        key = Some(t);
                        alpha_needed = false;
                    }
                }
            }
        }
        if !alpha_needed {
            let mut bd = 8u8;
            for &d in [1u8, 2, 4].iter() {
                let mul = match d {
                    1 => 255u16,
                    2 => 85,
                    _ => 17,
                };
                if g.iter().all(|&v| v as u16 % mul == 0) && key.map(|k| k as u16 % mul == 0).unwrap_or(true) {
                    bd = d;
                    break;
                }
            }
            let mul = match bd {
                1 => 255u8,
                2 => 85,
                4 => 17,
                _ => 1,
            };
            let vals: Vec<u8> = g.iter().map(|&v| v / mul).collect();
            let mut cand = base.clone();
            cand.color_type = 0;
            cand.bit_depth = bd;
            cand.palette.clear();
            cand.data = pack_samples(&vals, w, h, bd);
            cand.trns = key.map(|k| vec![0, k / mul]);
            if bd < 8 || too_many || colors.len() > 16 {
                return cand;
            }
            // compare with palette below when few colors
            if !too_many && colors.len() <= 16 {
                return cand;
            }
        } else if too_many {
            let mut cand = base.clone();
            cand.color_type = 4;
            cand.bit_depth = 8;
            cand.palette.clear();
            let mut d = Vec::with_capacity(n * 2);
            for i in 0..n {
                d.push(px[4 * i]);
                d.push(px[4 * i + 3]);
            }
            cand.data = d;
            return cand;
        }
    }
    if !too_many {
        // palette
        let mut cols = colors.clone();
        // order: opaque entries after transparent ones so tRNS is short
        cols.sort_by_key(|&c| {
            let a = (c & 0xFF) as u8;
            (if a == 255 { 1u8 } else { 0u8 }, 0u32)
        });
        let mut idx = std::collections::HashMap::new();
        for (i, &c) in cols.iter().enumerate() {
            idx.insert(c, i as u8);
        }
        let k = cols.len();
        let bd = if k <= 2 {
            1
        } else if k <= 4 {
            2
        } else if k <= 16 {
            4
        } else {
            8
        };
        let vals: Vec<u8> = (0..n)
            .map(|i| {
                let c = u32::from_be_bytes([px[4 * i], px[4 * i + 1], px[4 * i + 2], px[4 * i + 3]]);
                idx[&c]
            })
            .collect();
        let mut cand = base.clone();
        cand.color_type = 3;
        cand.bit_depth = bd;
        cand.palette = cols.iter().map(|&c| [(c >> 24) as u8, (c >> 16) as u8, (c >> 8) as u8]).collect();
        let ntrans = cols.iter().filter(|&&c| (c & 0xFF) != 255).count();
        cand.trns = if ntrans > 0 { Some(cols[..ntrans].iter().map(|&c| (c & 0xFF) as u8).collect()) } else { None };
        cand.data = pack_samples(&vals, w, h, bd);
        // palette is preferred for small color counts; for larger counts compare raw size
        let truecolor_bpp = if opaque { 3 } else { 4 };
        if k <= 16 || n * truecolor_bpp > n + 3 * k + 64 {
            return cand;
        }
    }
    let mut cand = base.clone();
    cand.palette.clear();
    cand.bit_depth = 8;
    if opaque {
        cand.color_type = 2;
        let mut d = Vec::with_capacity(n * 3);
        for i in 0..n {
            d.extend_from_slice(&px[4 * i..4 * i + 3]);
        }
        cand.data = d;
    } else {
        cand.color_type = 6;
        cand.data = px.clone();
    }
    cand
}

fn compress_idat(p: &Png, level: u8, zopfli: bool) -> Vec<u8> {
    let h = p.height as usize;
    let rb = row_bytes(p.width, p.color_type, p.bit_depth);
    let bpp = ((bits_per_pixel(p.color_type, p.bit_depth) + 7) / 8).max(1);
    let strategies: Vec<u8> = if p.color_type == 3 || p.bit_depth < 8 {
        if level >= 2 {
            vec![0, 5]
        } else {
            vec![0]
        }
    } else {
        match level {
            0 => vec![5],
            1 => vec![5],
            2 => vec![0, 5],
            _ => vec![0, 1, 2, 4, 5, 6],
        }
    };
    let deflate_level = if level == 0 { 6 } else { 10 };
    let mut best: Option<Vec<u8>> = None;
    for &s in strategies.iter() {
        let f = filter_image(&p.data, h, rb, bpp, s);
        let z = if level >= 3 || zopfli { deflate::zlib_best(&f) } else { deflate::zlib(&f, deflate_level, 0) };
        if best.as_ref().map(|b| z.len() < b.len()).unwrap_or(true) {
            best = Some(z);
        }
    }
    best.unwrap()
}

/// Lossless optimisation of a parsed PNG. Returns the new file.
pub fn optimize(p: &Png, level: u8, zopfli: bool) -> Vec<u8> {
    let reduced = reduce(p);
    let idat = compress_idat(&reduced, level, zopfli);
    assemble(&reduced, &idat)
}

pub fn encode_simple(img: &Image) -> Vec<u8> {
    let ct = match img.channels {
        1 => 0,
        2 => 4,
        3 => 2,
        _ => 6,
    };
    let p = Png {
        width: img.width,
        height: img.height,
        bit_depth: 8,
        color_type: ct,
        palette: Vec::new(),
        trns: None,
        data: img.data.clone(),
        aux_pre: Vec::new(),
        aux_mid: Vec::new(),
        aux_post: Vec::new(),
    };
    let rb = row_bytes(img.width, ct, 8);
    let f = filter_image(&p.data, img.height as usize, rb, img.channels as usize, 5);
    assemble(&p, &deflate::zlib(&f, 6, 0))
}

fn lossy(img: &Image, p: &Params) -> Vec<u8> {
    let rgba = img.to_rgba();
    let (palette, indices) = super::quant::quantize(&rgba, p.quality);
    let k = palette.len();
    let bd = 8u8;
    let mut pl = Png {
        width: img.width,
        height: img.height,
        bit_depth: bd,
        color_type: 3,
        palette: palette.iter().map(|c| [c[0], c[1], c[2]]).collect(),
        trns: None,
        data: indices,
        aux_pre: Vec::new(),
        aux_mid: Vec::new(),
        aux_post: Vec::new(),
    };
    if palette.iter().any(|c| c[3] != 255) {
        let last = palette.iter().rposition(|c| c[3] != 255).unwrap();
        pl.trns = Some(palette[..=last].iter().map(|c| c[3]).collect());
    }
    let _ = k;
    optimize(&pl, p.png_level, p.zopfli)
}

pub fn compress(data: &[u8], p: &Params) -> Result<Vec<u8>, CsError> {
    let resize = p.width > 0 || p.height > 0;
    if p.lossless {
        let mut png = parse(data, ErrStyle::Oxipng).map_err(|e| CsError::new(&e, 20210))?;
        if resize {
            let img = simplify(to_rgba(&png));
            let (w, h) = super::resize::compute_dimensions(img.width, img.height, p.width, p.height);
            let r = super::resize::resize(&img, w, h);
            let enc = encode_simple(&r);
            png = parse(&enc, ErrStyle::Oxipng).map_err(|e| CsError::new(&e, 20210))?;
            let out = optimize(&png, p.png_level, p.zopfli);
            return Ok(if out.len() < enc.len() { out } else { enc });
        }
        let out = optimize(&png, p.png_level, p.zopfli);
        if out.len() < data.len() {
            return Ok(out);
        }
        return Ok(data.to_vec());
    }
    let png = parse(data, ErrStyle::Lodepng).map_err(|e| CsError::new(&e, 20204))?;
    let mut img = to_rgba(&png);
    if resize {
        let (w, h) = super::resize::compute_dimensions(img.width, img.height, p.width, p.height);
        img = super::resize::resize(&img, w, h).to_rgba();
    }
    Ok(lossy(&img, p))
}

pub fn dimensions(data: &[u8]) -> Option<(u32, u32)> {
    if data.len() >= 24 && &data[12..16] == b"IHDR" {
        Some((be32(data, 16), be32(data, 20)))
    } else {
        None
    }
}
