// Palette quantization: median cut with error driven stopping, k-means
// refinement and Floyd-Steinberg error diffusion.
use super::Image;
use std::collections::HashMap;

const WR: f32 = 0.5;
const WG: f32 = 1.0;
const WB: f32 = 0.45;
const WA: f32 = 0.625;

fn quality_to_mse(q: u32) -> f64 {
    if q == 0 {
        return 1e20;
    }
    if q >= 100 {
        return 0.0;
    }
    let qf = q as f64;
    let fudge = (0.016 / (0.001 + qf) - 0.001).max(0.0);
    0.45 * (fudge + 2.5 / (210.0 + qf).powf(1.2) * (100.1 - qf) / 100.0)
}

#[derive(Clone, Copy)]
struct Col {
    c: [f32; 4],
    w: f32,
}

fn to_f(p: u32) -> [f32; 4] {
    let r = ((p >> 24) & 255) as f32 / 255.0;
    let g = ((p >> 16) & 255) as f32 / 255.0;
    let b = ((p >> 8) & 255) as f32 / 255.0;
    let a = (p & 255) as f32 / 255.0;
    [r * a * WR, g * a * WG, b * a * WB, a * WA]
}

fn from_f(c: &[f32; 4]) -> [u8; 4] {
    let a = (c[3] / WA).clamp(0.0, 1.0);
    if a <= 0.0 {
        return [0, 0, 0, 0];
    }
    let r = (c[0] / WR / a).clamp(0.0, 1.0);
    let g = (c[1] / WG / a).clamp(0.0, 1.0);
    let b = (c[2] / WB / a).clamp(0.0, 1.0);
    [
        (r * 255.0 + 0.5) as u8,
        (g * 255.0 + 0.5) as u8,
        (b * 255.0 + 0.5) as u8,
        (a * 255.0 + 0.5) as u8,
    ]
}

fn dist(a: &[f32; 4], b: &[f32; 4]) -> f32 {
    let d0 = a[0] - b[0];
    let d1 = a[1] - b[1];
    let d2 = a[2] - b[2];
    let d3 = a[3] - b[3];
    d0 * d0 + d1 * d1 + d2 * d2 + d3 * d3
}

