struct BoxC {
    items: Vec<usize>,
    sum: [f64; 4],
    weight: f64,
    err: f64,
}

fn box_stats(items: &[usize], cols: &[Col]) -> ([f64; 4], f64, f64) {
    let mut sum = [0f64; 4];
    let mut w = 0f64;
    for &i in items {
        let c = &cols[i];
        for k in 0..4 {
            sum[k] += c.c[k] as f64 * c.w as f64;
        }
        w += c.w as f64;
    }
    let mean = [sum[0] / w, sum[1] / w, sum[2] / w, sum[3] / w];
    let mut err = 0f64;
    for &i in items {
        let c = &cols[i];
        let mut d = 0f64;
        for k in 0..4 {
            let x = c.c[k] as f64 - mean[k];
            d += x * x;
        }
        err += d * c.w as f64;
    }
    (sum, w, err)
}

fn median_cut(cols: &[Col], max_colors: usize, target_total_err: f64) -> Vec<[f32; 4]> {
    let all: Vec<usize> = (0..cols.len()).collect();
    let (sum, w, err) = box_stats(&all, cols);
    let mut boxes = vec![BoxC { items: all, sum, weight: w, err }];
    loop {
        let total: f64 = boxes.iter().map(|b| b.err).sum();
        if boxes.len() >= max_colors || total <= target_total_err {
            break;
        }
        // split the box with the largest error
        let (bi, _) = match boxes
            .iter()
            .enumerate()
            .filter(|(_, b)| b.items.len() > 1)
            .max_by(|a, b| a.1.err.partial_cmp(&b.1.err).unwrap())
        {
            Some(x) => x,
            None => break,
        };
        let b = boxes.swap_remove(bi);
        let mean = [b.sum[0] / b.weight, b.sum[1] / b.weight, b.sum[2] / b.weight, b.sum[3] / b.weight];
        let mut var = [0f64; 4];
        for &i in &b.items {
            for k in 0..4 {
                let x = cols[i].c[k] as f64 - mean[k];
                var[k] += x * x * cols[i].w as f64;
            }
        }
        let axis = (0..4).max_by(|&a, &c| var[a].partial_cmp(&var[c]).unwrap()).unwrap();
        let mut items = b.items;
        items.sort_by(|&a, &c| cols[a].c[axis].partial_cmp(&cols[c].c[axis]).unwrap());
        let half = b.weight / 2.0;
        let mut acc = 0f64;
        let mut cut = 1;
        for (k, &i) in items.iter().enumerate() {
            acc += cols[i].w as f64;
            if acc >= half {
                cut = (k + 1).clamp(1, items.len() - 1);
                break;
            }
        }
        let right = items.split_off(cut);
        let (s1, w1, e1) = box_stats(&items, cols);
        let (s2, w2, e2) = box_stats(&right, cols);
        boxes.push(BoxC { items, sum: s1, weight: w1, err: e1 });
        boxes.push(BoxC { items: right, sum: s2, weight: w2, err: e2 });
    }
    boxes
        .iter()
        .map(|b| {
            [
                (b.sum[0] / b.weight) as f32,
                (b.sum[1] / b.weight) as f32,
                (b.sum[2] / b.weight) as f32,
                (b.sum[3] / b.weight) as f32,
            ]
        })
        .collect()
}

fn nearest(pal: &[[f32; 4]], c: &[f32; 4]) -> usize {
    let mut best = 0;
    let mut bd = f32::MAX;
    for (i, p) in pal.iter().enumerate() {
        let d = dist(p, c);
        if d < bd {
            bd = d;
            best = i;
        }
    }
    best
}

fn kmeans(cols: &[Col], pal: &mut Vec<[f32; 4]>, iters: usize) {
    for _ in 0..iters {
        let mut sums = vec![[0f64; 5]; pal.len()];
        for c in cols {
            let i = nearest(pal, &c.c);
            for k in 0..4 {
                sums[i][k] += c.c[k] as f64 * c.w as f64;
            }
            sums[i][4] += c.w as f64;
        }
        for (i, s) in sums.iter().enumerate() {
            if s[4] > 0.0 {
                pal[i] = [(s[0] / s[4]) as f32, (s[1] / s[4]) as f32, (s[2] / s[4]) as f32, (s[3] / s[4]) as f32];
            }
        }
    }
}

/// Returns palette (RGBA) and one index per pixel.
pub fn quantize(img: &Image, quality: u32) -> (Vec<[u8; 4]>, Vec<u8>) {
    let n = (img.width * img.height) as usize;
    let px = &img.data;
    let key = |i: usize| -> u32 {
        let a = px[4 * i + 3];
