            let e = *cache.entry(k).or_insert_with(|| nearest(&pal_f2, &to_f(k)) as u8);
            idx[i] = e;
        }
        return (pal, idx);
    }
    let dither = 0.75f32;
    let mut err_cur = vec![[0f32; 4]; w + 2];
    let mut err_next = vec![[0f32; 4]; w + 2];
    for y in 0..h {
        for e in err_next.iter_mut() {
            *e = [0.0; 4];
        }
        for x in 0..w {
            let i = y * w + x;
            let base = to_f(key(i));
