                (q(c[0], WR) << 18) | (q(c[1], WG) << 12) | (q(c[2], WB) << 6) | q(c[3], WA)
            };
            let pi = *cache.entry(qk).or_insert_with(|| nearest(&pal_f2, &c) as u8);
            idx[i] = pi;
            let p = &pal_f2[pi as usize];
            let mut e = [0f32; 4];
