// Separable Lanczos3 resampling (vertical pass first, f32 intermediate).
use super::Image;

pub fn compute_dimensions(ow: u32, oh: u32, dw: u32, dh: u32) -> (u32, u32) {
    if dw > 0 && dh > 0 {
        return (dw, dh);
    }
    let ratio = ow as f64 / oh as f64;
    if dh == 0 {
        let nh = (dw as f64 / ratio).round() as u32;
        (dw, nh.max(1))
    } else {
        let nw = (dh as f64 * ratio).round() as u32;
        (nw.max(1), dh)
    }
}

fn sinc(t: f32) -> f32 {
    let a = t * std::f32::consts::PI;
    if t == 0.0 {
        1.0
    } else {
        a.sin() / a
    }
}

fn lanczos3(x: f32) -> f32 {
    if x.abs() < 3.0 {
        sinc(x) * sinc(x / 3.0)
    } else {
        0.0
    }
}

fn weights(src: u32, dst: u32) -> Vec<(u32, Vec<f32>)> {
    let ratio = src as f32 / dst as f32;
    let sratio = if ratio < 1.0 { 1.0 } else { ratio };
    let support = 3.0 * sratio;
    let mut out = Vec::with_capacity(dst as usize);
    for o in 0..dst {
        let input = (o as f32 + 0.5) * ratio;
        let left = ((input - support).floor() as i64).clamp(0, src as i64 - 1) as u32;
        let right = ((input + support).ceil() as i64).clamp(left as i64 + 1, src as i64) as u32;
        let input = input - 0.5;
        let mut ws = Vec::with_capacity((right - left) as usize);
        let mut sum = 0.0f32;
        for i in left..right {
            let w = lanczos3((i as f32 - input) / sratio);
            ws.push(w);
            sum += w;
        }
        for w in ws.iter_mut() {
            *w /= sum;
        }
        out.push((left, ws));
    }
    out
}

pub fn resize(img: &Image, nw: u32, nh: u32) -> Image {
    if nw == img.width && nh == img.height {
        return img.clone();
    }
    let ch = img.channels as usize;
    let w = img.width as usize;
    let h = img.height as usize;
    // vertical
    let vw = weights(img.height, nh);
    let mut tmp = vec![0f32; w * nh as usize * ch];
    for (oy, (left, ws)) in vw.iter().enumerate() {
        for x in 0..w {
            let mut t = [0f32; 4];
            for (i, wt) in ws.iter().enumerate() {
                let y = *left as usize + i;
                let p = (y * w + x) * ch;
                for c in 0..ch {
                    t[c] += img.data[p + c] as f32 * wt;
                }
            }
            let o = (oy * w + x) * ch;
            tmp[o..o + ch].copy_from_slice(&t[..ch]);
        }
    }
    let _ = h;
    // horizontal
    let hw = weights(img.width, nw);
    let nwu = nw as usize;
    let mut out = vec![0u8; nwu * nh as usize * ch];
    for y in 0..nh as usize {
        for (ox, (left, ws)) in hw.iter().enumerate() {
            let mut t = [0f32; 4];
            for (i, wt) in ws.iter().enumerate() {
                let x = *left as usize + i;
                let p = (y * w + x) * ch;
                for c in 0..ch {
                    t[c] += tmp[p + c] * wt;
                }
            }
            let o = (y * nwu + ox) * ch;
            for c in 0..ch {
                out[o + c] = t[c].clamp(0.0, 255.0).round() as u8;
            }
        }
    }
    Image::new(nw, nh, img.channels, out)
