            first = *stack.last().unwrap();
            out.extend(stack.iter().rev());
            out.push(first);
        } else {
            break;
        }
        if let Some(p) = prev {
            if next < 4096 {
                prefix[next as usize] = p;
                suffix[next as usize] = first;
                length[next as usize] = length[p as usize] + 1;
                next += 1;
                if next == (1 << code_size) && code_size < 12 {
                    code_size += 1;
                }
            }
        }
        prev = Some(code);
        if out.len() >= npix {
            break;
        }
    }
    out
}

fn read_subblocks(d: &[u8], pos: &mut usize) -> Option<Vec<Vec<u8>>> {
    let mut v = Vec::new();
    loop {
        if *pos >= d.len() {
            return None;
        }
        let n = d[*pos] as usize;
        *pos += 1;
        if n == 0 {
            return Some(v);
        }
        if *pos + n > d.len() {
            return None;
        }
        v.push(d[*pos..*pos + n].to_vec());
        *pos += n;
    }
}

pub fn parse(d: &[u8]) -> Result<Gif, String> {
    if d.len() < 13 || &d[0..3] != b"GIF" || !(&d[3..6] == b"87a" || &d[3..6] == b"89a") {
        return Err("malformed GIF header".to_string());
    }
    let width = u16::from_le_bytes([d[6], d[7]]);
    let height = u16::from_le_bytes([d[8], d[9]]);
    let flags = d[10];
    let mut pos = 13;
    let gct = if flags & 0x80 != 0 {
        let n = 3 * (2usize << (flags & 7));
        if pos + n > d.len() {
            return Err("Found no usable frames to encode [20409]".to_string());
        }
        let t = d[pos..pos + n].to_vec();
        pos += n;
        Some(t)
    } else {
        None
    };
    let mut g = Gif {
        version: [d[3], d[4], d[5]],
        width,
        height,
        flags,
        bg: d[11],
        aspect: d[12],
        gct,
        frames: Vec::new(),
        trailing_exts: Vec::new(),
    };
    let mut pending_gce: Option<[u8; 4]> = None;
    let mut pending_exts: Vec<(u8, Vec<Vec<u8>>)> = Vec::new();
    while pos < d.len() {
        match d[pos] {
            0x3B => break,
            0x21 => {
                if pos + 1 >= d.len() {
                    break;
                }
                let label = d[pos + 1];
                pos += 2;
                let blocks = match read_subblocks(d, &mut pos) {
                    Some(b) => b,
                    None => break,
                };
                if label == 0xF9 && !blocks.is_empty() && blocks[0].len() >= 4 {
                    let b = &blocks[0];
                    pending_gce = Some([b[0], b[1], b[2], b[3]]);
                } else {
                    pending_exts.push((label, blocks));
                }
            }
            0x2C => {
                if pos + 10 > d.len() {
                    break;
                }
                let left = u16::from_le_bytes([d[pos + 1], d[pos + 2]]);
                let top = u16::from_le_bytes([d[pos + 3], d[pos + 4]]);
                let fw = u16::from_le_bytes([d[pos + 5], d[pos + 6]]);
                let fh = u16::from_le_bytes([d[pos + 7], d[pos + 8]]);
                let f2 = d[pos + 9];
                pos += 10;
                let lct = if f2 & 0x80 != 0 {
                    let n = 3 * (2usize << (f2 & 7));
                    if pos + n > d.len() {
                        break;
                    }
                    let t = d[pos..pos + n].to_vec();
                    pos += n;
                    Some(t)
                } else {
                    None
                };
                if pos >= d.len() {
                    break;
                }
                let min_code = d[pos];
                pos += 1;
                let blocks = match read_subblocks(d, &mut pos) {
                    Some(b) => b,
                    None => break,
                };
                let data: Vec<u8> = blocks.concat();
                let npix = fw as usize * fh as usize;
                let mut idx = lzw_decode(&data, min_code, npix);
                if idx.len() < npix {
                    idx.resize(npix, 0);
                }
                idx.truncate(npix);
                let interlaced = f2 & 0x40 != 0;
                if interlaced {
                    idx = deinterlace(&idx, fw as usize, fh as usize);
                }
                g.frames.push(Frame {
                    left,
                    top,
                    width: fw,
                    height: fh,
                    interlaced,
                    lct,
                    lct_size_bits: f2 & 7,
                    sorted: f2 & 0x20 != 0,
                    min_code,
                    indices: idx,
                    gce: pending_gce.take(),
                    exts: std::mem::take(&mut pending_exts),
                });
            }
            _ => break,
        }
    }
    g.trailing_exts = pending_exts;
    if g.frames.is_empty() {
        return Err("Found no usable frames to encode [20409]".to_string());
    }
    Ok(g)
}

fn deinterlace(idx: &[u8], w: usize, h: usize) -> Vec<u8> {
    let mut out = vec![0u8; w * h];
    let mut row = 0;
    for &(start, step) in [(0usize, 8usize), (4, 8), (2, 4), (1, 2)].iter() {
        let mut y = start;
        while y < h {
            out[y * w..(y + 1) * w].copy_from_slice(&idx[row * w..(row + 1) * w]);
            row += 1;
            y += step;
        }
    }
    out
}

// ---------------------------------------------------------------------------
// LZW encoding

struct BitOut {
    out: Vec<u8>,
    acc: u32,
    n: u32,
}

impl BitOut {
    fn put(&mut self, code: u32, size: u32) {
        self.acc |= code << self.n;
        self.n += size;
        while self.n >= 8 {
            self.out.push(self.acc as u8);
            self.acc >>= 8;
            self.n -= 8;
        }
    }
    fn finish(mut self) -> Vec<u8> {
        if self.n > 0 {
            self.out.push(self.acc as u8);
        }
        self.out
    }
}

/// LZW encode. When `palette` and `tolerance` are given, pixels may be
/// matched to dictionary strings whose colors are close enough (lossy).
fn lzw_encode(idx: &[u8], min_code: u8, palette: Option<&[u8]>, tolerance: u32) -> Vec<u8> {
    let clear = 1u32 << min_code;
    let eoi = clear + 1;
    let mut code_size = min_code as u32 + 1;
    let mut next = eoi + 1;
    // dictionary: child lookup table [code][symbol]
    let ns = 1usize << min_code.max(1);
    let mut table: Vec<u16> = vec![0; 4096 * ns];
    let mut bo = BitOut { out: Vec::new(), acc: 0, n: 0 };
    bo.put(clear, code_size);
    if idx.is_empty() {
        bo.put(eoi, code_size);
        return bo.finish();
    }
    let color = |i: u8| -> (i32, i32, i32) {
        match palette {
            Some(p) if (i as usize) * 3 + 2 < p.len() => (p[i as usize * 3] as i32, p[i as usize * 3 + 1] as i32, p[i as usize * 3 + 2] as i32),
            _ => (0, 0, 0),
        }
    };
    let lossy = palette.is_some() && tolerance > 0;
    let mut cur = idx[0] as u32;
    let mut i = 1;
    while i < idx.len() {
        let s = idx[i] as usize;
        let mut child = table[cur as usize * ns + s];
        if child == 0 && lossy {
            // search a close color among the existing children
            let (r, g, b) = color(s as u8);
            let mut best = u32::MAX;
            for alt in 0..ns {
                let c = table[cur as usize * ns + alt];
                if c != 0 {
                    let (r2, g2, b2) = color(alt as u8);
                    let d = ((r - r2) * (r - r2) + (g - g2) * (g - g2) + (b - b2) * (b - b2)) as u32;
                    if d <= tolerance && d < best {
                        best = d;
                        child = c;
                    }
                }
            }
        }
        if child != 0 {
            cur = child as u32;
            i += 1;
            continue;
        }
        bo.put(cur, code_size);
        if next < 4096 {
            table[cur as usize * ns + s] = next as u16;
            next += 1;
            if next > (1 << code_size) && code_size < 12 {
                code_size += 1;
            }
        } else {
            bo.put(clear, code_size);
            for v in table.iter_mut() {
                *v = 0;
            }
            code_size = min_code as u32 + 1;
            next = eoi + 1;
        }
        cur = s as u32;
        i += 1;
    }
    bo.put(cur, code_size);
    if next == (1 << code_size) && code_size < 12 {
        code_size += 1;
    }
    bo.put(eoi, code_size);
    bo.finish()
}

fn put_subblocks(out: &mut Vec<u8>, data: &[u8]) {
    for c in data.chunks(255) {
        out.push(c.len() as u8);
        out.extend_from_slice(c);
    }
    out.push(0);
}

fn write_ext(out: &mut Vec<u8>, label: u8, blocks: &[Vec<u8>]) {
    out.push(0x21);
    out.push(label);
    for b in blocks {
        out.push(b.len() as u8);
        out.extend_from_slice(b);
    }
    out.push(0);
}

pub fn write(g: &Gif, tolerance: u32) -> Vec<u8> {
    let mut out = b"GIF89a".to_vec();
    out.extend_from_slice(&g.width.to_le_bytes());
    out.extend_from_slice(&g.height.to_le_bytes());
    out.push(g.flags);
    out.push(g.bg);
    out.push(g.aspect);
    if let Some(t) = &g.gct {
        out.extend_from_slice(t);
    }
    for f in &g.frames {
        for (l, b) in &f.exts {
            write_ext(&mut out, *l, b);
        }
        if let Some(gce) = f.gce {
            write_ext(&mut out, 0xF9, &[gce.to_vec()]);
        }
        out.push(0x2C);
        out.extend_from_slice(&f.left.to_le_bytes());
        out.extend_from_slice(&f.top.to_le_bytes());
        out.extend_from_slice(&f.width.to_le_bytes());
        out.extend_from_slice(&f.height.to_le_bytes());
        let mut f2 = 0u8;
        if let Some(_) = &f.lct {
            f2 |= 0x80 | f.lct_size_bits;
            if f.sorted {
                f2 |= 0x20;
            }
        }
        out.push(f2);
        if let Some(t) = &f.lct {
            out.extend_from_slice(t);
        }
        let ncolors = f.lct.as_ref().map(|t| t.len() / 3).or(g.gct.as_ref().map(|t| t.len() / 3)).unwrap_or(256);
        let mut bits = 2u8;
        while (1usize << bits) < ncolors {
            bits += 1;
        }
        let max_idx = f.indices.iter().copied().max().unwrap_or(0) as usize;
        while (1usize << bits) <= max_idx {
            bits += 1;
        }
        let min_code = bits.min(8);
        out.push(min_code);
        let pal = f.lct.as_deref().or(g.gct.as_deref());
        let data = lzw_encode(&f.indices, min_code, if tolerance > 0 { pal } else { None }, tolerance);
        put_subblocks(&mut out, &data);
    }
    for (l, b) in &g.trailing_exts {
        write_ext(&mut out, *l, b);
    }
    out.push(0x3B);
    out
}

/// Crop frames to the region that changed compared to the previous canvas.
fn optimize_frames(g: &mut Gif) {
    let w = g.width as usize;
    let h = g.height as usize;
    if w == 0 || h == 0 {
        return;
    }
    // canvas of (palette color rgb, valid)
    let mut canvas: Vec<i32> = vec![-1; w * h];
    let mut prev_disposal = 0u8;
    let mut prev_rect = (0usize, 0usize, 0usize, 0usize);
    let mut saved: Vec<i32> = Vec::new();
    for fi in 0..g.frames.len() {
        let f = g.frames[fi].clone();
        let pal = f.lct.clone().or(g.gct.clone()).unwrap_or_default();
        let trans = f.gce.and_then(|e| if e[0] & 1 != 0 { Some(e[3]) } else { None });
        let disposal = f.gce.map(|e| (e[0] >> 2) & 7).unwrap_or(0);
        // apply previous disposal
        if fi > 0 {
            match prev_disposal {
                2 => {
                    let (x0, y0, pw, ph) = prev_rect;
                    for y in y0..(y0 + ph).min(h) {
                        for x in x0..(x0 + pw).min(w) {
                            canvas[y * w + x] = -1;
                        }
                    }
                }
                3 => {
                    if !saved.is_empty() {
                        canvas = saved.clone();
                    }
                }
                _ => {}
            }
        }
        if disposal == 3 {
            saved = canvas.clone();
        }
        let col = |i: u8| -> i32 {
            let k = i as usize * 3;
            if k + 2 < pal.len() {
                ((pal[k] as i32) << 16) | ((pal[k + 1] as i32) << 8) | pal[k + 2] as i32
            } else {
                0
            }
        };
        let fw = f.width as usize;
        let fh = f.height as usize;
        let fx = f.left as usize;
        let fy = f.top as usize;
        // bounding box of changed pixels
        let can_crop = fi > 0 && (prev_disposal == 0 || prev_disposal == 1) && disposal != 2 && disposal != 3;
        let (mut minx, mut miny, mut maxx, mut maxy) = (usize::MAX, usize::MAX, 0usize, 0usize);
        for y in 0..fh {
            for x in 0..fw {
                let cx = fx + x;
                let cy = fy + y;
                if cx >= w || cy >= h {
                    continue;
                }
                let v = f.indices[y * fw + x];
                if Some(v) == trans {
                    continue;
                }
                let c = col(v);
                if canvas[cy * w + cx] != c {
                    minx = minx.min(x);
                    miny = miny.min(y);
                    maxx = maxx.max(x);
                    maxy = maxy.max(y);
                }
            }
        }
        // draw
        for y in 0..fh {
            for x in 0..fw {
                let cx = fx + x;
                let cy = fy + y;
                if cx >= w || cy >= h {
                    continue;
                }
                let v = f.indices[y * fw + x];
                if Some(v) == trans {
                    continue;
                }
                canvas[cy * w + cx] = col(v);
            }
        }
        if can_crop {
            if minx == usize::MAX {
                minx = 0;
                miny = 0;
                maxx = 0;
                maxy = 0;
            }
            let nw = maxx - minx + 1;
            let nh = maxy - miny + 1;
            if nw != fw || nh != fh {
                let mut ni = Vec::with_capacity(nw * nh);
                for y in miny..=maxy {
                    ni.extend_from_slice(&f.indices[y * fw + minx..y * fw + maxx + 1]);
                }
                let fr = &mut g.frames[fi];
                fr.left = (fx + minx) as u16;
                fr.top = (fy + miny) as u16;
                fr.width = nw as u16;
                fr.height = nh as u16;
                fr.indices = ni;
            }
        }
        prev_disposal = disposal;
        let fr = &g.frames[fi];
        prev_rect = (fr.left as usize, fr.top as usize, fr.width as usize, fr.height as usize);
    }
}

pub fn compress(data: &[u8], p: &Params) -> Result<Vec<u8>, CsError> {
    let mut g = parse(data).map_err(|e| {
        if e.starts_with("malformed") {
            CsError::new(&e, 20404)
        } else {
            CsError::new(&e, 20411)
        }
    })?;
    if p.width > 0 || p.height > 0 {
        let (w, h) = super::resize::compute_dimensions(g.width as u32, g.height as u32, p.width, p.height);
        if w <= g.width as u32 && h <= g.height as u32 {
            g = resize_gif(&g, w, h);
        }
    }
    optimize_frames(&mut g);
    for f in g.frames.iter_mut() {
        f.interlaced = false;
    }
    let tolerance = if p.lossless || p.quality >= 100 { 0 } else { ((100 - p.quality) * (100 - p.quality)) / 4 + 10 };
    Ok(write(&g, tolerance))
}

fn resize_gif(g: &Gif, nw: u32, nh: u32) -> Gif {
    // render first frame canvas per frame and rescale with nearest neighbour
    let mut out = g.clone();
    let sx = g.width as f64 / nw as f64;
    let sy = g.height as f64 / nh as f64;
    for f in out.frames.iter_mut() {
        let fw = f.width as usize;
        let fh = f.height as usize;
        let nfw = ((fw as f64 / sx).round() as usize).max(1);
        let nfh = ((fh as f64 / sy).round() as usize).max(1);
        let mut ni = Vec::with_capacity(nfw * nfh);
        for y in 0..nfh {
            let syy = ((y as f64 + 0.5) * sy) as usize;
            for x in 0..nfw {
                let sxx = ((x as f64 + 0.5) * sx) as usize;
                ni.push(f.indices[syy.min(fh - 1) * fw + sxx.min(fw - 1)]);
            }
        }
        f.left = (f.left as f64 / sx).round() as u16;
        f.top = (f.top as f64 / sy).round() as u16;
        f.width = nfw as u16;
        f.height = nfh as u16;
        f.indices = ni;
    }
    out.width = nw as u16;
    out.height = nh as u16;
    out
}

pub fn decode_first(data: &[u8]) -> Result<Image, String> {
    let g = parse(data)?;
    let f = &g.frames[0];
    let pal = f.lct.clone().or(g.gct.clone()).unwrap_or_default();
    let trans = f.gce.and_then(|e| if e[0] & 1 != 0 { Some(e[3]) } else { None });
    let w = g.width as usize;
    let h = g.height as usize;
    let mut px = vec![0u8; w * h * 4];
    for y in 0..f.height as usize {
        for x in 0..f.width as usize {
            let cx = f.left as usize + x;
            let cy = f.top as usize + y;
            if cx >= w || cy >= h {
                continue;
            }
            let v = f.indices[y * f.width as usize + x];
            if Some(v) == trans {
                continue;
            }
            let k = v as usize * 3;
            let o = (cy * w + cx) * 4;
            if k + 2 < pal.len() {
                px[o] = pal[k];
                px[o + 1] = pal[k + 1];
                px[o + 2] = pal[k + 2];
            }
            px[o + 3] = 255;
        }
    }
    Ok(super::png::simplify(Image::new(w as u32, h as u32, 4, px)))
}

pub fn encode_simple(img: &Image) -> Vec<u8> {
    let rgba = img.to_rgba();
    let (pal, idx) = super::quant::quantize(&rgba, 100);
    let mut bits = 1u8;
    while (1usize << bits) < pal.len() {
        bits += 1;
    }
    let mut gct = Vec::new();
    for c in &pal {
        gct.extend_from_slice(&c[..3]);
    }
    while gct.len() < 3 * (1usize << bits) {
        gct.push(0);
    }
    let trans = pal.iter().position(|c| c[3] < 128);
    let g = Gif {
        version: *b"89a",
        width: img.width as u16,
        height: img.height as u16,
        flags: 0x80 | (bits - 1),
        bg: 0,
        aspect: 0,
        gct: Some(gct),
        frames: vec![Frame {
            left: 0,
            top: 0,
            width: img.width as u16,
            height: img.height as u16,
            interlaced: false,
            lct: None,
            lct_size_bits: 0,
            sorted: false,
            min_code: bits.max(2),
            indices: idx,
            gce: trans.map(|t| [1, 0, 0, t as u8]),
            exts: Vec::new(),
        }],
        trailing_exts: Vec::new(),
    };
    write(&g, 0)
}

pub fn dimensions(data: &[u8]) -> Option<(u32, u32)> {
    if data.len() >= 10 {
        Some((u16::from_le_bytes([data[6], data[7]]) as u32, u16::from_le_bytes([data[8], data[9]]) as u32))
    } else {
        None
    }
}
