// GIF decoding and re-encoding (LZW), with an optional lossy LZW matcher.
use super::Image;
use crate::caesium::{CsError, Params};

#[derive(Clone, Debug)]
pub struct Frame {
    pub left: u16,
    pub top: u16,
    pub width: u16,
    pub height: u16,
    pub interlaced: bool,
    pub lct: Option<Vec<u8>>,
    pub lct_size_bits: u8,
    pub sorted: bool,
    pub min_code: u8,
    pub indices: Vec<u8>,
