/// Little-endian strip TIFF with Deflate compressed strips.
pub fn encode_deflate(img: &Image, level: u8) -> Vec<u8> {
    let w = img.width as usize;
    let h = img.height as usize;
    let spp = img.channels as usize;
    let row_bytes = w * spp;
    let rows_per_strip = ((1_000_000 + row_bytes - 1) / row_bytes).max(1);
    let nstrips = (h + rows_per_strip - 1) / rows_per_strip;
    let mut out = vec![b'I', b'I', 42, 0, 0, 0, 0, 0];
    let mut offsets = Vec::new();
    let mut counts = Vec::new();
    for s in 0..nstrips {
        let y0 = s * rows_per_strip;
        let y1 = ((s + 1) * rows_per_strip).min(h);
        let raw = &img.data[y0 * row_bytes..y1 * row_bytes];
        let z = if level == 0 { raw.to_vec() } else { super::deflate::zlib(raw, level, 0) };
        offsets.push(out.len() as u32);
        counts.push(z.len() as u32);
        out.extend_from_slice(&z);
    }
