        (256, V::Long(vec![w as u32])),
        (257, V::Long(vec![h as u32])),
        (258, V::Short(vec![8; spp])),
        (259, V::Short(vec![if level == 0 { 1 } else { 8 }])),
        (262, V::Short(vec![photometric])),
        (273, V::Long(offsets)),
        (277, V::Short(vec![spp as u16])),
        (278, V::Long(vec![rows_per_strip as u32])),
        (279, V::Long(counts)),
        (282, V::Rational(1, 1)),
        (283, V::Rational(1, 1)),
        (296, V::Short(vec![1])),
    ];
    if spp == 2 || spp == 4 {
        entries.push((338, V::Short(vec![2])));
    }
    entries.push((339, V::Short(vec![1; spp])));
    entries.sort_by_key(|e| e.0);
    // out-of-line data in tag order
    let mut inline: Vec<(u16, u16, u32, [u8; 4])> = Vec::new();
    for (tag, v) in entries.iter() {
        let (typ, count, bytes): (u16, u32, Vec<u8>) = match v {
            V::Short(s) => (3, s.len() as u32, s.iter().flat_map(|x| x.to_le_bytes()).collect()),
            V::Long(s) => (4, s.len() as u32, s.iter().flat_map(|x| x.to_le_bytes()).collect()),
            V::Rational(a, b) => (5, 1, [a.to_le_bytes(), b.to_le_bytes()].concat()),
