        let y1 = ((s + 1) * rows_per_strip).min(h);
        let raw = &img.data[y0 * row_bytes..y1 * row_bytes];
        let z = if level == 0 { raw.to_vec() } else { super::deflate::zlib(raw, level, 0) };
        offsets.push(out.len() as u32);
        counts.push(z.len() as u32);
        out.extend_from_slice(&z);
    }
    let photometric: u16 = if spp <= 2 { 1 } else { 2 };
    // entries: (tag, type, values)
