        for sym in 0..256usize {
            let cur = actbl.ehufsi[sym];
            let cands: Vec<u8> = if cur == 0 { vec![12, 14, 16] } else { vec![cur.saturating_sub(1).max(1), cur + 1, 0] };
            for &c in cands.iter() {
                if c == cur { continue; }
                actbl.ehufsi[sym] = c;
                let b = count_bad(ci, &comps, &raws, &qq, &dctbl, &actbl, &r, rows);
                if b < best {
                    best = b; improved = true;
                    eprintln!("sym {:02x}: {} -> {} bad {}", sym, cur, c, b);
                    break;
                } else {
                    actbl.ehufsi[sym] = cur;
                }
            }
            if best == 0 { break; }
        }
        if !improved || best == 0 { break; }
    }
    println!("final bad {}", best);
    for sym in 0..256 { if actbl.ehufsi[sym] != orig[sym] { println!("  {:02x}: count {} len {} -> {}", sym, g.counts[ht + 2][sym], orig[sym], actbl.ehufsi[sym]); } }
