/// RIFF chunk list of a WebP container (fourcc, payload).
pub fn chunks(data: &[u8]) -> Vec<([u8; 4], Vec<u8>)> {
    let mut out = Vec::new();
    if data.len() < 12 {
        return out;
    }
    let mut p = 12;
    while p + 8 <= data.len() {
        let mut t = [0u8; 4];
        t.copy_from_slice(&data[p..p + 4]);
        let len = u32::from_le_bytes([data[p + 4], data[p + 5], data[p + 6], data[p + 7]]) as usize;
