/// Composite all frames into full RGBA canvases (with frame delays).
pub fn render_frames(g: &Gif) -> Vec<(Vec<u8>, u16)> {
    let w = g.width as usize;
    let h = g.height as usize;
    let mut canvas = vec![0u8; w * h * 4];
    let mut out = Vec::new();
    let mut prev_disposal = 0u8;
    let mut prev_rect = (0usize, 0usize, 0usize, 0usize);
    let mut saved: Vec<u8> = Vec::new();
    for f in &g.frames {
        match prev_disposal {
            2 => {
                let (x0, y0, pw, ph) = prev_rect;
                for y in y0..(y0 + ph).min(h) {
                    for x in x0..(x0 + pw).min(w) {
                        let o = (y * w + x) * 4;
                        canvas[o..o + 4].copy_from_slice(&[0, 0, 0, 0]);
                    }
                }
            }
            3 => {
                if !saved.is_empty() {
                    canvas.copy_from_slice(&saved);
                }
            }
            _ => {}
        }
        let disposal = f.gce.map(|e| (e[0] >> 2) & 7).unwrap_or(0);
        if disposal == 3 {
            saved = canvas.clone();
        }
        let pal = f.lct.clone().or(g.gct.clone()).unwrap_or_default();
        let trans = f.gce.and_then(|e| if e[0] & 1 != 0 { Some(e[3]) } else { None });
        let fw = f.width as usize;
        for y in 0..f.height as usize {
            for x in 0..fw {
                let cx = f.left as usize + x;
                let cy = f.top as usize + y;
                if cx >= w || cy >= h {
                    continue;
                }
                let v = f.indices[y * fw + x];
                if Some(v) == trans {
                    continue;
                }
                let k = v as usize * 3;
                let o = (cy * w + cx) * 4;
                if k + 2 < pal.len() {
                    canvas[o] = pal[k];
                    canvas[o + 1] = pal[k + 1];
                    canvas[o + 2] = pal[k + 2];
                } else {
                    canvas[o..o + 3].copy_from_slice(&[0, 0, 0]);
                }
                canvas[o + 3] = 255;
            }
        }
        let delay = f.gce.map(|e| u16::from_le_bytes([e[1], e[2]])).unwrap_or(0);
        out.push((canvas.clone(), delay));
        prev_disposal = disposal;
        prev_rect = (f.left as usize, f.top as usize, f.width as usize, f.height as usize);
    }
    out
}

/// Re-encode in the style of gifski: tiny global palette, per-frame local
/// palettes, frame differencing with transparency, optional lossy LZW.
pub fn encode_frames(g: &Gif, frames: &[(Vec<u8>, u16)], w: usize, h: usize, quality: u32, lossless: bool) -> Vec<u8> {
    let mut out = b"GIF89a".to_vec();
    out.extend_from_slice(&(w as u16).to_le_bytes());
    out.extend_from_slice(&(h as u16).to_le_bytes());
    out.push(0x80);
    out.push(0);
    out.push(0);
    out.extend_from_slice(&[0, 0, 0, 0, 0, 0]);
    let looping = g.frames.iter().flat_map(|f| f.exts.iter()).chain(g.trailing_exts.iter()).find(|(l, b)| *l == 0xFF && !b.is_empty() && b[0].starts_with(b"NETSCAPE2.0"));
    if let Some((_, b)) = looping {
        write_ext(&mut out, 0xFF, b);
    } else if frames.len() > 1 {
        write_ext(&mut out, 0xFF, &[b"NETSCAPE2.0".to_vec(), vec![1, 0, 0]]);
    }
    write_ext(&mut out, 0xFE, &[b"gif.ski".to_vec()]);
    let q = if lossless { 100 } else { quality };
    let tolerance = if q >= 100 { 0 } else { ((100 - q) * (100 - q)) / 3 + 20 };
    let mut prev: Option<&Vec<u8>> = None;
    for (fi, (canvas, delay)) in frames.iter().enumerate() {
        // changed region
        let (mut x0, mut y0, mut x1, mut y1) = (0usize, 0usize, w - 1, h - 1);
        if let Some(p) = prev {
            let (mut minx, mut miny, mut maxx, mut maxy) = (usize::MAX, usize::MAX, 0usize, 0usize);
            for y in 0..h {
                for x in 0..w {
                    let o = (y * w + x) * 4;
                    if canvas[o..o + 4] != p[o..o + 4] {
                        minx = minx.min(x);
                        miny = miny.min(y);
                        maxx = maxx.max(x);
                        maxy = maxy.max(y);
                    }
                }
            }
            if minx == usize::MAX {
                minx = 0;
                miny = 0;
                maxx = 0;
                maxy = 0;
            }
            x0 = minx;
            y0 = miny;
            x1 = maxx;
            y1 = maxy;
        }
        let fw = x1 - x0 + 1;
        let fh = y1 - y0 + 1;
        let mut px = Vec::with_capacity(fw * fh * 4);
        let mut transparent_used = false;
        for y in y0..=y1 {
            for x in x0..=x1 {
                let o = (y * w + x) * 4;
                let same = prev.map(|p| p[o..o + 4] == canvas[o..o + 4]).unwrap_or(false);
                if same || canvas[o + 3] < 128 {
                    px.extend_from_slice(&[0, 0, 0, 0]);
                    transparent_used = true;
                } else {
                    px.extend_from_slice(&[canvas[o], canvas[o + 1], canvas[o + 2], 255]);
                }
            }
        }
        let img = Image::new(fw as u32, fh as u32, 4, px);
        let (pal, idx) = super::quant::quantize(&img, q);
        // move the transparent entry (if any) to index 0
        let mut order: Vec<usize> = (0..pal.len()).collect();
        if let Some(t) = pal.iter().position(|c| c[3] == 0) {
            order.retain(|&i| i != t);
            order.insert(0, t);
        } else if transparent_used {
            // no transparent palette slot was created; reserve one
        }
        let mut remap = vec![0u8; pal.len()];
        for (ni, &oi) in order.iter().enumerate() {
            remap[oi] = ni as u8;
        }
        let mut bits = 1u8;
        while (1usize << bits) < order.len() {
            bits += 1;
        }
        let mut lct = Vec::with_capacity(3 << bits);
        for &oi in order.iter() {
            let c = pal[oi];
            if c[3] == 0 {
                lct.extend_from_slice(&[0, 0, 0]);
            } else {
                lct.extend_from_slice(&c[..3]);
            }
        }
        while lct.len() < 3 << bits {
            lct.push(0);
        }
        let indices: Vec<u8> = idx.iter().map(|&i| remap[i as usize]).collect();
        let has_t = pal.iter().any(|c| c[3] == 0);
        let d = if *delay < 2 { 2 } else { *delay };
        let gce = [if has_t { 0x05 } else { 0x04 }, d as u8, (d >> 8) as u8, 0];
        write_ext(&mut out, 0xF9, &[gce.to_vec()]);
        out.push(0x2C);
        out.extend_from_slice(&(x0 as u16).to_le_bytes());
        out.extend_from_slice(&(y0 as u16).to_le_bytes());
        out.extend_from_slice(&(fw as u16).to_le_bytes());
        out.extend_from_slice(&(fh as u16).to_le_bytes());
        out.push(0x80 | (bits - 1));
        out.extend_from_slice(&lct);
        let min_code = bits.max(2);
        out.push(min_code);
        let data = lzw_encode(&indices, min_code, if tolerance > 0 { Some(&lct) } else { None }, tolerance);
        put_subblocks(&mut out, &data);
        prev = Some(canvas);
        let _ = fi;
    }
    out.push(0x3B);
    out
}
