use codecs::jpeg;
use codecs::jpegenc as je;

// jpeg_gen_optimal_table with C side effects on freq
fn gen_clobber(freq: &mut [i64; 257]) -> je::HuffTable {
    let mut cnt = [0u32; 257];
    // compute table from a copy (same algorithm), then emulate clobbering
    for i in 0..257 { cnt[i] = freq[i].max(0) as u32; }
    let t = je::HuffTable::optimal(&cnt);
    // emulate: freq[256]=1 then merges leave a single root
    freq[256] = 1;
    let mut f = *freq;
    loop {
        let mut c1: i64 = -1; let mut v = i64::MAX;
        for i in 0..257 { if f[i] != 0 && f[i] <= v { v = f[i]; c1 = i as i64; } }
        let mut c2: i64 = -1; v = i64::MAX;
        for i in 0..257 { if f[i] != 0 && f[i] <= v && i as i64 != c1 { v = f[i]; c2 = i as i64; } }
        if c2 < 0 { break; }
        f[c1 as usize] += f[c2 as usize]; f[c2 as usize] = 0;
    }
    *freq = f;
    t
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let src = std::fs::read(&args[1]).unwrap();
    let refd = std::fs::read(&args[2]).unwrap();
    let q: i32 = args[3].parse().unwrap();
    let zeroing = args[4] == "zero";
    let shared = args[5] == "shared";
    let j = jpeg::decode_coefficients(&src).unwrap();
    let r = jpeg::decode_coefficients(&refd).unwrap();
    let planes = jpeg::full_planes(&j);
    let samp: Vec<(usize, usize)> = r.components.iter().map(|c| (c.h, c.v)).collect();
    let ids: Vec<u8> = r.components.iter().map(|c| c.id).collect();
    let opts = je::LossyOptions { quality: q, progressive: true, samp, tqs: vec![0, 1, 1], hts: vec![0, 1, 1], trellis: false, deringing: true };
    let (mut comps, qt, raws, _) = je::compute_coefficients_dbg(&planes, j.width, j.height, &ids, &opts);
    let nc = comps.len();
    let mut counts = [[0i64; 257]; 2];
    let mut tables: [Option<je::HuffTable>; 2] = [None, None];
    let cfg = je::TrellisCfg { lambda_log_scale1: 14.75, lambda_log_scale2: 16.5, dc: true };
    let gather = |comps: &Vec<je::CompCoefs>, ci: usize, counts: &mut [i64; 257]| {
        let mut g = je::Coder::gatherer();
        je::code_progressive(comps, &je::Scan::new(&[ci], 1, 63, 0, 0), j.width, j.height, &mut g);
        let t = comps[ci].info.ht + 2;
        for k in 0..257 { counts[k] += g.counts[t][k] as i64; }
    };
    for ci in 0..nc {
        let tb = if shared { 0 } else { comps[ci].info.ht };
        // gather plain (main / huff_opt pass)
        if zeroing { counts[tb] = [0; 257]; }
        gather(&comps, ci, &mut counts[tb]);
        tables[tb] = Some(gen_clobber(&mut counts[tb]));
        // trellis
        let actbl = tables[tb].clone().unwrap();
        let dctbl = je::std_dc_table(comps[ci].info.ht != 0);
        let info = comps[ci].info.clone();
        let qq = qt[info.tq];
        let wb = info.width_in_blocks;
        let mut last_dc = 0;
        for by in 0..info.height_in_blocks {
            if by % info.v == 0 { last_dc = 0; }
            let mut row: Vec<[i16; 64]> = comps[ci].blocks[by * info.bw..by * info.bw + wb].to_vec();
            je::quantize_trellis(&cfg, &dctbl, &actbl, &mut row, &raws[ci][by * wb..(by + 1) * wb], &qq, &mut last_dc, 1, 63);
            comps[ci].blocks[by * info.bw..by * info.bw + wb].copy_from_slice(&row);
        }
