        gather(&comps, ci, &mut counts[tb]);
        tables[tb] = Some(gen_clobber(&mut counts[tb]));
    }
    for ci in 0..nc {
        let c = &comps[ci]; let rc = &r.components[ci];
        let mut bad = 0;
        for by in 0..c.info.height_in_blocks { for bx in 0..c.info.width_in_blocks { if c.blk(bx, by)[1..] != rc.coefs[by * rc.bw + bx][1..] { bad += 1; } } }
        print!("comp {} bad {}  ", ci, bad);
    }
    println!();
}
