        out[0] = inp[0];
        out[1] = inp[0];
        return;
    }
    out[0] = inp[0];
    out[1] = (inp[0] * 3 + inp[1] + 2) >> 2;
    for i in 1..dw - 1 {
        let s = 3 * inp[i] + 2;
        out[i * 2] = (s + inp[i - 1]) >> 2;
        out[i * 2 + 1] = (s + inp[i + 1]) >> 2;
