/// Decode to pixels the way the generic image decoder does.
pub fn decode_image_generic(data: &[u8]) -> Result<super::Image, JpegError> {
    let j = decode_coefficients(data)?;
    let cs = j.color_space();
    if j.components.len() != 3 || cs != ColorSpace::YCbCr {
        return decode_image(data);
    }
    let clampv = std::env::var("ZCLAMP").map(|v| v == "1").unwrap_or(true);
    let w = j.width;
    let h = j.height;
    let mut full: Vec<Vec<i32>> = Vec::new();
    for c in &j.components {
        let q = j.qtables[c.tq].unwrap_or([1u16; 64]);
        let stride = c.bw * 8;
        let mut plane = vec![0i32; stride * c.bh * 8];
        for by in 0..c.bh {
            for bx in 0..c.bw {
                let b = idct_islow_i32(&c.coefs[by * c.bw + bx], &q, clampv);
                for y in 0..8 {
                    for x in 0..8 {
                        plane[(by * 8 + y) * stride + bx * 8 + x] = b[y * 8 + x];
                    }
                }
            }
        }
        let hf = j.max_h / c.h;
        let vf = j.max_v / c.v;
        let dw = (w * c.h + j.max_h - 1) / j.max_h;
        let dh = (h * c.v + j.max_v - 1) / j.max_v;
        let row = |y: isize| -> &[i32] {
            let yy = y.clamp(0, dh as isize - 1) as usize;
            &plane[yy * stride..yy * stride + dw]
        };
        let mut out = vec![0i32; w * h];
        let mut vrow = vec![0i32; dw];
        let mut line = vec![0i32; dw * 2 + 2];
        for y in 0..h {
            if vf == 2 {
                let iy = (y / 2) as isize;
                let near = row(iy);
                let far = if y % 2 == 0 { row(iy - 1) } else { row(iy + 1) };
                for x in 0..dw {
                    vrow[x] = (near[x] * 3 + far[x] + 2) >> 2;
                }
            } else {
                let r = row((y / vf.max(1)) as isize);
                vrow[..dw].copy_from_slice(r);
            }
            if hf == 2 {
                up_h2(&vrow, dw, &mut line);
                out[y * w..y * w + w].copy_from_slice(&line[..w]);
            } else if hf == 1 {
                out[y * w..y * w + w].copy_from_slice(&vrow[..w]);
            } else {
                for x in 0..w {
                    out[y * w + x] = vrow[(x / hf).min(dw - 1)];
                }
            }
        }
        full.push(out);
    }
    let n = w * h;
    let mut px = vec![0u8; n * 3];
    let (cr_r, cb_b, cr_g, cb_g) = ycc_tables();
    for i in 0..n {
        let y = full[0][i];
        let cb = full[1][i].clamp(0, 255) as usize;
        let cr = full[2][i].clamp(0, 255) as usize;
        px[3 * i] = (y + cr_r[cr]).clamp(0, 255) as u8;
        px[3 * i + 1] = (y + ((cb_g[cb] + cr_g[cr]) >> 16)).clamp(0, 255) as u8;
        px[3 * i + 2] = (y + cb_b[cb]).clamp(0, 255) as u8;
    }
    Ok(super::Image::new(w as u32, h as u32, 3, px))
}
