// Behaviour of the general purpose image decoding layer (format guessing,
// error texts) and of the header-only size probe used for resizing.
use super::Image;

pub fn guess_ok(d: &[u8]) -> bool {
    d.starts_with(&[0x89, b'P', b'N', b'G', 0x0D, 0x0A, 0x1A, 0x0A])
        || d.starts_with(&[0xFF, 0xD8, 0xFF])
        || d.starts_with(b"GIF87a")
        || d.starts_with(b"GIF89a")
        || (d.len() >= 12 && &d[0..4] == b"RIFF" && &d[8..12] == b"WEBP")
        || d.starts_with(b"II*\0")
        || d.starts_with(b"MM\0*")
}

fn chunk_type_debug(t: &[u8; 4]) -> String {
    format!(
        "ChunkType {{ type: {}, critical: {}, private: {}, reserved: {}, safecopy: {} }}",
        String::from_utf8_lossy(t),
        t[0] & 0x20 == 0,
        t[1] & 0x20 != 0,
        t[2] & 0x20 != 0,
        t[3] & 0x20 != 0
    )
}

fn png_error(d: &[u8]) -> Option<String> {
    let mut p = 8;
    let mut seen_ihdr = false;
    let mut ct = 0u8;
    let mut idat = Vec::new();
    let mut dims = (0u32, 0u32, 0u8, 0u8, 0u8);
    loop {
        if p + 8 > d.len() {
            return Some("unexpected end of file".to_string());
        }
        let len = u32::from_be_bytes([d[p], d[p + 1], d[p + 2], d[p + 3]]) as usize;
        let mut t = [0u8; 4];
        t.copy_from_slice(&d[p + 4..p + 8]);
        if &t == b"IDAT" && seen_ihdr {
            // image data is decoded while it is read
            let avail = &d[p + 8..d.len().min(p + 8 + len)];
            idat.extend_from_slice(avail);
            if p + 12 + len > d.len() {
                if let Some(e) = idat_error(&idat, dims, false) {
                    return Some(e);
                }
                return Some("unexpected end of file".to_string());
            }
            p += 12 + len;
            continue;
        }
        if p + 12 + len > d.len() {
            return Some("unexpected end of file".to_string());
        }
        let body = &d[p + 8..p + 8 + len];
        let crc = u32::from_be_bytes([d[p + 8 + len], d[p + 9 + len], d[p + 10 + len], d[p + 11 + len]]);
        let calc = super::png::crc_of(&t, body);
        if !idat.is_empty() && &t != b"IDAT" {
            if let Some(e) = idat_error(&idat, dims, true) {
                return Some(e);
            }
            idat.clear();
            idat.push(0);
        }
        if calc != crc {
            return Some(format!(
                "Format error decoding Png: CRC error: expected {:#x} have {:#x} while decoding {} chunk.",
                calc,
                crc,
                chunk_type_debug(&t)
            ));
        }
        match &t {
            b"IHDR" => {
                if len >= 13 {
                    ct = body[9];
                    dims = (
                        u32::from_be_bytes([body[0], body[1], body[2], body[3]]),
                        u32::from_be_bytes([body[4], body[5], body[6], body[7]]),
                        body[8],
                        body[9],
                        body[12],
                    );
                    if !matches!(ct, 0 | 2 | 3 | 4 | 6) {
                        return Some(format!("Format error decoding Png: Invalid color type {}.", ct));
                    }
                }
                seen_ihdr = true;
            }
            b"IEND" => {
                return None;
            }
            _ => {
                if t[0] & 0x20 == 0 && &t != b"PLTE" {
                    return Some(format!("Format error decoding Png: Unrecognized critical chunk: {}", chunk_type_debug(&t)));
                }
            }
        }
        p += 12 + len;
    }
}

fn idat_error(idat: &[u8], dims: (u32, u32, u8, u8, u8), complete: bool) -> Option<String> {
    let (raw, ok) = super::deflate::inflate_zlib_partial(idat);
    if !ok && complete {
        if idat.len() > 2 {
            let btype = (idat[2] >> 1) & 3;
            if btype == 3 {
                return Some("Format error decoding Png: Corrupt deflate stream. InvalidBlockType".to_string());
            }
        }
    }
    // filter bytes
    let (w, h, bd, ct, il) = dims;
    if il == 0 && w > 0 {
        let rb = super::png::row_bytes(w, ct, bd);
        let mut pos = 0;
        for _ in 0..h {
            if pos >= raw.len() {
                break;
            }
            let f = raw[pos];
            if f > 4 {
                return Some(format!("Format error decoding Png: Unknown filter method {}.", f));
            }
            pos += rb + 1;
        }
        if complete && ok && raw.len() < (rb + 1) * h as usize {
            return Some("Format error decoding Png: IDAT or fDAT chunk does not have enough data for image.".to_string());
        }
    }
    if !ok && complete {
        return Some("Format error decoding Png: Corrupt deflate stream. InvalidBlockType".to_string());
    }
    None
}

fn be16(d: &[u8], p: usize) -> usize {
    ((d[p] as usize) << 8) | d[p + 1] as usize
}

fn jpeg_error(d: &[u8]) -> Option<String> {
    let mut p = 2;
    loop {
        // find marker
        if p >= d.len() {
            return Some("Format error decoding Jpeg: I/O errors Generic I/O error: Cannot satisfy read\n".to_string());
        }
        if d[p] != 0xFF {
            p += 1;
            continue;
        }
        while p < d.len() && d[p] == 0xFF {
            p += 1;
        }
        if p >= d.len() {
            return Some("Format error decoding Jpeg: I/O errors Generic I/O error: Cannot satisfy read\n".to_string());
        }
        let m = d[p];
        p += 1;
        if m == 0x00 || m == 0x01 || (0xD0..=0xD8).contains(&m) {
            continue;
        }
        if m == 0xD9 {
            return Some("Format error decoding Jpeg: I/O errors Generic I/O error: Cannot satisfy read\n".to_string());
        }
        if p + 2 > d.len() {
            return Some("Format error decoding Jpeg: I/O errors Generic I/O error: Cannot satisfy read\n".to_string());
        }
        let len = be16(d, p);
        if m == 0xDA {
            return None;
        }
        if p + len > d.len() {
            let mut start = p + 2;
            let mut expected = len.saturating_sub(2);
            if m == 0xE1 && d.len() >= start + 6 && &d[start..start + 6] == b"Exif\0\0" {
                start += 6;
                expected = expected.saturating_sub(6);
            }
            return Some(format!(
                "Format error decoding Jpeg: I/O errors Not enough bytes, expected {} but found {}\n",
                expected,
                d.len().saturating_sub(start)
            ));
        }
        p += len;
    }
}

fn gif_error(d: &[u8]) -> Option<String> {
    match super::gif::parse(d) {
        Ok(g) => {
            let _ = g;
            None
        }
        Err(_) => Some("Format error decoding Gif: Unexpected End of File".to_string()),
    }
}

fn first_frame_complete_gif(d: &[u8]) -> bool {
    // the first image's data sub-blocks must be complete
    if d.len() < 13 {
        return false;
    }
    let flags = d[10];
    let mut pos = 13;
    if flags & 0x80 != 0 {
        pos += 3 * (2usize << (flags & 7));
    }
    while pos < d.len() {
        match d[pos] {
            0x21 => {
                pos += 2;
                loop {
                    if pos >= d.len() {
                        return false;
                    }
                    let n = d[pos] as usize;
                    pos += 1 + n;
                    if n == 0 {
                        break;
                    }
                }
            }
            0x2C => {
                if pos + 10 > d.len() {
                    return false;
                }
                let f2 = d[pos + 9];
                pos += 10;
                if f2 & 0x80 != 0 {
                    pos += 3 * (2usize << (f2 & 7));
                }
                pos += 1;
                loop {
                    if pos >= d.len() {
                        return false;
                    }
                    let n = d[pos] as usize;
                    pos += 1 + n;
                    if n == 0 {
                        return pos <= d.len();
                    }
                }
            }
            _ => return false,
        }
    }
    false
}

fn webp_error(d: &[u8]) -> Option<String> {
    let cs = super::webp::chunks(d);
    for (t, body) in cs.iter() {
        if t == b"VP8 " {
            let declared = u32::from_le_bytes([d[16], d[17], d[18], d[19]]) as usize;
            if body.len() < 10 {
                return Some("failed to fill whole buffer".to_string());
            }
            let tag = body[0] as usize | (body[1] as usize) << 8 | (body[2] as usize) << 16;
            let p0 = tag >> 5;
            if 10 + p0 > body.len() {
                return Some("failed to fill whole buffer".to_string());
            }
            if body.len() < declared {
                return Some("Format error decoding WebP: Corrupt bitstream".to_string());
            }
            return None;
        }
        if t == b"VP8L" {
            let declared = u32::from_le_bytes([d[16], d[17], d[18], d[19]]) as usize;
            if body.len() < declared {
                return Some("Format error decoding WebP: Corrupt bitstream".to_string());
            }
            return None;
        }
    }
    if d.len() < 20 {
        return Some("failed to fill whole buffer".to_string());
    }
    None
}

/// Decode through the generic layer. Errors carry the generic decoder text.
pub fn decode(d: &[u8]) -> Result<Image, String> {
    if !guess_ok(d) {
        return Err("The image format could not be determined".to_string());
    }
    if d.starts_with(&[0x89, b'P', b'N', b'G']) {
        if let Some(e) = png_error(d) {
            return Err(e);
        }
        return super::png::decode(d).map_err(|e| format!("Format error decoding Png: {}", e));
    }
    if d.starts_with(&[0xFF, 0xD8, 0xFF]) {
        if let Some(e) = jpeg_error(d) {
            return Err(e);
        }
        return super::jpeg::decode_image_generic(d).map_err(|_| "Format error decoding Jpeg: I/O errors Generic I/O error: Cannot satisfy read\n".to_string());
    }
    if d.starts_with(b"GIF") {
        if !first_frame_complete_gif(d) {
            if let Some(e) = gif_error(d) {
                return Err(e);
            }
            return Err("Format error decoding Gif: Unexpected End of File".to_string());
        }
        return super::gif::decode_first(d).map_err(|_| "Format error decoding Gif: Unexpected End of File".to_string());
    }
    if &d[0..4] == b"RIFF" {
        if let Some(e) = webp_error(d) {
            return Err(e);
        }
        return super::webp::decode_any(d).ok_or_else(|| "Format error decoding WebP: Corrupt bitstream".to_string());
    }
    Err("The image format could not be determined".to_string())
}

/// Header-only dimension probe.
pub fn probe_size(d: &[u8]) -> Result<(u32, u32), String> {
    const NOT_SUPPORTED: &str = "Could not decode image";
    const CORRUPT: &str = "Hit end of file before finding size";
    const EOF: &str = "failed to fill whole buffer";
    if d.len() >= 3 && d[0..3] == [0xFF, 0xD8, 0xFF] {
        let mut p = 2usize;
        let mut depth = 0i32;
        loop {
            if p + 2 > d.len() {
                return Err(EOF.to_string());
            }
            if d[p] != 0xFF {
                return Err(CORRUPT.to_string());
            }
            let page = d[p + 1];
            p += 2;
            if matches!(page, 0xC0..=0xC3 | 0xC5..=0xC7 | 0xC9..=0xCB | 0xCD..=0xCF) && depth == 0 {
                p += 3;
                if p + 4 > d.len() {
                    return Err(EOF.to_string());
                }
                let h = be16(d, p) as u32;
                let w = be16(d, p + 2) as u32;
                return Ok((w, h));
            } else if page == 0xD8 {
                depth += 1;
            } else if page == 0xD9 {
                depth -= 1;
                if depth < 0 {
                    return Err(CORRUPT.to_string());
                }
            }
            if p + 2 > d.len() {
                return Err(EOF.to_string());
            }
            let size = be16(d, p) as i64;
            let np = p as i64 + size;
            if np < 0 {
                return Err(CORRUPT.to_string());
            }
            p = np as usize;
        }
    }
    if d.len() >= 4 && &d[0..4] == b"\x89PNG" {
        if d.len() < 24 {
            return Err(EOF.to_string());
        }
        let w = u32::from_be_bytes([d[16], d[17], d[18], d[19]]);
        let h = u32::from_be_bytes([d[20], d[21], d[22], d[23]]);
        return Ok((w, h));
    }
    if d.len() >= 6 && (&d[0..6] == b"GIF87a" || &d[0..6] == b"GIF89a") {
        if d.len() < 10 {
            return Err(EOF.to_string());
        }
        return Ok((u16::from_le_bytes([d[6], d[7]]) as u32, u16::from_le_bytes([d[8], d[9]]) as u32));
    }
    if d.len() >= 12 && &d[0..4] == b"RIFF" && &d[8..12] == b"WEBP" {
        if d.len() < 30 {
            return Err(EOF.to_string());
        }
        match &d[12..16] {
            b"VP8 " => {
                let w = (u16::from_le_bytes([d[26], d[27]]) & 0x3FFF) as u32;
