                return Ok((w, h));
            }
            b"VP8L" => {
                let b = u32::from_le_bytes([d[21], d[22], d[23], d[24]]);
                return Ok(((b & 0x3FFF) + 1, ((b >> 14) & 0x3FFF) + 1));
            }
            b"VP8X" => {
                let w = 1 + (d[24] as u32 | (d[25] as u32) << 8 | (d[26] as u32) << 16);
