use codecs::jpeg;
use codecs::jpegenc as je;
fn main() {
    let args: Vec<String> = std::env::args().collect();
    let src = std::fs::read(&args[1]).unwrap();
    let refd = std::fs::read(&args[2]).unwrap();
    let q: i32 = args[3].parse().unwrap();
    let ci: usize = args[4].parse().unwrap();
    let j = jpeg::decode_coefficients(&src).unwrap();
    let r = jpeg::decode_coefficients(&refd).unwrap();
    let planes = jpeg::full_planes(&j);
    let samp: Vec<(usize, usize)> = r.components.iter().map(|c| (c.h, c.v)).collect();
    let ids: Vec<u8> = r.components.iter().map(|c| c.id).collect();
    let opts = je::LossyOptions { quality: q, progressive: true, samp, tqs: vec![0, 1, 1], hts: vec![0, 1, 1], trellis: false, deringing: true };
    let (comps, qt, raws, _) = je::compute_coefficients_dbg(&planes, j.width, j.height, &ids, &opts);
    let t = comps[ci].info.ht;
    let mut g = je::Coder::gatherer();
    je::code_sequential(&comps, &je::Scan::new(&[ci], 0, 63, 0, 0), j.width, j.height, &[t], &[t], &mut g);
    let s_ac = g.counts[t + 2]; let s_dc = g.counts[t];
    let info = comps[ci].info.clone(); let qq = qt[info.tq]; let wb = info.width_in_blocks; let rc = &r.components[ci];
    let cfg = je::TrellisCfg { lambda_log_scale1: 14.75, lambda_log_scale2: 16.5, dc: false };
    let dctbl = je::std_dc_table(t != 0);
    let eval = |acc: &[u32; 257]| -> usize {
        let actbl = je::HuffTable::optimal(acc);
        let mut bad = 0;
        for by in 0..info.height_in_blocks {
            let mut row: Vec<[i16; 64]> = comps[ci].blocks[by * info.bw..by * info.bw + wb].to_vec();
            let mut ld = 0;
            je::quantize_trellis(&cfg, &dctbl, &actbl, &mut row, &raws[ci][by * wb..(by + 1) * wb], &qq, &mut ld, 1, 63);
            for bx in 0..wb { if row[bx][1..] != rc.coefs[by * rc.bw + bx][1..] { bad += 1; } }
        }
        bad
    };
    // shared array: seq AC + seq DC of same component
    let mut res = Vec::new();
    for a in 1..5u32 { for b in 0..9u32 {
        let mut acc = [0u32; 257];
        for k in 0..257 { acc[k] = s_ac[k] * a + s_dc[k] * b; }
        res.push((eval(&acc), a, b));
    }}
    res.sort();
    for x in res.iter().take(6) { println!("bad {} ac*{} dc*{}", x.0, x.1, x.2); }
}
